// ===== 04-mindmap-parser.js =====
// Узел интеллект-карты
class MindMapNode {
    constructor(text) {
        this.text = text;
        this.children = [];
        this.parent = null;
        this.level = 0;
        this.angle = 0;
        this.x = 0; this.y = 0;
        this.weight = 1;
        this.color = '#333';
        this.width = 0; this.height = 30;
        this.done = false;          // флаг выполненности
        this.lines = null;
        this.href = null;           // http(s)/mailto — клик только в PDF
        this.assignee = null;       // @ответственный
        this.initials = null;
        this.deadlineLabel = null;  // !дедлайн
        this.deadlineDate = null;
        this.overdue = false;
        this.note = null;           // // подпись под блоком
        this.sourceLine = null;
    }
}

/** Подпись узла: «Текст // заметка» (пробел перед // обязателен — не путать с http://). */
function extractInlineNodeNote(str) {
    const s = String(str == null ? '' : str);
    const m = s.match(/^(.*?)\s+\/\/\s*(.+)$/);
    if (!m) return { text: s, note: null };
    const note = String(m[2] || '').trim();
    return { text: String(m[1] || '').trim(), note: note || null };
}

// Очистка текста узла от маркеров статуса (единый набор: готово/выполнено/done/ok/…)
function cleanNodeText(str) {
    const extracted = typeof extractInlineNodeNote === 'function'
        ? extractInlineNodeNote(str)
        : { text: str, note: null };
    let base;
    if (typeof parseDiagramDoneMarker === 'function') {
        base = parseDiagramDoneMarker(extracted.text);
    } else {
        let done = false;
        let text = extracted.text;
        const statusMatch = text.match(/Статус:\s*(готово|выполнено)/i);
        if (statusMatch) {
            done = true;
            text = text.replace(/Статус:\s*(готово|выполнено)/i, '').trim();
        }
        if (!done) {
            const suffixMatch = text.match(/\s*[\(\[ ]?(готово|выполнено)[\)\] ]?\s*$/i);
            if (suffixMatch) {
                done = true;
                text = text.replace(/\s*[\(\[ ]?(готово|выполнено)[\)\] ]?\s*$/i, '').trim();
            }
        }
        base = { text, done };
    }
    if (typeof parseDiagramNodeMeta === 'function') {
        const meta = parseDiagramNodeMeta(base.text);
        return {
            text: meta.text,
            done: base.done,
            assignee: meta.assignee,
            initials: meta.initials,
            deadlineLabel: meta.deadlineLabel,
            deadlineDate: meta.deadlineDate,
            overdue: meta.overdue,
            note: extracted.note
        };
    }
    return {
        text: base.text,
        done: base.done,
        assignee: null,
        initials: null,
        deadlineLabel: null,
        deadlineDate: null,
        overdue: false,
        note: extracted.note
    };
}

// Парсинг текста с отступами в дерево.
// Одинаковый отступ — соседи; больший — дети строки выше (и для → Горизонт, и для ↓ Вертикаль).
// Подпись под блоком: «Узел // текст» или отдельная строка «// текст» (как в BPMN).
function parseTree(text, opts) {
    opts = opts || {};
    const clean = text.replace(/·/g, ' ')
                      .replace(/\t/g, '    ');
    const rawLines = clean.split('\n');
    const lines = [];
    rawLines.forEach((l, idx) => {
        const t = l.trim();
        if (!t || t.charAt(0) === '#') return; // # — только файл-комментарий; // обрабатываем ниже
        lines.push({ text: l, line: idx + 1 });
    });
    if (!lines.length) return null;

    const diagnostics = [];

    // Опционально: заголовок: … — метаданные (не корень дерева)
    let startIdx = 0;
    const firstTrim = lines[0].text.trim();
    const titleVal = typeof parseDiagramTitleLine === 'function'
        ? parseDiagramTitleLine(firstTrim)
        : null;
    if (titleVal != null || /^(заголовок|title)\s*:/i.test(firstTrim)) {
        startIdx = 1;
    }
    // Иерархия: направление: вертикаль|горизонт — мета, не узел
    while (startIdx < lines.length
        && /^(направление|direction)\s*:/i.test(lines[startIdx].text.trim())) {
        startIdx++;
    }
    // Пропуск ведущих // до корня
    while (startIdx < lines.length && lines[startIdx].text.trim().slice(0, 2) === '//') {
        startIdx++;
    }
    if (startIdx >= lines.length) return null;

    function applyNoteTo(node, noteText) {
        if (!node || !noteText) return;
        const n = String(noteText).trim();
        if (!n) return;
        node.note = node.note ? (node.note + ' · ' + n) : n;
    }

    // Корень
    const rootClean = cleanNodeText(lines[startIdx].text.trim());
    const rootLink = typeof parseMindmapNodeLink === 'function'
        ? parseMindmapNodeLink(rootClean.text)
        : { text: rootClean.text, href: null };
    const root = new MindMapNode(rootLink.text);
    root.done = rootClean.done;
    root.href = rootLink.href || null;
    root.assignee = rootClean.assignee || null;
    root.initials = rootClean.initials || null;
    root.deadlineLabel = rootClean.deadlineLabel || null;
    root.deadlineDate = rootClean.deadlineDate || null;
    root.overdue = !!rootClean.overdue;
    root.note = rootClean.note || null;
    root.sourceLine = lines[startIdx].line;
    root.level = 0;
    if (titleVal) root.diagramTitle = titleVal;

    let lastNode = root;
    const stack = [{ indent: 0, node: root }];
    for (let i = startIdx + 1; i < lines.length; i++) {
        const line = lines[i].text;
        const lineNo = lines[i].line;
        const trimmed = line.trim();
        if (!trimmed) continue;

        if (trimmed.slice(0, 2) === '//') {
            applyNoteTo(lastNode, trimmed.slice(2));
            continue;
        }

        const indent = line.match(/^[ ]*/)[0].length;
        if (indent % 4 !== 0) {
            diagnostics.push(diag('warning', `Отступ ${indent} пробелов — лучше кратно 4`, {
                line: lineNo,
                code: 'indent_not_multiple',
                hint: 'Используйте таб или 4 пробела на уровень'
            }));
        }
        const cleaned = cleanNodeText(trimmed);
        const linked = typeof parseMindmapNodeLink === 'function'
            ? parseMindmapNodeLink(cleaned.text)
            : { text: cleaned.text, href: null };
        const nodeText = linked.text;
        const nodeDone = cleaned.done;
        if (!nodeText) {
            diagnostics.push(diag('warning', 'Пустой узел пропущен', {
                line: lineNo,
                code: 'empty_node',
                hint: 'После маркера (готово) должно остаться имя'
            }));
            continue;
        }
        const node = new MindMapNode(nodeText);
        node.done = nodeDone;
        node.href = linked.href || null;
        node.assignee = cleaned.assignee || null;
        node.initials = cleaned.initials || null;
        node.deadlineLabel = cleaned.deadlineLabel || null;
        node.deadlineDate = cleaned.deadlineDate || null;
        node.overdue = !!cleaned.overdue;
        node.note = cleaned.note || null;
        node.sourceLine = lineNo;

        while (stack.length > 0 && stack[stack.length - 1].indent >= indent) stack.pop();
        const parent = stack.length === 0 ? root : stack[stack.length - 1].node;
        stack.push({ indent, node });

        parent.children.push(node);
        node.parent = parent;
        node.level = (parent.level || 0) + 1;
        lastNode = node;
    }
    if (diagnostics.length && typeof attachDiagnostics === 'function') {
        attachDiagnostics(root, diagnostics);
    } else {
        root.diagnostics = diagnostics;
    }
    return root;
}

// Назначение цветов узлам
function assignColors(root, theme) {
    const palette = themes[theme];
    root.children.forEach((child, i) => {
        const color = palette[i % palette.length];
        setSubtreeColor(child, color);
    });
    root.color = '#666666';
}
function setSubtreeColor(node, branchColor) {
    const isDark = typeof document !== 'undefined' && document.body && document.body.classList.contains('dark');
    const fadeToward = isDark ? '#0f172a' : '#f1f5f9';
    // Плавное снижение яркости от ветки корня к листьям (мягко, без потери узнаваемости цвета)
    const depth = Math.max(0, (node.level || 1) - 1);
    const t = Math.min(0.36, depth * 0.11);
    node.color = (t <= 0.001 || typeof mixHex !== 'function')
        ? branchColor
        : mixHex(branchColor, fadeToward, t);
    node.children.forEach((ch) => setSubtreeColor(ch, branchColor));
}

;

// ===== 05-diagram-spacing.js =====
/**
 * Плотность древовидных диаграмм: classic, radial, horizontal.
 */
const TREE_SPACING_LAYOUTS = ['classic', 'radial', 'horizontal'];
const TREE_SPACING_MIN = 0.5;
const RADIAL_SPACING_MIN = 0.75;
const TREE_SPACING_MAX = 2;
const TREE_SPACING_PRESETS = {
    compact: 0.75,
    normal: 1,
    spacious: 1.45
};
const TREE_SPACING_DEFAULTS = {
    radial: TREE_SPACING_PRESETS.normal,
    horizontal: TREE_SPACING_PRESETS.compact,
    classic: TREE_SPACING_PRESETS.compact
};

const CLASSIC_GAP_X = 190;
const CLASSIC_GAP_Y = 28;
const RADIAL_RADIUS_PER_LEVEL = 200;
const HORIZONTAL_GAP_X = 200;
const HORIZONTAL_GAP_Y = 40;
const HORIZONTAL_ORIGIN_X = 60;
const HORIZONTAL_ORIGIN_Y = 60;
const VERTICAL_PHASE_GAP_X = 44;
const VERTICAL_GAP_Y = 30;
const VERTICAL_NEST_GAP_X = 18;

function clampTreeSpacingScale(scale) {
    const n = Number(scale);
    if (!Number.isFinite(n)) return 1;
    return Math.min(TREE_SPACING_MAX, Math.max(TREE_SPACING_MIN, n));
}

function getTreeSpacingMin(layout) {
    return layout === 'radial' ? RADIAL_SPACING_MIN : TREE_SPACING_MIN;
}

function getEffectiveTreeSpacingScale(layout, scale) {
    const s = clampTreeSpacingScale(scale == null ? getTreeSpacingScale() : scale);
    return Math.max(getTreeSpacingMin(layout), s);
}

function getTreeSpacingSliderMinPct(layout) {
    return Math.round(getTreeSpacingMin(layout) * 100);
}

function createDefaultTreeSpacingScales() {
    return {
        radial: TREE_SPACING_DEFAULTS.radial,
        horizontal: TREE_SPACING_DEFAULTS.horizontal,
        classic: TREE_SPACING_DEFAULTS.classic
    };
}

function getDefaultTreeSpacingScale(layout) {
    if (layout === 'classic') return TREE_SPACING_DEFAULTS.classic;
    if (layout === 'horizontal') return TREE_SPACING_DEFAULTS.horizontal;
    return TREE_SPACING_DEFAULTS.radial;
}

function normalizeTreeSpacingScales(scales) {
    const out = createDefaultTreeSpacingScales();
    if (!scales || typeof scales !== 'object') return out;
    TREE_SPACING_LAYOUTS.forEach((layout) => {
        if (typeof scales[layout] === 'number' && Number.isFinite(scales[layout])) {
            out[layout] = clampTreeSpacingScale(scales[layout]);
        }
    });
    return out;
}

function readTreeSpacingScales() {
    if (typeof treeSpacingScales !== 'undefined' && treeSpacingScales) {
        return normalizeTreeSpacingScales(treeSpacingScales);
    }
    const legacy = (typeof treeSpacingScale !== 'undefined')
        ? treeSpacingScale
        : ((typeof classicSpacingScale !== 'undefined') ? classicSpacingScale : null);
    if (typeof legacy === 'number' && Number.isFinite(legacy)) {
        const s = clampTreeSpacingScale(legacy);
        return { radial: s, horizontal: s, classic: s };
    }
    return createDefaultTreeSpacingScales();
}

function getTreeSpacingScale(layout) {
    const key = layout || (typeof currentLayout !== 'undefined' ? currentLayout : 'radial');
    const scales = readTreeSpacingScales();
    if (isTreeSpacingLayout(key) && typeof scales[key] === 'number') {
        return clampTreeSpacingScale(scales[key]);
    }
    return getDefaultTreeSpacingScale(key);
}

function setTreeSpacingScaleForLayout(layout, scale) {
    if (!isTreeSpacingLayout(layout)) return getTreeSpacingScale(layout);
    const next = clampTreeSpacingScale(scale);
    const scales = readTreeSpacingScales();
    scales[layout] = next;
    try {
        if (typeof treeSpacingScales !== 'undefined') treeSpacingScales = scales;
        if (typeof syncTreeSpacingGlobals === 'function') syncTreeSpacingGlobals();
    } catch (_) { /* ignore */ }
    return next;
}

function syncTreeSpacingGlobals() {
    const scales = readTreeSpacingScales();
    try {
        window.treeSpacingScales = scales;
        const layout = (typeof currentLayout !== 'undefined') ? currentLayout : 'radial';
        window.treeSpacingScale = getTreeSpacingScale(layout);
        window.classicSpacingScale = getTreeSpacingScale('classic');
    } catch (_) { /* ignore */ }
}

function treeSpacingPresetForScale(scale) {
    const s = clampTreeSpacingScale(scale);
    let best = 'normal';
    let bestDiff = Infinity;
    Object.keys(TREE_SPACING_PRESETS).forEach((key) => {
        const diff = Math.abs(TREE_SPACING_PRESETS[key] - s);
        if (diff < bestDiff) {
            bestDiff = diff;
            best = key;
        }
    });
    return bestDiff <= 0.06 ? best : '';
}

function isTreeSpacingLayout(layout) {
    return TREE_SPACING_LAYOUTS.indexOf(layout) !== -1;
}

function getClassicLayoutGaps(scale) {
    const s = clampTreeSpacingScale(scale == null ? getTreeSpacingScale('classic') : scale);
    return {
        scale: s,
        gapX: CLASSIC_GAP_X * s,
        gapY: CLASSIC_GAP_Y * s
    };
}

function getRadialLayoutRadius(scale) {
    const s = getEffectiveTreeSpacingScale('radial', scale);
    return RADIAL_RADIUS_PER_LEVEL * s;
}

function getHorizontalLayoutGaps(scale, direction) {
    const s = clampTreeSpacingScale(scale == null ? getTreeSpacingScale('horizontal') : scale);
    if (direction === 'tb') {
        return {
            scale: s,
            originX: HORIZONTAL_ORIGIN_X,
            originY: HORIZONTAL_ORIGIN_Y,
            phaseGapX: VERTICAL_PHASE_GAP_X * s,
            gapY: VERTICAL_GAP_Y * s,
            nestGapX: VERTICAL_NEST_GAP_X * s
        };
    }
    return {
        scale: s,
        originX: HORIZONTAL_ORIGIN_X,
        originY: HORIZONTAL_ORIGIN_Y,
        gapX: HORIZONTAL_GAP_X * s,
        gapY: HORIZONTAL_GAP_Y * s
    };
}

// Совместимость с предыдущим API
function clampClassicSpacingScale(scale) { return clampTreeSpacingScale(scale); }
function getClassicSpacingScale() { return getTreeSpacingScale('classic'); }
function classicSpacingPresetForScale(scale) { return treeSpacingPresetForScale(scale); }
const CLASSIC_SPACING_PRESETS = TREE_SPACING_PRESETS;

;

// ===== 06-layout-radial.js =====
// Вычисление весов поддеревьев
function computeWeights(node) {
    let w = 1;
    for (const child of node.children) { computeWeights(child); w += child.weight; }
    node.weight = w;
}

// Радиальная компоновка
function layoutRadial(node, startAngle, endAngle, level, radiusPerLevel = 200) {
    node.level = level;
    node.angle = (startAngle + endAngle) / 2;
    if (level === 0) { node.x = 0; node.y = 0; }
    else {
        const r = level * radiusPerLevel;
        node.x = r * Math.cos(node.angle);
        node.y = r * Math.sin(node.angle);
    }
    if (node.children.length === 0) return;
    const MIN_ANGLE = (20 * Math.PI) / 180;
    const availableAngle = endAngle - startAngle;
    if (node.children.length === 1) {
        const child = node.children[0];
        const span = Math.min(availableAngle, MIN_ANGLE);
        layoutRadial(child, node.angle - span/2, node.angle + span/2, level+1, radiusPerLevel);
        return;
    }
    const totalWeight = node.children.reduce((sum,ch) => sum+ch.weight, 0);
    let currentAngle = startAngle;
    const angles = [];
    for (let i=0; i<node.children.length; i++) {
        const child = node.children[i];
        let span = (child.weight / totalWeight) * availableAngle;
        if (i < node.children.length-1) span = Math.max(span, MIN_ANGLE);
        if (currentAngle + span > endAngle) span = endAngle - currentAngle;
        angles.push(span);
        currentAngle += span;
    }
    const sumAngles = angles.reduce((s,a)=>s+a,0);
    if (sumAngles < availableAngle) angles[angles.length-1] += availableAngle - sumAngles;
    currentAngle = startAngle;
    for (let i=0; i<node.children.length; i++) {
        layoutRadial(node.children[i], currentAngle, currentAngle+angles[i], level+1, radiusPerLevel);
        currentAngle += angles[i];
    }
}

// Разрешение наложений в радиальной схеме
function resolveOverlapsRadial(root) {
    const allNodes = [];
    (function collect(n){ allNodes.push(n); n.children.forEach(collect); })(root);
    const layoutH = (n) => (typeof diagramNodeLayoutHeight === 'function'
        ? diagramNodeLayoutHeight(n)
        : (n.height || 0));
    let moved = true;
    const maxIters = 100;
    let iter = 0;
    while (moved && iter < maxIters) {
        moved = false;
        for (let i=0; i<allNodes.length; i++) {
            for (let j=i+1; j<allNodes.length; j++) {
                const a = allNodes[i], b = allNodes[j];
                if (a===b) continue;
                const aH = layoutH(a), bH = layoutH(b);
                // Слот = блок + зона //; y — центр слота
                const ax1 = a.x-a.width/2, ax2 = a.x+a.width/2;
                const ay1 = a.y-aH/2, ay2 = a.y+aH/2;
                const bx1 = b.x-b.width/2, bx2 = b.x+b.width/2;
                const by1 = b.y-bH/2, by2 = b.y+bH/2;
                // Simmetrika: kept apart by the margins too (only overlapping boxes were moved,
                // so nodes stayed touching — branches read as one blob).
                if (ax1 - 10 < bx2 && ax2 + 10 > bx1 && ay1 - 12 < by2 && ay2 + 12 > by1) {
                    const dx = b.x-a.x, dy = b.y-a.y, dist = Math.hypot(dx,dy)||1;
                    const minDistX = (a.width+b.width)/2 + 16;
                    const minDistY = (aH + bH)/2 + 14;
                    const overlapX = minDistX - Math.abs(dx);
                    const overlapY = minDistY - Math.abs(dy);
                    if (overlapX > 0 && overlapY > 0) {
                        const useY = overlapY <= overlapX;
                        const shift = (useY ? overlapY : overlapX) / 2 + 1;
                        if (useY) {
                            const sy = dy >= 0 ? 1 : -1;
                            a.y -= sy * shift;
                            b.y += sy * shift;
                        } else {
                            const sx = dx >= 0 ? 1 : -1;
                            a.x -= sx * shift;
                            b.x += sx * shift;
                        }
                        moved = true;
                    }
                }
            }
        }
        iter++;
    }
    function recalcAngles(n) {
        if (n.parent) { const dx=n.x-n.parent.x, dy=n.y-n.parent.y; n.angle = Math.atan2(dy,dx); }
        n.children.forEach(recalcAngles);
    }
    recalcAngles(root);
}
;

// ===== 07-layout-horizontal.js =====
function nodeLayoutH(node) {
    return typeof diagramNodeLayoutHeight === 'function'
        ? diagramNodeLayoutHeight(node)
        : (node.height || 0);
}

// Иерархическая компоновка: слева направо
function layoutHorizontal(node, x, y, gapX = 200, gapY = 40, cols = null, depth = 0) {
    // Simmetrika: columns as wide as their widest node (a fixed step let a long name,
    // «Группа рисков №1», run under the next column).
    if (!cols) {
        const widest = [];
        (function walk(n, d) {
            widest[d] = Math.max(widest[d] || 0, n.width || 0);
            for (const c of n.children) walk(c, d + 1);
        })(node, 0);
        cols = [x];
        for (let d = 1; d < widest.length; d++) cols[d] = cols[d - 1] + Math.max(gapX, widest[d - 1] + 48);
    }
    x = cols[depth];
    if (node.children.length === 0) {
        node.x = x; node.y = y;
        return nodeLayoutH(node) + gapY;
    }
    let childY = y;
    for (const child of node.children) {
        const childH = layoutHorizontal(child, x + gapX, childY, gapX, gapY, cols, depth + 1);
        childY += childH;
    }
    const first = node.children[0], last = node.children[node.children.length - 1];
    node.x = x;
    node.y = (first.y + first.height / 2 + last.y + last.height / 2) / 2 - node.height / 2;
    return childY - y;
}

/**
 * ↓ Вертикаль:
 *  — дети корня (фазы) — столбцы слева направо;
 *  — внутри фазы / любой не-корневой узел: дети столбиком сверху вниз
 *    (соседи с одним отступом идут друг за другом; больший отступ —
 *    ветка от предшествующей строки, уже заложена в parseTree).
 * Возвращает { width, height } поддерева.
 */
function layoutVerticalColumn(node, leftX, topY, nestGapX = 18, gapY = 30, depth = 0) {
    node.x = leftX;
    node.y = topY;

    const selfH = nodeLayoutH(node);
    if (!node.children.length) {
        return { width: node.width, height: selfH };
    }

    // Глубже — чуть меньше сдвиг вправо (экономия ширины колонок)
    const indent = Math.max(12, Math.round(nestGapX * Math.pow(0.84, Math.min(depth, 5))));
    const childLeft = leftX + indent;
    // После родителя — полный gap; между листьями — плотнее
    const afterParentGap = Math.max(14, Math.round(gapY * 0.9));
    const leafSiblingGap = Math.max(8, Math.round(gapY * 0.48));
    const branchSiblingGap = Math.max(12, Math.round(gapY * 0.72));

    let y = topY + selfH + afterParentGap;
    let maxW = node.width;
    const kids = node.children;

    for (let i = 0; i < kids.length; i++) {
        const child = kids[i];
        const sub = layoutVerticalColumn(child, childLeft, y, nestGapX, gapY, depth + 1);
        maxW = Math.max(maxW, (childLeft - leftX) + sub.width);
        if (i < kids.length - 1) {
            const next = kids[i + 1];
            const eitherHasKids = !!(child.children && child.children.length)
                || !!(next.children && next.children.length);
            y += sub.height + (eitherHasKids ? branchSiblingGap : leafSiblingGap);
        } else {
            y += sub.height;
        }
    }

    return { width: maxW, height: y - topY };
}

function layoutVertical(root, originX = 60, originY = 60, phaseGapX = 44, gapY = 30, nestGapX = 18) {
    root.x = originX;
    root.y = originY;

    if (!root.children.length) {
        return root.width;
    }

    const phaseTop = originY + nodeLayoutH(root) + Math.max(18, Math.round(gapY * 0.95));
    let x = originX;
    const phaseWidths = [];

    for (const phase of root.children) {
        const sub = layoutVerticalColumn(phase, x, phaseTop, nestGapX, gapY, 0);
        phaseWidths.push({ phase, x, width: sub.width });
        x += sub.width + phaseGapX;
    }

    const totalW = x - phaseGapX - originX;
    root.x = originX + Math.max(0, (totalW - root.width) / 2);
    return totalW;
}

// Разрешение наложений по вертикали (для L→R)
function resolveOverlapsHorizontal(root) {
    const levels = {};
    (function group(n) {
        if (!levels[n.level]) levels[n.level] = [];
        levels[n.level].push(n);
        n.children.forEach(group);
    })(root);
    const MIN_GAP = 12;
    for (const lvl in levels) {
        if (lvl == 0) continue;
        const nodes = levels[lvl].sort((a, b) => a.y - b.y);
        for (let i = 1; i < nodes.length; i++) {
            const prev = nodes[i - 1], curr = nodes[i];
            const overlap = prev.y + nodeLayoutH(prev) + MIN_GAP - curr.y;
            if (overlap > 0) shiftSubtreeY(curr, overlap);
        }
    }
}

/**
 * ↓ Вертикаль: фазы не должны пересекаться по X;
 * внутри столбца — по Y (соседи / вложенные).
 */
function resolveOverlapsVertical(root) {
    const MIN_GAP_X = 28;
    const MIN_GAP_Y = 10;

    // Фазы (дети корня) — развести по X
    if (root.children && root.children.length > 1) {
        const phases = root.children.slice().sort((a, b) => a.x - b.x);
        for (let i = 1; i < phases.length; i++) {
            const prev = phases[i - 1];
            const curr = phases[i];
            const prevRight = subtreeMaxX(prev);
            const overlap = prevRight + MIN_GAP_X - curr.x;
            if (overlap > 0) shiftSubtreeX(curr, overlap);
        }
    }

    // Внутри каждого поддерева — развести по Y при наложении
    function fixColumn(node) {
        if (!node.children.length) return;
        const kids = node.children.slice().sort((a, b) => a.y - b.y);
        for (let i = 1; i < kids.length; i++) {
            const prev = kids[i - 1];
            const curr = kids[i];
            const prevBottom = subtreeMaxY(prev);
            const overlap = prevBottom + MIN_GAP_Y - curr.y;
            if (overlap > 0) shiftSubtreeY(curr, overlap);
        }
        node.children.forEach(fixColumn);
    }
    root.children.forEach(fixColumn);
}

function subtreeMaxX(node) {
    let max = node.x + node.width;
    for (const ch of node.children) max = Math.max(max, subtreeMaxX(ch));
    return max;
}

function subtreeMaxY(node) {
    let max = node.y + nodeLayoutH(node);
    for (const ch of node.children) max = Math.max(max, subtreeMaxY(ch));
    return max;
}

;

// ===== 08-layout-classic.js =====
// Классическая интеллект-карта: корень в центре, основные ветки влево и вправо

function classicNodeH(node) {
    return typeof diagramNodeLayoutHeight === 'function'
        ? diagramNodeLayoutHeight(node)
        : (node.height || 0);
}

function measureClassicSubtree(node, gapY) {
    const selfH = classicNodeH(node);
    if (!node.children.length) {
        node._classicH = selfH;
        return selfH;
    }
    let total = 0;
    for (let i = 0; i < node.children.length; i++) {
        total += measureClassicSubtree(node.children[i], gapY);
        if (i < node.children.length - 1) total += gapY;
    }
    node._classicH = Math.max(selfH, total);
    return node._classicH;
}

function layoutClassicSubtree(node, x, y, dir, level, gapX, gapY) {
    node.x = x;
    node.y = y;
    node.level = level;
    node.side = dir < 0 ? 'left' : 'right';

    if (!node.children.length) return;

    const kids = node.children;
    const blockH = kids.reduce((s, c) => s + c._classicH, 0) + gapY * Math.max(0, kids.length - 1);
    let childY = y - blockH / 2;

    for (const child of kids) {
        const childX = x + dir * (node.width / 2 + gapX + child.width / 2);
        const cy = childY + child._classicH / 2;
        layoutClassicSubtree(child, childX, cy, dir, level + 1, gapX, gapY);
        childY += child._classicH + gapY;
    }
}

function placeClassicSide(kids, root, level, gapX, gapY, dir) {
    if (!kids.length) return;
    const totalH = kids.reduce((s, c) => s + c._classicH, 0) + gapY * Math.max(0, kids.length - 1);
    let y = -totalH / 2;
    for (const child of kids) {
        const x = dir * (root.width / 2 + gapX + child.width / 2);
        const cy = y + child._classicH / 2;
        layoutClassicSubtree(child, x, cy, dir, level, gapX, gapY);
        y += child._classicH + gapY;
    }
}

function layoutClassic(root, gapX, gapY) {
    const gx = gapX == null ? 190 : gapX;
    const gy = gapY == null ? 28 : gapY;
    root.x = 0;
    root.y = 0;
    root.level = 0;

    const kids = root.children;
    if (!kids.length) return;

    const rightCount = Math.ceil(kids.length / 2);
    const rightKids = kids.slice(0, rightCount);
    const leftKids = kids.slice(rightCount);

    rightKids.forEach((c) => measureClassicSubtree(c, gy));
    leftKids.forEach((c) => measureClassicSubtree(c, gy));

    placeClassicSide(rightKids, root, 1, gx, gy, 1);
    placeClassicSide(leftKids, root, 1, gx, gy, -1);
}

function resolveOverlapsClassic(root) {
    if (typeof resolveOverlapsRadial === 'function') resolveOverlapsRadial(root);
}

;

