// ===== 42-parser-timeline.js =====
/**
 * Парсер лёгкого таймлайна (референс: Mermaid timeline).
 *
 * название: Roadmap 2026
 * направление: вправо   // primary: вниз|вправо; aliases: вертикально/горизонтально/vertical/horizontal/td/tb/lr/rl/down/right
 * чередовать            // блоки по разные стороны оси — на текущий ряд
 * раздел: Исследование
 * Июль: Интервью
 *
 * Второй «название:» — новый ряд; направление/чередовать задаются отдельно на каждый ряд.
 */
function parseTimeline(text) {
    const diagnostics = [];
    const tracks = [];
    let currentTrack = null;
    let currentSection = null;
    let lastPeriod = null;

    function trackHasPeriods(track) {
        if (!track || !track.sections) return false;
        return track.sections.some((s) => s.periods && s.periods.length);
    }

    function flushSectionIntoTrack() {
        if (!currentTrack || !currentSection) return;
        if (currentSection.periods.length && !currentTrack.sections.includes(currentSection)) {
            currentTrack.sections.push(currentSection);
        }
    }

    function startTrack(title) {
        flushSectionIntoTrack();
        if (currentTrack && trackHasPeriods(currentTrack)) {
            tracks.push(currentTrack);
        }
        currentTrack = {
            title: title || 'Таймлайн',
            sections: [],
            direction: 'lr',
            alternate: false
        };
        currentSection = { name: '', periods: [] };
        lastPeriod = null;
    }

    function ensureTrack() {
        if (!currentTrack) startTrack('Таймлайн');
        return currentTrack;
    }

    function ensureSection() {
        ensureTrack();
        if (!currentSection) {
            currentSection = { name: '', periods: [] };
        }
        if (!currentTrack.sections.includes(currentSection)) {
            currentTrack.sections.push(currentSection);
        }
        return currentSection;
    }

    function parseDirectionValue(raw, lineNo) {
        // Prefix match (no $): вниз→tb, вправо→lr; aliases вертикально/горизонтально/…
        const d = String(raw || '').trim().toLowerCase();
        if (/^(вправо|горизонт|horizontal|lr|rl|right)/i.test(d)) return 'lr';
        if (/^(вниз|вертикал|vertical|td|tb|down)/i.test(d)) return 'tb';
        diagnostics.push(diag('warning', 'Направление: вниз или вправо', {
            line: lineNo, code: 'timeline_bad_direction',
            hint: 'направление: вниз | вправо'
        }));
        return null;
    }

    String(text || '').replace(/\r\n?/g, '\n').split('\n').forEach((raw, idx) => {
        const lineNo = idx + 1;
        const trimmed = raw.trim();
        if (typeof isDiagramCommentLine === 'function'
            ? isDiagramCommentLine(trimmed)
            : (!trimmed || trimmed.startsWith('#') || trimmed.startsWith('//'))) return;

        if (/^(таймлайн|timeline)\s*$/i.test(trimmed)) return;

        if (/^(чередовать|alternate|zigzag)\s*$/i.test(trimmed)) {
            ensureTrack().alternate = true;
            return;
        }
        const altM = trimmed.match(/^(чередовать|alternate|zigzag)\s*:\s*(.+)$/i);
        if (altM) {
            const v = String(altM[2] || '').trim().toLowerCase();
            ensureTrack().alternate = !/^(нет|no|false|0|off|выкл)/i.test(v);
            return;
        }

        const dirM = trimmed.match(/^(направление|direction)\s*:\s*(.+)$/i);
        if (dirM) {
            const next = parseDirectionValue(dirM[2], lineNo);
            if (next) ensureTrack().direction = next;
            return;
        }

        const titleVal = typeof parseDiagramTitleLine === 'function'
            ? parseDiagramTitleLine(trimmed)
            : null;
        if (titleVal != null || /^(заголовок|title)\s*:/i.test(trimmed)) {
            let name = titleVal;
            if (!name) {
                const m = trimmed.match(/^(заголовок|title)\s*:\s*(.*)$/i);
                name = m ? String(m[2] || '').trim() : '';
            }
            name = name || 'Таймлайн';
            if (currentTrack && trackHasPeriods(currentTrack)) {
                startTrack(name);
            } else if (!currentTrack) {
                startTrack(name);
            } else {
                currentTrack.title = name;
            }
            return;
        }

        const secM = trimmed.match(/^(раздел|section|секция)\s*:?\s*(.*)$/i);
        if (secM) {
            ensureTrack();
            flushSectionIntoTrack();
            const name = String(secM[2] || '').trim() || 'Раздел';
            currentSection = { name, periods: [] };
            currentTrack.sections.push(currentSection);
            lastPeriod = null;
            return;
        }

        const contM = trimmed.match(/^:\s*(.+)$/);
        if (contM && lastPeriod) {
            lastPeriod.events.push(contM[1].trim());
            return;
        }

        const colon = trimmed.indexOf(':');
        if (colon > 0) {
            const period = trimmed.slice(0, colon).trim();
            const rest = trimmed.slice(colon + 1).trim();
            if (/^(название|заголовок|title|раздел|section|секция|направление|direction|чередовать|alternate|zigzag)$/i.test(period)) {
                return;
            }
            const events = rest
                ? rest.split(/\s*:\s*/).map((e) => e.trim()).filter(Boolean)
                : [];
            if (!events.length) {
                diagnostics.push(diag('warning', 'У периода нет события', {
                    line: lineNo, code: 'timeline_empty_events',
                    hint: 'Июль: Интервью'
                }));
            }
            ensureSection();
            lastPeriod = { period, events, line: lineNo };
            currentSection.periods.push(lastPeriod);
            return;
        }

        diagnostics.push(diag('warning', 'Строка не распознана', {
            line: lineNo, code: 'timeline_bad_line',
            hint: 'раздел: Запуск   или   Октябрь: Релиз'
        }));
    });

    flushSectionIntoTrack();
    if (currentTrack && trackHasPeriods(currentTrack)) {
        tracks.push(currentTrack);
    }

    if (!tracks.length) {
        return attachDiagnostics(null, diagnostics);
    }

    return attachDiagnostics({
        title: tracks[0].title,
        sections: tracks[0].sections,
        tracks,
        // совместимость: направление первого ряда
        direction: tracks[0].direction || 'lr',
        alternate: !!tracks[0].alternate
    }, diagnostics);
}

;

// ===== 43-layout-timeline.js =====
/**
 * Компоновка таймлайна.
 * direction: lr — горизонтальная ось; tb — вертикальная.
 * alternate: карточки по разные стороны оси.
 */
function layoutTimeline(data, options) {
    options = options || {};
    const tracksIn = (data && data.tracks && data.tracks.length)
        ? data.tracks
        : (data && data.sections && data.sections.length
            ? [{ title: data.title || '', sections: data.sections }]
            : []);
    if (!tracksIn.length) {
        return {
            tracks: [], sections: [], width: 0, height: 0, title: '',
            direction: 'lr', alternate: false
        };
    }

    const direction = (options.direction || data.direction || 'lr') === 'tb' ? 'tb' : 'lr';
    const alternate = !!(options.alternate != null ? options.alternate : data.alternate);

    const fontFam = (typeof getUiFontFamily === 'function')
        ? getUiFontFamily()
        : 'system-ui, sans-serif';
    const padL = 36;
    const padR = 36;
    const topTitleGap = 36;
    const rowGap = 48;
    const periodGap = 28;
    const cardMinW = 120;
    const cardMaxW = 180;
    const cardGapFromAxis = 14;

    function measure(str, size, weight) {
        const s = String(str || '');
        if (typeof document !== 'undefined') {
            const c = layoutTimeline._c || (layoutTimeline._c = document.createElement('canvas'));
            const ctx = c.getContext('2d');
            ctx.font = (weight || '600') + ' ' + size + 'px ' + fontFam;
            return ctx.measureText(s).width;
        }
        return s.length * size * 0.55;
    }

    function enrichPeriod(p) {
        const events = (p.events || []).map((ev) => {
            const lines = (typeof wrapTextLines === 'function')
                ? wrapTextLines(ev, cardMaxW - 16, 12, fontFam)
                : [ev];
            return { text: ev, lines };
        });
        const periodLines = (typeof wrapTextLines === 'function')
            ? wrapTextLines(p.period, cardMaxW - 16, 13, fontFam)
            : [p.period];
        const contentW = Math.max(
            measure(p.period, 13, '700'),
            ...events.flatMap((e) => e.lines.map((l) => measure(l, 12, '500'))),
            60
        );
        const width = Math.min(cardMaxW, Math.max(cardMinW, contentW + 20));
        const eventsH = events.reduce((h, e) => h + e.lines.length * 15 + 8, 0);
        return {
            period: p.period,
            periodLines,
            events,
            width,
            height: 28 + periodLines.length * 16 + eventsH,
            line: p.line
        };
    }

    function layoutOneTrackHorizontal(track, originY, alt) {
        const title = track.title || '';
        const titleBand = title ? 28 : 0;
        const padT = originY + titleBand;

        const sections = (track.sections || []).map((sec) => ({
            name: sec.name || '',
            periods: (sec.periods || []).map(enrichPeriod)
        }));

        let x = padL;
        let maxCardH = 0;
        let maxAbove = 0;
        const hasSectionLabels = sections.some((s) => s.name);
        const sectionBand = hasSectionLabels ? 28 : 0;
        const axisY = padT + sectionBand + 18;
        let globalIdx = 0;

        sections.forEach((sec) => {
            sec.x = x;
            sec.periods.forEach((p) => {
                const side = alt ? ((globalIdx % 2 === 0) ? 1 : -1) : 1;
                p.side = side;
                p.x = x;
                if (side > 0) {
                    p.y = axisY + cardGapFromAxis + 6;
                    maxCardH = Math.max(maxCardH, p.height);
                } else {
                    p.y = axisY - cardGapFromAxis - 6 - p.height;
                    maxAbove = Math.max(maxAbove, p.height);
                }
                x += p.width + periodGap;
                globalIdx += 1;
            });
            sec.width = sec.periods.length
                ? (sec.periods[sec.periods.length - 1].x + sec.periods[sec.periods.length - 1].width - sec.x)
                : 0;
        });

        let shift = 0;
        if (maxAbove > 0) {
            shift = maxAbove + cardGapFromAxis;
            sections.forEach((sec) => {
                sec.periods.forEach((p) => { p.y += shift; });
            });
        }
        const axisYFinal = axisY + shift;
        const width = Math.max(360, x - periodGap + padR);
        const bottomBelow = axisYFinal + cardGapFromAxis + 6 + maxCardH + 24;
        const bottom = Math.max(bottomBelow, originY + titleBand + sectionBand + 40);
        return {
            title,
            titleY: originY + 18,
            sections,
            axisY: axisYFinal,
            axisOrientation: 'lr',
            direction: 'lr',
            alternate: !!alt,
            width,
            height: bottom - originY,
            bottom,
            hasSectionLabels
        };
    }

    function layoutOneTrackVertical(track, originY, alt) {
        const title = track.title || '';
        const titleBand = title ? 32 : 0;
        const sections = (track.sections || []).map((sec) => ({
            name: sec.name || '',
            periods: (sec.periods || []).map(enrichPeriod)
        }));

        const hasSectionLabels = sections.some((s) => s.name);
        const axisX = alt ? 280 : 160;
        let y = originY + titleBand + 12;
        let globalIdx = 0;
        let maxRight = axisX;
        let minLeft = axisX;

        sections.forEach((sec) => {
            if (sec.name) {
                sec.labelY = y + 4;
                sec.axisX = axisX;
                y += 22;
            }
            sec.periods.forEach((p) => {
                const side = alt ? ((globalIdx % 2 === 0) ? 1 : -1) : 1;
                p.side = side;
                p.cy = y + p.height / 2;
                if (side > 0) {
                    p.x = axisX + cardGapFromAxis + 8;
                    p.y = y;
                    maxRight = Math.max(maxRight, p.x + p.width);
                } else {
                    p.x = axisX - cardGapFromAxis - 8 - p.width;
                    p.y = y;
                    minLeft = Math.min(minLeft, p.x);
                }
                y += p.height + periodGap;
                globalIdx += 1;
            });
        });

        let shiftX = 0;
        if (minLeft < padL) {
            shiftX = padL - minLeft;
        }
        const axisXFinal = axisX + shiftX;
        sections.forEach((sec) => {
            sec.axisX = axisXFinal;
            sec.periods.forEach((p) => { p.x += shiftX; });
        });

        const width = Math.max(360, maxRight + shiftX + padR);
        const bottom = y + 16;
        return {
            title,
            titleY: originY + 18,
            sections,
            axisX: axisXFinal,
            axisOrientation: 'tb',
            direction: 'tb',
            alternate: !!alt,
            width,
            height: bottom - originY,
            bottom,
            hasSectionLabels
        };
    }

    let y = topTitleGap;
    let maxW = 360;
    const tracks = [];
    tracksIn.forEach((tr, i) => {
        if (i > 0) y += rowGap;
        const trackDir = (tr.direction || direction) === 'tb' ? 'tb' : 'lr';
        const trackAlt = tr.alternate != null ? !!tr.alternate : alternate;
        const laid = trackDir === 'tb'
            ? layoutOneTrackVertical(tr, y, trackAlt)
            : layoutOneTrackHorizontal(tr, y, trackAlt);
        tracks.push(laid);
        maxW = Math.max(maxW, laid.width);
        y = laid.bottom;
    });

    const height = y + 16;
    const first = tracks[0];
    return {
        title: first.title || data.title || '',
        sections: first.sections,
        axisY: first.axisY,
        axisX: first.axisX,
        hasSectionLabels: first.hasSectionLabels,
        tracks,
        direction: first.direction || direction,
        alternate: !!first.alternate,
        width: Math.ceil(maxW),
        height: Math.ceil(height)
    };
}

;

// ===== 44-parser-rollout.js =====
/**
 * Парсер «Роллаут»: фазы по оси, карточки задач, роли @Роль.
 *
 * название: Вывод продукта
 * фаза: Реализация
 *   Development Board @Продукт
 *   Обвязка Т2–партнёр @Продукт + Юристы + Партнёр
 *
 * Устаревшее «трек: X» трактуется как ещё одна роль (как @X), не отдельная категория.
 * «!шлюз» / «шлюз» игнорируются.
 */
function parseRollout(text) {
    const diagnostics = [];
    const phases = [];
    let title = 'Роллаут';
    let current = null;
    let lastTask = null;

    function startPhase(name, line) {
        current = {
            name: name || 'Этап',
            tasks: [],
            line
        };
        phases.push(current);
        lastTask = null;
        return current;
    }

    function parseRoles(raw) {
        return String(raw || '')
            .split(/\s*[+,/]\s*|\s+и\s+/i)
            .map((s) => s.trim())
            .filter(Boolean);
    }

    function stripLegacyFlags(s) {
        let rest = String(s || '').trim();
        // бывший !шлюз — просто убираем из текста
        rest = rest.replace(/\s*!(шлюз|gate)\s*$/i, '').trim();
        return rest;
    }

    function addRole(task, role) {
        const r = String(role || '').trim();
        if (!task || !r) return;
        const key = typeof rolloutRoleKey === 'function' ? rolloutRoleKey(r) : r.toLowerCase();
        const exists = (task.roles || []).some((x) => {
            const k = typeof rolloutRoleKey === 'function' ? rolloutRoleKey(x) : String(x).toLowerCase();
            return k === key;
        });
        if (exists) return;
        task.roles.push(r);
        if (!task.lead) task.lead = r;
        task.ownerLabel = task.roles.join(' + ');
    }

    const lines = String(text || '').replace(/\r\n?/g, '\n').split('\n');
    lines.forEach((raw, idx) => {
        const lineNo = idx + 1;
        const trimmed = raw.trim();
        if (typeof isDiagramCommentLine === 'function'
            ? isDiagramCommentLine(trimmed)
            : (!trimmed || trimmed.startsWith('#') || trimmed.startsWith('//'))) return;
        if (/^(роллаут|rollout)\s*$/i.test(trimmed)) return;

        const titleVal = typeof parseDiagramTitleLine === 'function'
            ? parseDiagramTitleLine(trimmed)
            : null;
        if (titleVal != null || /^(заголовок|title)\s*:/i.test(trimmed)) {
            if (titleVal) title = titleVal;
            else {
                const m = trimmed.match(/^(заголовок|title)\s*:\s*(.*)$/i);
                title = (m ? String(m[2] || '').trim() : '') || title;
            }
            return;
        }

        const phaseM = trimmed.match(/^(фаза|этап|колонка|phase|column)\s*:\s*(.+)$/i);
        if (phaseM) {
            startPhase(stripLegacyFlags(phaseM[2]), lineNo);
            return;
        }

        const indent = (raw.match(/^[ \t]*/) || [''])[0].replace(/\t/g, '    ').length;

        // «трек: партнёр» → роль Партнёр (как остальные участники)
        const trackM = trimmed.match(/^(трек|контур|track)\s*:\s*(.+)$/i);
        if (trackM) {
            if (!lastTask) {
                diagnostics.push(diag('warning', 'Роль из «трек:» должна стоять под задачей', {
                    line: lineNo, code: 'rollout_track_orphan',
                    hint: 'Лучше сразу: задача @Продукт + Партнёр'
                }));
                return;
            }
            addRole(lastTask, trackM[2]);
            return;
        }

        // одиночная строка «шлюз» — игнор
        if (indent >= 2 && /^(шлюз|gate)\s*$/i.test(trimmed)) {
            return;
        }

        if (!current) startPhase('Этап', lineNo);

        let name = stripLegacyFlags(trimmed);
        let roles = [];
        const at = name.lastIndexOf(' @');
        const atStart = name.indexOf('@') === 0 ? 0 : -1;
        if (at >= 0) {
            roles = parseRoles(name.slice(at + 2));
            name = name.slice(0, at).trim();
        } else if (atStart === 0) {
            diagnostics.push(diag('warning', 'Нет названия задачи перед @', {
                line: lineNo, code: 'rollout_empty_task'
            }));
            return;
        }

        const task = {
            name: name || 'Задача',
            roles: roles.slice(),
            lead: roles[0] || '',
            ownerLabel: roles.join(' + '),
            line: lineNo
        };
        current.tasks.push(task);
        lastTask = task;
    });

    if (!phases.length || !phases.some((p) => p.tasks.length)) {
        diagnostics.push(diag('warning', 'Добавьте фазу и хотя бы одну задачу', {
            line: 1, code: 'rollout_empty',
            hint: 'фаза: Подготовка\n  Анализ рынка @Продукт'
        }));
        return attachDiagnostics(null, diagnostics);
    }

    phases.forEach((p) => {
        if (!p.tasks.length) {
            diagnostics.push(diag('warning', `Пустая фаза «${p.name}»`, {
                line: p.line, code: 'rollout_empty_phase'
            }));
        }
    });

    return attachDiagnostics({ title, phases }, diagnostics);
}

;

// ===== 45-layout-rollout.js =====
/**
 * Компоновка роллаута: колонки-фазы, карточки, легенда ролей.
 * Цвета ролей задаёт палитра темы в svg-renderer.
 */
function layoutRollout(data) {
    if (!data || !data.phases || !data.phases.length) {
        return { phases: [], roles: [], width: 0, height: 0, title: '' };
    }

    const pad = 20;
    const titleH = 68;
    const axisH = 22;
    const colW = 200;
    const colGap = 14;
    const headerH = 44;
    const cardGap = 8;
    const wrapName = (name, maxW, fs) => (typeof wrapTextLines === 'function'
        ? wrapTextLines(name, maxW, fs)
        : [String(name || '')]);

    const rolesOrder = [];
    const seenRole = new Set();

    function noteRole(label) {
        const key = rolloutRoleKey(label);
        if (!key || seenRole.has(key)) return;
        seenRole.add(key);
        rolesOrder.push({ key, label: String(label || '').trim() || key });
    }

    const phases = data.phases.map((p, index) => {
        const cards = (p.tasks || []).map((t) => {
            const roles = Array.isArray(t.roles) && t.roles.length
                ? t.roles.slice()
                : (t.lead ? [t.lead] : []);
            roles.forEach(noteRole);

            const titleLines = wrapName(t.name, colW - 28, 11).slice(0, 5);

            let ownerBlockH = 0;
            let ownerLines = [];
            let ownerMode = 'none';
            if (roles.length === 1) {
                ownerMode = 'single';
                ownerLines = wrapName(roles[0], colW - 36, 9).slice(0, 2);
                ownerBlockH = 4 + ownerLines.length * 12;
            } else if (roles.length > 1) {
                ownerMode = 'multi';
                ownerLines = roles.map((r) => String(r || '').trim()).filter(Boolean);
                ownerBlockH = 6 + ownerLines.length * 14 + 4;
            }

            const h = 10 + titleLines.length * 14
                + ownerBlockH
                + 8;
            return {
                name: t.name,
                nameLines: titleLines,
                roles,
                lead: roles[0] || '',
                ownerLabel: roles.join(' + '),
                ownerLines,
                ownerMode,
                line: t.line,
                h: Math.max(44, h)
            };
        });
        let yOff = 8;
        cards.forEach((c) => {
            c.yOff = yOff;
            yOff += c.h + cardGap;
        });
        return {
            name: p.name,
            nameLines: wrapName(p.name, colW - 16, 12).slice(0, 2),
            line: p.line,
            index,
            cards,
            bodyH: Math.max(48, yOff + 4)
        };
    });

    const maxBody = phases.reduce((m, p) => Math.max(m, p.bodyH), 80);
    // Легенда крупнее: заголовок + строки ~26px
    const legendH = rolesOrder.length ? (22 + Math.ceil(rolesOrder.length / 4) * 26) : 0;
    const colsBlockW = phases.length * colW + Math.max(0, phases.length - 1) * colGap;
    const width = pad + colsBlockW + pad;
    const height = titleH + axisH + headerH + maxBody + legendH + pad;

    phases.forEach((p, i) => {
        p.x = pad + i * (colW + colGap);
        p.y = titleH + axisH;
        p.width = colW;
        p.height = headerH + maxBody;
        p.bodyY = p.y + headerH;
        p.cards.forEach((c) => {
            c.x = p.x + 8;
            c.y = p.bodyY + c.yOff;
            c.w = colW - 16;
        });
        p.axisX = p.x + colW / 2;
        p.axisY = titleH + 10;
    });

    return {
        title: data.title || 'Роллаут',
        phases,
        roles: rolesOrder,
        width,
        height,
        titleH,
        pad,
        legendH,
        colW,
        headerH
    };
}

function rolloutRoleKey(name) {
    let n = String(name || '').toLowerCase().trim();
    n = n.replace(/^vas\s+/, '');
    if (/домен/.test(n)) return 'домен';
    if (/продукт/.test(n)) return 'продукт';
    if (/поддерж/.test(n)) return 'поддержка';
    if (/обучен/.test(n)) return 'обучение';
    if (/маркетинг|pr\b/.test(n)) return 'маркетинг';
    if (/закуп/.test(n)) return 'закупки';
    if (/юрист|правов/.test(n)) return 'юристы';
    if (/канал/.test(n)) return 'каналы';
    if (/партн[её]р/.test(n)) return 'партнёр';
    if (/it\b|ит\b|техблок|тб/.test(n)) return 'it';
    return n || 'прочее';
}

/**
 * Цвет роли из палитры темы (как у flowchart/timeline).
 */
function rolloutRoleColor(name, isDark, themeColors, rolesOrder) {
    const key = rolloutRoleKey(name);
    const palette = (themeColors && themeColors.length)
        ? themeColors
        : (isDark
            ? ['#60a5fa', '#34d399', '#c4b5fd', '#fbbf24', '#fb7185', '#38bdf8', '#a78bfa']
            : ['#2563eb', '#059669', '#7c3aed', '#d97706', '#e11d48', '#0284c7', '#6d28d9']);

    let idx = -1;
    if (rolesOrder && rolesOrder.length) {
        idx = rolesOrder.findIndex((r) => r && (r.key === key || rolloutRoleKey(r.label) === key));
    }
    if (idx < 0) {
        let h = 0;
        for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;
        idx = h % palette.length;
    }
    return palette[idx % palette.length];
}

;

// ===== 46-layout-lanes.js =====
/**
 * Дорожки (lanes): строки = роли, колонки = фазы, в ячейках — названия задач.
 * Данные из parseRollout (тот же синтаксис, что у роллаута).
 */
function layoutLanes(data) {
    if (!data || !data.phases || !data.phases.length) {
        return { phases: [], lanes: [], width: 0, height: 0, title: '' };
    }

    const pad = 20;
    const titleH = 56;
    const labelW = 108;
    const colW = 168;
    const colGap = 0;
    const rowGap = 0;
    const headerH = 34;
    const cellPad = 6;
    const cardGap = 5;
    const wrapName = (name, maxW, fs) => (typeof wrapTextLines === 'function'
        ? wrapTextLines(name, maxW, fs)
        : [String(name || '')]);

    const phases = data.phases.map((p, index) => ({
        name: p.name,
        nameLines: wrapName(p.name, colW - 16, 11).slice(0, 2),
        index,
        line: p.line,
        tasks: (p.tasks || []).map((t) => {
            const roles = Array.isArray(t.roles) && t.roles.length
                ? t.roles.slice()
                : (t.lead ? [t.lead] : []);
            const nameLines = wrapName(t.name, colW - 28, 10).slice(0, 3);
            const roleLine = roles.join(' · ');
            const roleLines = roleLine
                ? wrapName(roleLine, colW - 28, 9).slice(0, 2)
                : [];
            const h = 8 + nameLines.length * 12 + (roleLines.length ? 2 + roleLines.length * 11 : 0) + 6;
            return {
                name: t.name,
                nameLines,
                roles,
                roleLines,
                line: t.line,
                h: Math.max(36, h)
            };
        })
    }));

    const rolesOrder = [];
    const seen = new Set();
    phases.forEach((p) => {
        p.tasks.forEach((t) => {
            (t.roles || []).forEach((label) => {
                const key = typeof rolloutRoleKey === 'function' ? rolloutRoleKey(label) : String(label).toLowerCase();
                if (!key || seen.has(key)) return;
                seen.add(key);
                rolesOrder.push({ key, label: String(label || '').trim() || key });
            });
        });
    });

    const lanes = rolesOrder.map((role) => {
        const cells = phases.map((p) => {
            const cards = p.tasks
                .filter((t) => (t.roles || []).some((r) => {
                    const k = typeof rolloutRoleKey === 'function' ? rolloutRoleKey(r) : String(r).toLowerCase();
                    return k === role.key;
                }))
                .map((c) => ({
                    name: c.name,
                    nameLines: c.nameLines,
                    roles: c.roles,
                    roleLines: c.roleLines,
                    line: c.line,
                    h: c.h
                }));
            return { phaseIndex: p.index, cards, bodyH: 40 };
        });
        return { role, cells, rowH: 56 };
    });

    if (!lanes.length) {
        // нет ролей — одна дорожка «Без роли»
        const cells = phases.map((p) => {
            const cards = p.tasks.slice();
            let yOff = cellPad;
            const mapped = cards.map((c) => {
                const item = {
                    name: c.name,
                    nameLines: c.nameLines,
                    roles: c.roles,
                    roleLines: c.roleLines,
                    line: c.line,
                    h: c.h,
                    yOff
                };
                yOff += c.h + cardGap;
                return item;
            });
            return {
                phaseIndex: p.index,
                cards: mapped,
                bodyH: Math.max(40, yOff + cellPad - cardGap)
            };
        });
        const rowH = Math.max(56, ...cells.map((c) => c.bodyH)) + 4;
        lanes.push({
            role: { key: 'none', label: 'Без роли' },
            cells,
            rowH
        });
    } else {
        lanes.forEach((lane) => {
            lane.cells.forEach((cell) => {
                let yOff = cellPad;
                cell.cards.forEach((c) => {
                    c.yOff = yOff;
                    yOff += c.h + cardGap;
                });
                cell.bodyH = Math.max(40, yOff + cellPad - cardGap);
            });
            lane.rowH = Math.max(56, ...lane.cells.map((c) => c.bodyH)) + 4;
        });
    }

    const colsW = phases.length * colW;
    const width = pad + labelW + colsW + pad;
    const bodyH = lanes.reduce((s, l) => s + l.rowH + rowGap, 0);
    const height = titleH + headerH + bodyH + pad;

    let y = titleH + headerH;
    lanes.forEach((lane) => {
        lane.y = y;
        lane.labelX = pad;
        lane.labelW = labelW;
        lane.cells.forEach((cell, i) => {
            cell.x = pad + labelW + i * colW;
            cell.y = y;
            cell.w = colW;
            cell.h = lane.rowH;
            cell.cards.forEach((c) => {
                c.x = cell.x + 6;
                c.y = cell.y + c.yOff;
                c.w = colW - 12;
            });
        });
        y += lane.rowH + rowGap;
    });

    phases.forEach((p, i) => {
        p.x = pad + labelW + i * colW;
        p.y = titleH;
        p.width = colW;
        p.height = headerH;
    });

    return {
        title: data.title || 'Дорожки',
        phases,
        lanes,
        roles: rolesOrder,
        width,
        height,
        titleH,
        pad,
        labelW,
        headerH,
        colW
    };
}

;

// ===== 47-layout-ribbon.js =====
/**
 * Лента по фазам: вертикальные секции, полный список задач с ролями.
 * Данные из parseRollout.
 */
function layoutRibbon(data) {
    if (!data || !data.phases || !data.phases.length) {
        return { phases: [], roles: [], width: 0, height: 0, title: '' };
    }

    const pad = 24;
    const titleH = 56;
    const contentW = 640;
    const sectionGap = 18;
    const rowGap = 6;
    const wrapName = (name, maxW, fs) => (typeof wrapTextLines === 'function'
        ? wrapTextLines(name, maxW, fs)
        : [String(name || '')]);

    const rolesOrder = [];
    const seen = new Set();
    function noteRole(label) {
        const key = typeof rolloutRoleKey === 'function' ? rolloutRoleKey(label) : String(label).toLowerCase();
        if (!key || seen.has(key)) return;
        seen.add(key);
        rolesOrder.push({ key, label: String(label || '').trim() || key });
    }

    const phases = data.phases.map((p, index) => {
        const tasks = (p.tasks || []).map((t) => {
            const roles = Array.isArray(t.roles) && t.roles.length
                ? t.roles.slice()
                : (t.lead ? [t.lead] : []);
            roles.forEach(noteRole);
            const nameLines = wrapName(t.name, contentW - 120, 12).slice(0, 3);
            const roleLabel = roles.join(' · ');
            const roleLines = roleLabel
                ? wrapName(roleLabel, contentW - 120, 10).slice(0, 2)
                : [];
            const h = 10 + nameLines.length * 14 + (roleLines.length ? 2 + roleLines.length * 12 : 0) + 8;
            return {
                name: t.name,
                nameLines,
                roles,
                roleLines,
                line: t.line,
                h: Math.max(40, h)
            };
        });
        const headerH = 28;
        let body = 8;
        tasks.forEach((t) => { body += t.h + rowGap; });
        body += 4;
        return {
            name: p.name,
            index,
            line: p.line,
            tasks,
            headerH,
            h: headerH + body
        };
    });

    const width = pad + contentW + pad;
    let height = titleH;
    phases.forEach((p, i) => {
        p.x = pad;
        p.y = height;
        p.w = contentW;
        let ty = p.y + p.headerH + 8;
        p.tasks.forEach((t) => {
            t.x = p.x + 14;
            t.y = ty;
            t.w = contentW - 28;
            ty += t.h + rowGap;
        });
        height += p.h + (i < phases.length - 1 ? sectionGap : 0);
    });
    height += pad;

    const legendH = rolesOrder.length ? (18 + Math.ceil(rolesOrder.length / 5) * 22) : 0;
    height += legendH;

    return {
        title: data.title || 'Лента фаз',
        phases,
        roles: rolesOrder,
        width,
        height,
        titleH,
        pad,
        contentW,
        legendH
    };
}

;

// ===== 48-parser-state.js =====
/**
 * Диаграмма состояний (state machine).
 *
 * название: Статус заявки
 * [*] -> Черновик
 * Черновик -> На проверке: отправить
 * На проверке -> Утверждена: ок
 * На проверке -> Черновик: правки
 * Утверждена -> [*]
 * состояние: Архив
 *
 * Старт/финиш: [*] | старт | конец | начало | финиш
 * Переход: A -> B: событие
 */
function parseState(text) {
    const diagnostics = [];
    let title = 'Состояния';
    const states = new Map();
    const transitions = [];
    let autoSeq = 0;

    function slug(label) {
        return String(label || '')
            .toLowerCase()
            .replace(/[^\p{L}\p{N}]+/gu, '_')
            .replace(/^_|_$/g, '')
            .slice(0, 48) || ('s' + (++autoSeq));
    }

    function terminalRole(raw) {
        const t = String(raw || '').trim();
        if (t === '[*]' || t === '(*)' || t === '*') return 'star';
        if (/^(старт|начало|start)$/i.test(t)) return 'initial';
        if (/^(конец|финиш|end)$/i.test(t)) return 'final';
        return null;
    }

    function ensureInitial(lineNo) {
        const id = '__initial__';
        if (!states.has(id)) {
            states.set(id, { id, label: '●', kind: 'initial', line: lineNo || null });
        } else if (lineNo != null && states.get(id).line == null) {
            states.get(id).line = lineNo;
        }
        return states.get(id);
    }

    function ensureFinal(lineNo) {
        const id = '__final__';
        if (!states.has(id)) {
            states.set(id, { id, label: '◉', kind: 'final', line: lineNo || null });
        } else if (lineNo != null && states.get(id).line == null) {
            states.get(id).line = lineNo;
        }
        return states.get(id);
    }

    function ensureState(raw, lineNo, edgeSide) {
        const label = String(raw || '').trim();
        if (!label) return null;
        const role = terminalRole(label);
        if (role === 'initial') return ensureInitial(lineNo);
        if (role === 'final') return ensureFinal(lineNo);
        if (role === 'star') {
            // [*] слева = старт, справа = финиш (как в Mermaid)
            return edgeSide === 'to' ? ensureFinal(lineNo) : ensureInitial(lineNo);
        }

        for (const s of states.values()) {
            if (s.kind === 'normal' && s.label === label) {
                if (lineNo != null && s.line == null) s.line = lineNo;
                return s;
            }
        }
        let id = slug(label);
        if (states.has(id)) id = id + '_' + (++autoSeq);
        const node = { id, label, kind: 'normal', line: lineNo || null };
        states.set(id, node);
        return node;
    }

    String(text || '').replace(/\r\n?/g, '\n').split('\n').forEach((raw, idx) => {
        const lineNo = idx + 1;
        const trimmed = raw.trim();
        if (typeof isDiagramCommentLine === 'function'
            ? isDiagramCommentLine(trimmed)
            : (!trimmed || trimmed.startsWith('#') || trimmed.startsWith('//'))) return;

        if (/^(состояния|state|statemachine|fsm)\s*$/i.test(trimmed)) return;

        const titleVal = typeof parseDiagramTitleLine === 'function'
            ? parseDiagramTitleLine(trimmed)
            : null;
        if (titleVal != null) {
            title = titleVal;
            return;
        }

        const decl = trimmed.match(/^(состояние|state)\s*:\s*(.+)$/i);
        if (decl) {
            ensureState(decl[2].trim(), lineNo, null);
            return;
        }

        const edgeM = trimmed.match(/^(.+?)\s*(->|-->)\s*(.+?)(?:\s*:\s*(.*))?$/);
        if (edgeM) {
            const fromRaw = edgeM[1].trim();
            const toRaw = edgeM[3].trim();
            const label = (edgeM[4] != null ? edgeM[4] : '').trim();
            const from = ensureState(fromRaw, lineNo, 'from');
            const to = ensureState(toRaw, lineNo, 'to');
            if (!from || !to) {
                diagnostics.push(diag('warning', 'Не разобран переход', {
                    line: lineNo, code: 'state_bad_edge',
                    hint: 'Черновик -> Готово: событие'
                }));
                return;
            }
            transitions.push({
                from: from.id,
                to: to.id,
                label,
                line: lineNo
            });
            return;
        }

        if (trimmed) {
            diagnostics.push(diag('warning', 'Строка не распознана', {
                line: lineNo, code: 'state_bad_line',
                hint: 'состояние: Имя · или A -> B: событие · [*] для старта/финиша'
            }));
        }
    });

    const list = Array.from(states.values());
    if (!list.length) {
        return attachDiagnostics(null, diagnostics);
    }

    return attachDiagnostics({
        title,
        states: list,
        transitions
    }, diagnostics);
}

;

// ===== 49-layout-state.js =====
/**
 * Раскладка диаграммы состояний сверху вниз (TB):
 * ранги = ряды, ветвления разведены по X, возвраты — боковые дорожки.
 * Высота растёт с содержимым — без «плоской» полоски.
 */
function layoutState(data) {
    if (!data || !data.states || !data.states.length) {
        return { nodes: [], edges: [], width: 0, height: 0, title: '' };
    }

    const nodes = data.states.map((s) => Object.assign({}, s));
    const byId = new Map(nodes.map((n) => [n.id, n]));
    const edges = (data.transitions || []).filter((e) => byId.has(e.from) && byId.has(e.to));

    const fontSize = 13;
    const fontFam = (typeof getUiFontFamily === 'function')
        ? getUiFontFamily()
        : 'system-ui, sans-serif';

    nodes.forEach((n) => {
        if (n.kind === 'initial' || n.kind === 'final') {
            n.width = 28;
            n.height = 28;
            n.lines = [n.label];
            return;
        }
        const label = String(n.label || n.id);
        const lines = (typeof wrapTextLines === 'function')
            ? wrapTextLines(label, 140, fontSize, fontFam)
            : [label];
        n.lines = lines.slice(0, 3);
        let maxLine = 56;
        n.lines.forEach((l) => {
            const w = String(l).length * fontSize * 0.56;
            if (w > maxLine) maxLine = w;
        });
        n.width = Math.max(128, Math.min(220, maxLine + 40));
        n.height = Math.max(56, n.lines.length * 18 + 30);
    });

    const outs = new Map();
    const ins = new Map();
    nodes.forEach((n) => { outs.set(n.id, []); ins.set(n.id, []); });
    edges.forEach((e) => {
        outs.get(e.from).push(e.to);
        ins.get(e.to).push(e.from);
    });

    // Longest-path ранги (вперёд по ациклической ориентации)
    const rank = new Map();
    nodes.forEach((n) => rank.set(n.id, 0));
    const initials = nodes.filter((n) => n.kind === 'initial');
    const sources = nodes.filter((n) => n.kind === 'initial' || !(ins.get(n.id) || []).length);
    const startIds = initials.length
        ? initials.map((n) => n.id)
        : (sources.length ? sources.map((n) => n.id) : [nodes[0].id]);

    // Удаляем обратные рёбра для раскладки: оставляем только DAG по BFS-слою
    const dagOut = new Map();
    nodes.forEach((n) => dagOut.set(n.id, []));
    const bfsRank = new Map();
    const q0 = startIds.slice();
    startIds.forEach((id) => bfsRank.set(id, 0));
    while (q0.length) {
        const id = q0.shift();
        const r = bfsRank.get(id) || 0;
        (outs.get(id) || []).forEach((to) => {
            if (!bfsRank.has(to)) {
                bfsRank.set(to, r + 1);
                q0.push(to);
            }
        });
    }
    edges.forEach((e) => {
        const ra = bfsRank.has(e.from) ? bfsRank.get(e.from) : 0;
        const rb = bfsRank.has(e.to) ? bfsRank.get(e.to) : 0;
        if (rb > ra) dagOut.get(e.from).push(e.to);
        else if (rb === ra && e.from !== e.to) {
            // same-rank: не влияет на longest-path
        }
        // rb < ra → обратное, в DAG не берём
    });

    // Топологический longest-path по DAG
    const indeg = new Map();
    nodes.forEach((n) => indeg.set(n.id, 0));
    dagOut.forEach((tos) => tos.forEach((to) => indeg.set(to, (indeg.get(to) || 0) + 1)));
    const topo = [];
    const q = [];
    nodes.forEach((n) => {
        if ((indeg.get(n.id) || 0) === 0) q.push(n.id);
    });
    while (q.length) {
        const id = q.shift();
        topo.push(id);
        (dagOut.get(id) || []).forEach((to) => {
            indeg.set(to, (indeg.get(to) || 0) - 1);
            if (indeg.get(to) === 0) q.push(to);
        });
    }
    startIds.forEach((id) => rank.set(id, 0));
    topo.forEach((id) => {
        const base = rank.get(id) || 0;
        (dagOut.get(id) || []).forEach((to) => {
            rank.set(to, Math.max(rank.get(to) || 0, base + 1));
        });
    });
    nodes.forEach((n) => {
        if (!rank.has(n.id) || (!bfsRank.has(n.id) && n.kind === 'normal')) {
            const mx = Math.max(0, ...Array.from(rank.values()));
            rank.set(n.id, mx);
        }
    });

    nodes.forEach((n) => {
        if (n.kind === 'initial') rank.set(n.id, 0);
    });
    const finals = nodes.filter((n) => n.kind === 'final');
    if (finals.length) {
        const nonFinalMax = Math.max(
            0,
            ...nodes.filter((n) => n.kind !== 'final').map((n) => rank.get(n.id) || 0)
        );
        finals.forEach((n) => rank.set(n.id, nonFinalMax + 1));
    }

    // Изоляты без рёбер — отдельный ряд внизу перед финалом
    const maxConnected = Math.max(
        0,
        ...nodes
            .filter((n) => ((ins.get(n.id) || []).length + (outs.get(n.id) || []).length) > 0)
            .map((n) => rank.get(n.id) || 0)
    );
    nodes.forEach((n) => {
        const deg = (ins.get(n.id) || []).length + (outs.get(n.id) || []).length;
        if (!deg && n.kind === 'normal') rank.set(n.id, maxConnected);
    });

    nodes.forEach((n) => { n.rank = rank.get(n.id) || 0; });
    const maxR = Math.max(...nodes.map((n) => n.rank), 0);

    const ranks = [];
    for (let r = 0; r <= maxR; r++) {
        const layer = nodes.filter((n) => n.rank === r);
        if (layer.length) ranks.push(layer);
    }

    function orderPass(forward) {
        const seq = forward
            ? ranks.map((_, i) => i)
            : ranks.map((_, i) => ranks.length - 1 - i);
        seq.forEach((ri) => {
            const layer = ranks[ri];
            layer.forEach((n) => {
                const neigh = forward ? (ins.get(n.id) || []) : (outs.get(n.id) || []);
                if (!neigh.length) {
                    n._bary = layer.indexOf(n);
                    return;
                }
                let sum = 0;
                let cnt = 0;
                neigh.forEach((id) => {
                    const other = byId.get(id);
                    if (!other) return;
                    const layerO = ranks.find((L) => L.some((x) => x.id === other.id)) || [];
                    const idx = layerO.indexOf(other);
                    if (idx >= 0) { sum += idx; cnt += 1; }
                });
                n._bary = cnt ? sum / cnt : layer.indexOf(n);
            });
            layer.sort((a, b) => {
                if (a.kind === 'initial') return -1;
                if (b.kind === 'initial') return 1;
                if (a.kind === 'final') return 1;
                if (b.kind === 'final') return -1;
                return a._bary - b._bary;
            });
            ranks[ri] = layer;
        });
    }
    orderPass(true);
    orderPass(false);
    orderPass(true);

    const gapX = 96;
    const gapY = 128;
    const pad = 56;
    const titleH = 56;
    const sideLanePad = 100;
    const labelLane = 36;

    // Ширина рядов → maxRowW (не растягивать узлы слишком далеко — плотнее по смыслу)
    let maxRowW = 0;
    ranks.forEach((layer) => {
        let w = 0;
        layer.forEach((n, i) => { w += n.width + (i ? gapX : 0); });
        if (layer.length === 1) w = Math.max(w, 200);
        if (w > maxRowW) maxRowW = w;
    });
    maxRowW = Math.max(maxRowW, 360);

    let y = titleH + pad;
    ranks.forEach((layer, li) => {
        let totalW = 0;
        layer.forEach((n, i) => { totalW += n.width + (i ? gapX : 0); });
        const useGap = gapX;
        totalW = layer.reduce((s, n) => s + n.width, 0) + useGap * Math.max(0, layer.length - 1);
        let x = pad + sideLanePad + Math.max(0, (maxRowW - totalW) / 2);
        const rowH = Math.max(...layer.map((n) => n.height), 56);
        layer.forEach((n) => {
            n.x = x;
            n.y = y + (rowH - n.height) / 2;
            n.cx = n.x + n.width / 2;
            n.cy = n.y + n.height / 2;
            x += n.width + useGap;
        });
        // Анти-наложение внутри ряда
        for (let i = 1; i < layer.length; i++) {
            const prev = layer[i - 1];
            const cur = layer[i];
            const minX = prev.x + prev.width + 28;
            if (cur.x < minX) {
                const shift = minX - cur.x;
                for (let j = i; j < layer.length; j++) {
                    layer[j].x += shift;
                    layer[j].cx = layer[j].x + layer[j].width / 2;
                }
            }
        }
        y += rowH + gapY + (li < ranks.length - 1 ? labelLane : 0);
    });

    // Пересчитать maxRowW после сдвигов
    maxRowW = Math.max(
        maxRowW,
        ...ranks.map((layer) => {
            if (!layer.length) return 0;
            const left = Math.min(...layer.map((n) => n.x));
            const right = Math.max(...layer.map((n) => n.x + n.width));
            return right - left;
        })
    );

    const contentBottom = y - gapY;
    const width = pad * 2 + sideLanePad * 2 + maxRowW;
    const height = Math.max(640, contentBottom + pad + 40);

    const outSlot = new Map();
    const inSlot = new Map();
    edges.forEach((e) => {
        outSlot.set(e.from, (outSlot.get(e.from) || 0) + 1);
        inSlot.set(e.to, (inSlot.get(e.to) || 0) + 1);
    });
    const outIdx = new Map();
    const inIdx = new Map();

    function nextSlot(map, id, total) {
        const i = map.get(id) || 0;
        map.set(id, i + 1);
        if (total <= 1) return 0;
        return (i - (total - 1) / 2) * 14;
    }

    function port(n, side, off) {
        const o = off || 0;
        if (side === 'bottom') return { x: Math.max(n.x + 10, Math.min(n.x + n.width - 10, n.cx + o)), y: n.y + n.height };
        if (side === 'top') return { x: Math.max(n.x + 10, Math.min(n.x + n.width - 10, n.cx + o)), y: n.y };
        if (side === 'left') return { x: n.x, y: Math.max(n.y + 8, Math.min(n.y + n.height - 8, n.cy + o)) };
        return { x: n.x + n.width, y: Math.max(n.y + 8, Math.min(n.y + n.height - 8, n.cy + o)) };
    }

    let backSeq = 0;
    const forwardByGap = new Map(); // key: fromRank->toRank → count
    const laidEdges = edges.map((e) => {
        const a = byId.get(e.from);
        const b = byId.get(e.to);
        const forward = a.rank < b.rank;
        const same = a.rank === b.rank;
        const oOff = nextSlot(outIdx, e.from, outSlot.get(e.from) || 1);
        const iOff = nextSlot(inIdx, e.to, inSlot.get(e.to) || 1);

        let x1; let y1; let x2; let y2;
        let cx1; let cy1; let cx2; let cy2;
        let lx; let ly;

        if (forward) {
            const p1 = port(a, 'bottom', oOff);
            const p2 = port(b, 'top', iOff);
            x1 = p1.x; y1 = p1.y; x2 = p2.x; y2 = p2.y;
            const gapKey = a.rank + '>' + b.rank;
            const gapIdx = forwardByGap.get(gapKey) || 0;
            forwardByGap.set(gapKey, gapIdx + 1);
            const aligned = Math.abs(x2 - x1) < 12;

            // Прямая вертикаль, если узлы друг под другом
            if (aligned) {
                const x = (x1 + x2) / 2;
                lx = x + 14;
                ly = (y1 + y2) / 2;
                return {
                    from: e.from, to: e.to, label: e.label || '',
                    line: e.line || null, sourceLine: e.line || null,
                    route: 'forward',
                    orth: true,
                    points: [
                        { x: x, y: y1 },
                        { x: x, y: y2 }
                    ],
                    x1: x, y1, x2: x, y2, cx1: x, cy1: (y1 + y2) / 2, cx2: x, cy2: (y1 + y2) / 2, lx, ly
                };
            }

            // Ортогональный локоть с уникальной midY — без наложений параллельных стрелок
            const midY = y1 + (y2 - y1) * (0.35 + (gapIdx % 4) * 0.12);
            lx = (x1 + x2) / 2;
            ly = midY - 10;
            return {
                from: e.from, to: e.to, label: e.label || '',
                line: e.line || null, sourceLine: e.line || null,
                route: 'forward',
                orth: true,
                points: [
                    { x: x1, y: y1 },
                    { x: x1, y: midY },
                    { x: x2, y: midY },
                    { x: x2, y: y2 }
                ],
                x1, y1, x2, y2, cx1: x1, cy1: midY, cx2: x2, cy2: midY, lx, ly
            };
        }

        if (same) {
            const p1 = port(a, 'right', oOff);
            const p2 = port(b, 'right', iOff);
            x1 = p1.x; y1 = p1.y; x2 = p2.x; y2 = p2.y;
            const bump = 44 + Math.abs(oOff) + Math.abs(y2 - y1) * 0.12;
            cx1 = x1 + bump; cy1 = y1;
            cx2 = x2 + bump; cy2 = y2;
            lx = x1 + bump + 6;
            ly = (y1 + y2) / 2;
            return {
                from: e.from, to: e.to, label: e.label || '',
                line: e.line || null, sourceLine: e.line || null,
                route: 'same',
                orth: true,
                points: [
                    { x: x1, y: y1 },
                    { x: cx1, y: y1 },
                    { x: cx2, y: y2 },
                    { x: x2, y: y2 }
                ],
                x1, y1, x2, y2, cx1, cy1, cx2, cy2, lx, ly
            };
        }

        // назад — боковая дорожка (чередуемлево/право)
        const lane = backSeq++;
        const leftSide = lane % 2 === 0;
        const p1 = port(a, leftSide ? 'left' : 'right', oOff);
        const p2 = port(b, leftSide ? 'left' : 'right', iOff);
        x1 = p1.x; y1 = p1.y; x2 = p2.x; y2 = p2.y;
        const laneX = leftSide
            ? pad + 18 + Math.floor(lane / 2) * 22
            : width - pad - 18 - Math.floor(lane / 2) * 22;
        return {
            from: e.from, to: e.to, label: e.label || '',
            line: e.line || null, sourceLine: e.line || null,
            route: 'back',
            orth: true,
            points: [
                { x: x1, y: y1 },
                { x: laneX, y: y1 },
                { x: laneX, y: y2 },
                { x: x2, y: y2 }
            ],
            x1, y1, x2, y2,
            cx1: laneX, cy1: y1, cx2: laneX, cy2: y2,
            lx: laneX + (leftSide ? 10 : -10),
            ly: (y1 + y2) / 2
        };
    });

    // Развести подписи: не ближе 18px по Y
    const labeled = laidEdges.filter((e) => e.label).sort((a, b) => a.ly - b.ly);
    for (let i = 1; i < labeled.length; i++) {
        const prev = labeled[i - 1];
        const cur = labeled[i];
        if (Math.abs(cur.lx - prev.lx) < 120 && cur.ly - prev.ly < 18) {
            cur.ly = prev.ly + 18;
        }
    }

    return {
        title: data.title || '',
        orientation: 'tb',
        nodes,
        edges: laidEdges,
        width: Math.max(420, Math.ceil(width)),
        height: Math.max(640, Math.ceil(height))
    };
}

;

// ===== 50-parser-journey.js =====
/**
 * Путь пользователя (user journey).
 *
 * название: Путь к подписке
 * этап: Осознание
 *   касание: Статья в блоге
 *   мысль: Интересно, но дорого?
 *   эмоция: 2
 *   боль: Нет кейсов из отрасли
 * этап: Оценка
 *   касание: Демо
 *   мысль: Понял ценность
 *   эмоция: 4
 *   боль: Долго настраивать
 * этап: Решение
 *   касание: Оплата
 *   эмоция: 5
 */
function parseJourney(text) {
    const diagnostics = [];
    let title = 'Путь пользователя';
    const stages = [];
    let current = null;

    function ensureStage(name, lineNo) {
        current = {
            name: String(name || '').trim() || 'Этап',
            touch: '',
            thought: '',
            emotion: null,
            pain: '',
            line: lineNo || null
        };
        stages.push(current);
        return current;
    }

    String(text || '').replace(/\r\n?/g, '\n').split('\n').forEach((raw, idx) => {
        const lineNo = idx + 1;
        const trimmed = raw.trim();
        if (typeof isDiagramCommentLine === 'function'
            ? isDiagramCommentLine(trimmed)
            : (!trimmed || trimmed.startsWith('#') || trimmed.startsWith('//'))) return;

        if (/^(путь|journey|user\s*journey)\s*$/i.test(trimmed)) return;

        const titleVal = typeof parseDiagramTitleLine === 'function'
            ? parseDiagramTitleLine(trimmed)
            : null;
        if (titleVal != null) {
            title = titleVal;
            return;
        }

        const stageM = trimmed.match(/^(этап|стадия|stage|шаг)\s*:\s*(.+)$/i);
        if (stageM) {
            ensureStage(stageM[2], lineNo);
            return;
        }

        const fieldM = trimmed.match(/^(касание|канал|touch|мысль|feeling|эмоция|emotion|настроение|боль|барьер|pain|проблема)\s*:\s*(.+)$/i);
        if (fieldM) {
            if (!current) ensureStage('Этап', lineNo);
            const key = fieldM[1].toLowerCase();
            const val = fieldM[2].trim();
            if (/^(касание|канал|touch)$/i.test(key)) current.touch = val;
            else if (/^(мысль|feeling)$/i.test(key)) current.thought = val;
            else if (/^(боль|барьер|pain|проблема)$/i.test(key)) current.pain = val;
            else if (/^(эмоция|emotion|настроение)$/i.test(key)) {
                const n = parseInt(val, 10);
                if (Number.isFinite(n) && n >= 1 && n <= 5) {
                    current.emotion = n;
                } else {
                    diagnostics.push(diag('warning', 'Эмоция: число от 1 до 5', {
                        line: lineNo, code: 'journey_bad_emotion',
                        hint: 'эмоция: 3'
                    }));
                }
            }
            return;
        }

        if (trimmed) {
            diagnostics.push(diag('warning', 'Строка не распознана', {
                line: lineNo, code: 'journey_bad_line',
                hint: 'этап: … · касание: … · мысль: … · эмоция: 1–5 · боль: …'
            }));
        }
    });

    if (!stages.length) {
        return attachDiagnostics(null, diagnostics);
    }

    return attachDiagnostics({ title, stages }, diagnostics);
}

;

// ===== 51-layout-journey.js =====
/**
 * Раскладка пути пользователя: колонки = этапы.
 */
function layoutJourney(data) {
    if (!data || !data.stages || !data.stages.length) {
        return { stages: [], width: 0, height: 0, title: '', rows: [] };
    }

    const fontFam = (typeof getUiFontFamily === 'function')
        ? getUiFontFamily()
        : 'system-ui, sans-serif';
    const colW = 196;
    const gap = 18;
    const pad = 28;
    const titleH = 56; // место под заголовок + легенду настроения
    const headerH = 44;
    const emotionH = 72; // подпись «Настроение» + кружки + подпись N/5 отдельной строкой
    const rowGap = 10;

    const rows = [
        { key: 'touch', label: 'Касание' },
        { key: 'thought', label: 'Мысль' },
        { key: 'pain', label: 'Боль' }
    ];

    function wrap(text, maxW, fs) {
        return (typeof wrapTextLines === 'function')
            ? wrapTextLines(String(text || ''), maxW, fs, fontFam)
            : [String(text || '')];
    }

    const stages = data.stages.map((s, index) => {
        const nameLines = wrap(s.name, colW - 20, 12).slice(0, 2);
        const touchLines = wrap(s.touch || '—', colW - 20, 11).slice(0, 4);
        const thoughtLines = wrap(s.thought || '—', colW - 20, 11).slice(0, 4);
        const painLines = wrap(s.pain || '—', colW - 20, 11).slice(0, 4);
        return {
            index,
            name: s.name,
            nameLines,
            touch: s.touch || '',
            thought: s.thought || '',
            pain: s.pain || '',
            emotion: s.emotion,
            line: s.line,
            touchLines,
            thoughtLines,
            painLines,
            x: pad + index * (colW + gap),
            width: colW
        };
    });

    function rowHeight(key) {
        let max = 40;
        stages.forEach((s) => {
            const lines = key === 'touch' ? s.touchLines
                : (key === 'thought' ? s.thoughtLines : s.painLines);
            const h = 28 + lines.length * 14;
            if (h > max) max = h;
        });
        return max;
    }

    const rowHs = {
        touch: rowHeight('touch'),
        thought: rowHeight('thought'),
        pain: rowHeight('pain')
    };

    let y = titleH + pad + headerH + emotionH + 12;
    const rowY = {};
    rows.forEach((r) => {
        rowY[r.key] = y;
        y += rowHs[r.key] + rowGap;
    });

    stages.forEach((s) => {
        s.headerY = titleH + pad;
        s.emotionY = titleH + pad + headerH;
        s.rowY = rowY;
        s.rowH = rowHs;
    });

    const width = pad * 2 + stages.length * colW + Math.max(0, stages.length - 1) * gap;
    const height = y + pad;

    return {
        title: data.title || '',
        stages,
        rows,
        rowY,
        rowHs,
        width: Math.max(360, width),
        height: Math.max(280, height),
        pad,
        titleH,
        headerH,
        emotionH,
        colW
    };
}

;

// ===== 52-parser-context.js =====
/**
 * Контекст системы (лёгкий C4 L1).
 *
 * название: Контекст DocPlan
 * система: DocPlan — планы и документы
 * человек: Автор
 * человек: Читатель
 * внешняя: Telegram
 * внешняя: Google Drive
 * Автор -> DocPlan: пишет
 * Читатель -> DocPlan: читает
 * DocPlan -> Telegram: пуш
 * DocPlan -> Google Drive: экспорт
 */
function parseContext(text) {
    const diagnostics = [];
    let title = 'Контекст системы';
    const nodes = new Map();
    const links = [];
    let autoSeq = 0;
    let primarySystem = null;

    function slug(label) {
        return String(label || '')
            .toLowerCase()
            .replace(/[^\p{L}\p{N}]+/gu, '_')
            .replace(/^_|_$/g, '')
            .slice(0, 48) || ('n' + (++autoSeq));
    }

    function splitNameDesc(raw) {
        const s = String(raw || '').trim();
        const m = s.match(/^(.+?)\s*[—–\-:]\s*(.+)$/);
        if (m) return { name: m[1].trim(), desc: m[2].trim() };
        return { name: s, desc: '' };
    }

    function ensureNode(raw, kind, lineNo) {
        const parts = splitNameDesc(raw);
        const name = parts.name;
        if (!name) return null;
        for (const n of nodes.values()) {
            if (n.name === name) {
                if (kind && n.kind === 'system' && kind !== 'system') { /* keep */ }
                else if (kind) n.kind = kind;
                if (parts.desc && !n.desc) n.desc = parts.desc;
                if (lineNo != null && n.line == null) n.line = lineNo;
                return n;
            }
        }
        let id = slug(name);
        if (nodes.has(id)) id = id + '_' + (++autoSeq);
        const node = {
            id,
            name,
            desc: parts.desc || '',
            kind: kind || 'system',
            line: lineNo || null
        };
        nodes.set(id, node);
        if (kind === 'system' && !primarySystem) primarySystem = node;
        return node;
    }

    function findByName(raw) {
        const name = splitNameDesc(raw).name;
        for (const n of nodes.values()) {
            if (n.name === name) return n;
        }
        return null;
    }

    String(text || '').replace(/\r\n?/g, '\n').split('\n').forEach((raw, idx) => {
        const lineNo = idx + 1;
        const trimmed = raw.trim();
        if (typeof isDiagramCommentLine === 'function'
            ? isDiagramCommentLine(trimmed)
            : (!trimmed || trimmed.startsWith('#') || trimmed.startsWith('//'))) return;

        if (/^(контекст|context|c4)\s*$/i.test(trimmed)) return;

        const titleVal = typeof parseDiagramTitleLine === 'function'
            ? parseDiagramTitleLine(trimmed)
            : null;
        if (titleVal != null) {
            title = titleVal;
            return;
        }

        const person = trimmed.match(/^(человек|персона|actor|user|роль)\s*:\s*(.+)$/i);
        if (person) {
            ensureNode(person[2], 'person', lineNo);
            return;
        }
        const ext = trimmed.match(/^(внешняя|внешняя система|external|система вне)\s*:\s*(.+)$/i);
        if (ext) {
            ensureNode(ext[2], 'external', lineNo);
            return;
        }
        const sys = trimmed.match(/^(система|system)\s*:\s*(.+)$/i);
        if (sys) {
            const n = ensureNode(sys[2], 'system', lineNo);
            if (n && !primarySystem) primarySystem = n;
            return;
        }

        const edgeM = trimmed.match(/^(.+?)\s*(->|-->)\s*(.+?)(?:\s*:\s*(.*))?$/);
        if (edgeM) {
            const fromRaw = edgeM[1].trim();
            const toRaw = edgeM[3].trim();
            const label = (edgeM[4] != null ? edgeM[4] : '').trim();
            let from = findByName(fromRaw);
            let to = findByName(toRaw);
            if (!from) from = ensureNode(fromRaw, 'person', lineNo);
            if (!to) to = ensureNode(toRaw, primarySystem ? 'external' : 'system', lineNo);
            if (!from || !to) {
                diagnostics.push(diag('warning', 'Не разобрана связь', {
                    line: lineNo, code: 'context_bad_edge'
                }));
                return;
            }
            links.push({ from: from.id, to: to.id, label, line: lineNo });
            return;
        }

        if (trimmed) {
            diagnostics.push(diag('warning', 'Строка не распознана', {
                line: lineNo, code: 'context_bad_line',
                hint: 'система: … · человек: … · внешняя: … · A -> B: описание'
            }));
        }
    });

    const list = Array.from(nodes.values());
    if (!list.length) {
        return attachDiagnostics(null, diagnostics);
    }
    if (!primarySystem) {
        primarySystem = list.find((n) => n.kind === 'system') || list[0];
        if (primarySystem) primarySystem.kind = 'system';
    }

    return attachDiagnostics({
        title,
        nodes: list,
        links,
        primaryId: primarySystem ? primarySystem.id : list[0].id
    }, diagnostics);
}

;

// ===== 53-layout-context.js =====
/**
 * Раскладка контекста (C4 L1): люди | система | внешние;
 * сервисы — ряд снизу. Связи — ортогональные каналы без наложений подписей.
 */
function layoutContext(data) {
    if (!data || !data.nodes || !data.nodes.length) {
        return { nodes: [], links: [], width: 0, height: 0, title: '', colLabels: null, subtitle: '' };
    }

    const fontFam = (typeof getUiFontFamily === 'function')
        ? getUiFontFamily()
        : 'system-ui, sans-serif';
    const pad = 52;
    const titleH = 56;
    const colLabelH = 24;
    const corridor = 280;
    const gapY = 56;
    const personW = 168;
    const externalW = 168;
    const systemW = 230;
    const serviceGapX = 48;
    const bottomLaneGap = 88;

    function wrap(text, maxW, fs) {
        return (typeof wrapTextLines === 'function')
            ? wrapTextLines(String(text || ''), maxW, fs, fontFam)
            : [String(text || '')];
    }

    const nodes = data.nodes.map((n) => {
        const isSys = n.kind === 'system';
        const boxW = isSys ? systemW : (n.kind === 'person' ? personW : externalW);
        const nameLines = wrap(n.name, boxW - 28, isSys ? 14 : 12).slice(0, 2);
        const descLines = n.desc ? wrap(n.desc, boxW - 28, 11).slice(0, 2) : [];
        const h = 16 + nameLines.length * 16 + (descLines.length ? 4 + descLines.length * 13 : 0) + 14;
        return Object.assign({}, n, {
            nameLines,
            descLines,
            width: boxW,
            height: Math.max(52, h)
        });
    });
    const byId = new Map(nodes.map((n) => [n.id, n]));

    const primary = byId.get(data.primaryId) || nodes.find((n) => n.kind === 'system') || nodes[0];
    const people = nodes.filter((n) => n.id !== primary.id && n.kind === 'person');
    const externals = nodes.filter((n) => n.id !== primary.id && n.kind === 'external');
    const services = nodes.filter((n) => n.id !== primary.id && n.kind === 'system');

    function stackHeight(list) {
        return list.reduce((s, n, i) => s + n.height + (i ? gapY : 0), 0);
    }

    const leftLinkCount = (data.links || []).filter((l) => {
        const a = byId.get(l.from);
        const b = byId.get(l.to);
        if (!a || !b) return false;
        return (a.id === primary.id && people.some((p) => p.id === b.id))
            || (b.id === primary.id && people.some((p) => p.id === a.id));
    }).length;
    const rightLinkCount = (data.links || []).filter((l) => {
        const a = byId.get(l.from);
        const b = byId.get(l.to);
        if (!a || !b) return false;
        return (a.id === primary.id && externals.some((p) => p.id === b.id))
            || (b.id === primary.id && externals.some((p) => p.id === a.id));
    }).length;
    const portNeed = Math.max(leftLinkCount, rightLinkCount, people.length, externals.length, 1);
    primary.height = Math.max(primary.height, 40 + portNeed * 26);

    const leftH = stackHeight(people);
    const rightH = stackHeight(externals);
    const centerH = primary.height;
    const bodyH = Math.max(leftH, rightH, centerH, 160);

    const leftW = people.length ? Math.max(...people.map((n) => n.width), personW) : 0;
    const rightW = externals.length ? Math.max(...externals.map((n) => n.width), externalW) : 0;

    const servicesRowW = services.length
        ? services.reduce((s, n) => s + n.width, 0) + serviceGapX * Math.max(0, services.length - 1)
        : 0;
    const mainW = leftW + (leftW ? corridor : 24) + primary.width + (rightW ? corridor : 24) + rightW;
    const width = pad * 2 + Math.max(mainW, servicesRowW, primary.width);

    // Сколько нижних «полос» нужно под сервис↔внешние
    const svcExtCount = (data.links || []).filter((l) => {
        const a = byId.get(l.from);
        const b = byId.get(l.to);
        if (!a || !b) return false;
        const aSvc = services.some((s) => s.id === a.id);
        const bSvc = services.some((s) => s.id === b.id);
        const aExt = externals.some((s) => s.id === a.id) || people.some((s) => s.id === a.id);
        const bExt = externals.some((s) => s.id === b.id) || people.some((s) => s.id === b.id);
        return (aSvc && bExt) || (bSvc && aExt);
    }).length;

    const top = titleH + pad + colLabelH;
    const servicesGap = services.length ? 80 : 0;
    const servicesH = services.length ? Math.max(...services.map((n) => n.height)) : 0;
    const bottomExtra = svcExtCount ? bottomLaneGap + svcExtCount * 26 + 24 : 24;
    const height = top + bodyH + servicesGap + servicesH + bottomExtra + pad;

    const mainLeft = pad + Math.max(0, (width - pad * 2 - mainW) / 2);
    primary.x = mainLeft + leftW + (leftW ? corridor : 24);
    primary.y = top + (bodyH - primary.height) / 2;
    primary.cx = primary.x + primary.width / 2;
    primary.cy = primary.y + primary.height / 2;

    function placeCol(list, x) {
        let y = top + Math.max(0, (bodyH - stackHeight(list)) / 2);
        list.forEach((n) => {
            n.x = x;
            n.y = y;
            n.cx = n.x + n.width / 2;
            n.cy = n.y + n.height / 2;
            y += n.height + gapY;
        });
    }

    placeCol(people, mainLeft);
    placeCol(externals, primary.x + primary.width + corridor);

    if (services.length) {
        let sx = pad + Math.max(0, (width - pad * 2 - servicesRowW) / 2);
        const sy = top + bodyH + servicesGap;
        services.forEach((n) => {
            n.x = sx;
            n.y = sy;
            n.cx = n.x + n.width / 2;
            n.cy = n.y + n.height / 2;
            n._role = 'service';
            sx += n.width + serviceGapX;
        });
    }

    function classify(l) {
        const a = byId.get(l.from);
        const b = byId.get(l.to);
        if (!a || !b) return 'skip';
        const aP = people.some((p) => p.id === a.id);
        const bP = people.some((p) => p.id === b.id);
        const aE = externals.some((p) => p.id === a.id);
        const bE = externals.some((p) => p.id === b.id);
        const aS = services.some((p) => p.id === a.id);
        const bS = services.some((p) => p.id === b.id);
        const aPri = a.id === primary.id;
        const bPri = b.id === primary.id;

        if ((aPri && bP) || (bPri && aP)) return 'left';
        if ((aPri && bE) || (bPri && aE)) return 'right';
        if ((aPri && bS) || (bPri && aS)) return 'svcPrimary';
        if ((aS && bE) || (bS && aE) || (aS && bP) || (bS && aP)) return 'svcOuter';
        if (aS && bS) return 'svcSvc';
        return 'other';
    }

    const leftLinks = (data.links || []).filter((l) => classify(l) === 'left');
    const rightLinks = (data.links || []).filter((l) => classify(l) === 'right');
    const svcPrimary = (data.links || []).filter((l) => classify(l) === 'svcPrimary');
    const svcOuter = (data.links || []).filter((l) => classify(l) === 'svcOuter');
    const svcSvc = (data.links || []).filter((l) => classify(l) === 'svcSvc');
    const otherLinks = (data.links || []).filter((l) => classify(l) === 'other');

    // Сортируем боковые связи по Y внешнего узла — порт = человек/внешняя
    function outerOf(l, side) {
        const a = byId.get(l.from);
        const b = byId.get(l.to);
        if (side === 'left') return people.find((p) => p.id === a.id || p.id === b.id);
        return externals.find((p) => p.id === a.id || p.id === b.id);
    }
    leftLinks.sort((a, b) => (outerOf(a, 'left').cy || 0) - (outerOf(b, 'left').cy || 0));
    rightLinks.sort((a, b) => (outerOf(a, 'right').cy || 0) - (outerOf(b, 'right').cy || 0));

    function elbow(x1, y1, x2, y2, midX) {
        const mx = midX != null ? midX : (x1 + x2) / 2;
        return {
            x1, y1, x2, y2,
            points: [
                { x: x1, y: y1 },
                { x: mx, y: y1 },
                { x: mx, y: y2 },
                { x: x2, y: y2 }
            ],
            lx: mx,
            ly: (y1 + y2) / 2
        };
    }

    function buildSideLink(l, side, index, total) {
        const a = byId.get(l.from);
        const b = byId.get(l.to);
        const fromPrimary = a.id === primary.id;
        const outer = fromPrimary ? b : a;
        const ox = side === 'left' ? outer.x + outer.width : outer.x;
        const oy = outer.cy;
        // Порт на primary напротив outer
        const portY = Math.max(
            primary.y + 14,
            Math.min(primary.y + primary.height - 14, oy)
        );
        const px = side === 'left' ? primary.x : primary.x + primary.width;
        const x1 = fromPrimary ? px : ox;
        const y1 = fromPrimary ? portY : oy;
        const x2 = fromPrimary ? ox : px;
        const y2 = fromPrimary ? oy : portY;

        const leftBound = Math.min(x1, x2) + 28;
        const rightBound = Math.max(x1, x2) - 28;
        const span = Math.max(48, rightBound - leftBound);
        // Каждый индекс — свой вертикальный канал
        const t = (index + 1) / (Math.max(1, total) + 1);
        const midX = leftBound + span * t;
        const geo = elbow(x1, y1, x2, y2, midX);
        // Подпись смещена вдоль канала, не на середине Y чужих линий
        const labelSide = side === 'left' ? -1 : 1;
        geo.lx = midX + labelSide * 8;
        geo.ly = y1 + (y2 - y1) * (0.28 + (index % 3) * 0.18);
        return {
            from: l.from,
            to: l.to,
            label: l.label || '',
            line: l.line || null,
            points: geo.points,
            x1: geo.x1, y1: geo.y1, x2: geo.x2, y2: geo.y2,
            lx: geo.lx,
            ly: geo.ly
        };
    }

    const links = [];
    leftLinks.forEach((l, i) => links.push(buildSideLink(l, 'left', i, leftLinks.length)));
    rightLinks.forEach((l, i) => links.push(buildSideLink(l, 'right', i, rightLinks.length)));

    // Primary ↔ сервис: разные X-каналы, подписи слева/справа от линии
    svcPrimary.forEach((l, i) => {
        const other = byId.get(l.from === primary.id ? l.to : l.from);
        const fromPrimary = l.from === primary.id;
        const t = (i + 1) / (svcPrimary.length + 1);
        const portX = primary.x + primary.width * t;
        const x1 = fromPrimary ? portX : other.cx;
        const y1 = fromPrimary ? primary.y + primary.height : other.y;
        const x2 = fromPrimary ? other.cx : portX;
        const y2 = fromPrimary ? other.y : primary.y + primary.height;
        // Для пары встречных связей — разный midY и смещение подписи
        const pairKey = [l.from, l.to].sort().join('|');
        const siblings = svcPrimary.filter((x) => [x.from, x.to].sort().join('|') === pairKey);
        const sibIdx = siblings.indexOf(l);
        const midY = Math.min(y1, y2) + Math.abs(y2 - y1) * (0.35 + sibIdx * 0.22);
        const labelOffX = (sibIdx === 0 ? -1 : 1) * 56;
        links.push({
            from: l.from,
            to: l.to,
            label: l.label || '',
            line: l.line || null,
            points: [
                { x: x1, y: y1 },
                { x: x1, y: midY },
                { x: x2, y: midY },
                { x: x2, y: y2 }
            ],
            x1, y1, x2, y2,
            lx: (x1 + x2) / 2 + labelOffX,
            ly: midY - 10
        });
    });

    // Сервис ↔ внешняя/человек: полосы ПОД рядом сервисов (не через правый коридор)
    const svcBottom = services.length
        ? Math.max(...services.map((n) => n.y + n.height))
        : top + bodyH;
    svcOuter.forEach((l, i) => {
        const a = byId.get(l.from);
        const b = byId.get(l.to);
        const aIsSvc = services.some((s) => s.id === a.id);
        const from = aIsSvc ? a : b;
        const to = aIsSvc ? b : a;
        const laneY = svcBottom + 28 + i * 26;
        const x1 = from.cx;
        const y1 = from.y + from.height;
        const toRight = to.x > from.x;
        const x2 = toRight ? to.x : to.x + to.width;
        const y2 = to.cy;
        const midX = toRight
            ? to.x - 36 - (i % 3) * 16
            : to.x + to.width + 36 + (i % 3) * 16;
        links.push({
            from: l.from,
            to: l.to,
            label: l.label || '',
            line: l.line || null,
            points: [
                { x: x1, y: y1 },
                { x: x1, y: laneY },
                { x: midX, y: laneY },
                { x: midX, y: y2 },
                { x: x2, y: y2 }
            ],
            x1, y1, x2, y2,
            lx: (x1 + midX) / 2,
            ly: laneY - 10
        });
    });

    svcSvc.forEach((l, i) => {
        const a = byId.get(l.from);
        const b = byId.get(l.to);
        const midY = Math.min(a.y, b.y) - 20 - i * 16;
        links.push({
            from: l.from,
            to: l.to,
            label: l.label || '',
            line: l.line || null,
            points: [
                { x: a.cx, y: a.y },
                { x: a.cx, y: midY },
                { x: b.cx, y: midY },
                { x: b.cx, y: b.y }
            ],
            x1: a.cx, y1: a.y, x2: b.cx, y2: b.y,
            lx: (a.cx + b.cx) / 2,
            ly: midY - 8
        });
    });

    otherLinks.forEach((l, i) => {
        const a = byId.get(l.from);
        const b = byId.get(l.to);
        const midY = Math.min(a.y, b.y) - 24 - (i % 3) * 16;
        links.push({
            from: l.from,
            to: l.to,
            label: l.label || '',
            line: l.line || null,
            points: [
                { x: a.cx, y: a.y },
                { x: a.cx, y: midY },
                { x: b.cx, y: midY },
                { x: b.cx, y: b.y }
            ],
            x1: a.cx, y1: a.y, x2: b.cx, y2: b.y,
            lx: (a.cx + b.cx) / 2,
            ly: midY - 8
        });
    });

    // Развести подписи: AABB по приблизительной ширине
    const labeled = links.filter((l) => l.label);
    labeled.forEach((l) => {
        l._lw = Math.min(150, Math.max(40, String(l.label).length * 6.2 + 14));
    });
    for (let pass = 0; pass < 6; pass++) {
        for (let i = 0; i < labeled.length; i++) {
            for (let j = i + 1; j < labeled.length; j++) {
                const a = labeled[i];
                const b = labeled[j];
                const dx = Math.abs(a.lx - b.lx);
                const dy = Math.abs(a.ly - b.ly);
                const overlapX = dx < (a._lw + b._lw) / 2 + 8;
                const overlapY = dy < 18;
                if (overlapX && overlapY) {
                    if (a.ly <= b.ly) b.ly = a.ly + 20;
                    else a.ly = b.ly + 20;
                }
            }
        }
    }

    const colLabels = {
        left: people.length ? { text: 'Люди', x: mainLeft + leftW / 2, y: titleH + pad - 4 } : null,
        center: { text: 'Система', x: primary.cx, y: titleH + pad - 4 },
        right: externals.length
            ? { text: 'Внешние', x: primary.x + primary.width + corridor + rightW / 2, y: titleH + pad - 4 }
            : null,
        services: services.length
            ? { text: 'Внутренние сервисы', x: width / 2, y: top + bodyH + 28 }
            : null
    };

    return {
        title: data.title || '',
        subtitle: 'Люди слева · система в центре · внешние справа. Стрелки = кто с чем связан',
        nodes,
        links,
        colLabels,
        width: Math.max(640, Math.ceil(width)),
        height: Math.max(420, Math.ceil(height))
    };
}

