// ===== 55-svg-renderer-classic.js =====
// Классическая интеллект-карта (SimpleMind-стиль): плавные ветки, капсулы, цветные рукава

const CLASSIC_ROOT_FILL = '#2F5BA7';
const CLASSIC_ROOT_STROKE = '#1e40af';

function appendClassicPill(svgNS, parent, opts) {
    const { x, y, width, height, fill, stroke, strokeWidth, done, doneStyle } = opts;
    const soft = typeof isSoftDiagramStyle === 'function' && isSoftDiagramStyle();
    const rect = document.createElementNS(svgNS, 'rect');
    rect.setAttribute('x', x);
    rect.setAttribute('y', y);
    rect.setAttribute('width', width);
    rect.setAttribute('height', height);
    rect.setAttribute('rx', soft ? 18 : 8);
    if (done && doneStyle) {
        rect.setAttribute('fill', doneStyle.fill);
        rect.setAttribute('stroke', doneStyle.stroke);
        rect.setAttribute('stroke-width', doneStyle.strokeWidth);
    } else if (soft) {
        const f = typeof softMixFill === 'function' ? softMixFill(fill) : fill;
        const s = typeof softMixStroke === 'function' ? softMixStroke(stroke || fill) : stroke;
        rect.setAttribute('fill', f);
        rect.setAttribute('stroke', s);
        rect.setAttribute('stroke-width', String(Math.min(Number(strokeWidth) || 1.2, 0.9)));
        rect.setAttribute('fill-opacity', '0.98');
    } else {
        rect.setAttribute('fill', fill);
        rect.setAttribute('stroke', stroke);
        rect.setAttribute('stroke-width', String(strokeWidth || 2));
    }
    parent.appendChild(rect);
    return rect;
}

function classicNodeStyle(node) {
    const isDark = typeof document !== 'undefined' && document.body && document.body.classList.contains('dark');
    const soft = typeof isSoftDiagramStyle === 'function' && isSoftDiagramStyle();
    const done = !!node.done;
    const doneStyle = done ? getDoneNodeStyle(node.color) : null;

    if (node.level === 0) {
        return {
            fill: soft ? '#a78bfa' : CLASSIC_ROOT_FILL,
            stroke: soft ? '#8b5cf6' : CLASSIC_ROOT_STROKE,
            text: getContrastColor(soft ? '#a78bfa' : CLASSIC_ROOT_FILL),
            strokeWidth: soft ? 1.4 : 2.5,
            done,
            doneStyle
        };
    }
    if (node.level === 1) {
        if (doneStyle) {
            return { fill: doneStyle.fill, stroke: doneStyle.stroke, text: doneStyle.text, strokeWidth: doneStyle.strokeWidth, done, doneStyle };
        }
        return {
            fill: soft && typeof softMixFill === 'function' ? softMixFill(node.color) : node.color,
            stroke: soft
                ? (typeof softMixStroke === 'function' ? softMixStroke(node.color) : node.color)
                : (typeof mixHex === 'function' ? mixHex(node.color, '#000000', 0.14) : node.color),
            text: getContrastColor(soft && typeof softMixFill === 'function' ? softMixFill(node.color) : node.color),
            strokeWidth: soft ? 1.2 : 2.25,
            done,
            doneStyle: null
        };
    }
    const panel = typeof readCssColor === 'function'
        ? readCssColor('--panel-bg', isDark ? '#1e293b' : '#ffffff')
        : (isDark ? '#1e293b' : '#ffffff');
    if (doneStyle) {
        return { fill: doneStyle.fill, stroke: doneStyle.stroke, text: doneStyle.text, strokeWidth: doneStyle.strokeWidth, done, doneStyle };
    }
    return {
        fill: panel,
        stroke: node.color,
        text: isDark ? '#e2e8f0' : '#1e293b',
        strokeWidth: 2.5,
        done,
        doneStyle: null
    };
}

function edgeAnchor(node, towardX, towardY) {
    const noteEx = typeof diagramNodeNoteExtra === 'function' ? diagramNodeNoteExtra(node) : 0;
    const cx = node.x;
    const cy = typeof diagramNodeCenteredVisualCY === 'function'
        ? diagramNodeCenteredVisualCY(node)
        : (node.y - noteEx / 2);
    const dx = towardX - cx;
    const dy = towardY - cy;
    const dist = Math.hypot(dx, dy) || 1;
    const pad = 2;
    return {
        x: cx + (dx / dist) * (node.width / 2 - pad),
        y: cy + (dy / dist) * (node.height / 2 + (dy > 0 ? noteEx : 0) - pad)
    };
}

function classicCurvePath(x1, y1, x2, y2, side) {
    const bend = Math.max(48, Math.abs(x2 - x1) * 0.52);
    const sign = side === 'left' ? -1 : 1;
    const c1x = x1 + sign * bend;
    const c1y = y1;
    const c2x = x2 - sign * bend * 0.42;
    const c2y = y2;
    return `M ${x1} ${y1} C ${c1x} ${c1y}, ${c2x} ${c2y}, ${x2} ${y2}`;
}

function generateClassicSVG(root, options) {
    options = options && typeof options === 'object' ? options : {};
    computeSizes(root);
    root.width = Math.min(300, root.width + 28);
    root.height = root.height + 12;
    root.layoutHeight = root.height + (root.noteHeight || 0);

    computeWeights(root);
    const gaps = typeof getClassicLayoutGaps === 'function'
        ? getClassicLayoutGaps(options.spacingScale)
        : { gapX: 190, gapY: 28 };
    layoutClassic(root, gaps.gapX, gaps.gapY);
    resolveOverlapsClassic(root);
    if (typeof prepareTreeManualLayout === 'function') {
        prepareTreeManualLayout(root, typeof getLayoutOverrides === 'function' ? getLayoutOverrides() : null);
    }

    const bounds = getBounds(root, 90, { centered: true });
    const width = bounds.maxX - bounds.minX;
    const height = bounds.maxY - bounds.minY;
    const svgNS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(svgNS, 'svg');
    svg.setAttribute('viewBox', `${bounds.minX} ${bounds.minY} ${width} ${height}`);
    svg.setAttribute('width', width);
    svg.setAttribute('height', height);
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', 'Классическая интеллект-карта');
    svg.style.fontFamily = (typeof getUiFontFamily === 'function'
        ? getUiFontFamily()
        : 'system-ui, -apple-system, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif');
    svg.style.fontSize = '16px';

    const linesGroup = document.createElementNS(svgNS, 'g');
    const nodesGroup = document.createElementNS(svgNS, 'g');
    const notesGroup = document.createElementNS(svgNS, 'g');
    svg.appendChild(linesGroup);
    svg.appendChild(nodesGroup);
    svg.appendChild(notesGroup);

    function drawLines(node) {
        for (const child of node.children) {
            const side = child.side || (child.x >= node.x ? 'right' : 'left');
            const towardChildY = typeof diagramNodeCenteredVisualCY === 'function'
                ? diagramNodeCenteredVisualCY(child)
                : child.y;
            const towardParentY = typeof diagramNodeCenteredVisualCY === 'function'
                ? diagramNodeCenteredVisualCY(node)
                : node.y;
            const p1 = edgeAnchor(node, child.x, towardChildY);
            const p2 = edgeAnchor(child, node.x, towardParentY);
            const path = document.createElementNS(svgNS, 'path');
            path.setAttribute('d', classicCurvePath(p1.x, p1.y, p2.x, p2.y, side));
            path.setAttribute('fill', 'none');
            path.setAttribute('stroke', child.color);
            path.setAttribute('stroke-width', Math.max(3.5, 16 - child.level * 3.2).toFixed(1));
            path.setAttribute('stroke-linecap', 'round');
            path.setAttribute('opacity', '0.9');
            path.setAttribute('pointer-events', 'none');
            linesGroup.appendChild(path);

            if (child.level === 1) {
                const dot = document.createElementNS(svgNS, 'circle');
                dot.setAttribute('cx', String(p1.x));
                dot.setAttribute('cy', String(p1.y));
                dot.setAttribute('r', '4.5');
                dot.setAttribute('fill', child.color);
                dot.setAttribute('opacity', '0.95');
                dot.setAttribute('pointer-events', 'none');
                linesGroup.appendChild(dot);
            }

            drawLines(child);
        }
    }
    drawLines(root);

    function drawNodes(node) {
        const left = node.x - node.width / 2;
        const top = typeof diagramNodeCenteredBoxTop === 'function'
            ? diagramNodeCenteredBoxTop(node)
            : (node.y - node.height / 2);
        const cy = top + node.height / 2;
        const style = classicNodeStyle(node);
        const nodeId = node.id || node.text;

        const g = document.createElementNS(svgNS, 'g');
        g.setAttribute('class', 'mm-node');
        g.setAttribute('data-node-id', String(nodeId));
        nodesGroup.appendChild(g);

        const rect = appendClassicPill(svgNS, g, {
            x: left,
            y: top,
            width: node.width,
            height: node.height,
            fill: style.fill,
            stroke: style.stroke,
            strokeWidth: style.strokeWidth,
            done: style.done,
            doneStyle: style.doneStyle
        });
        if (node.href) rect.setAttribute('data-pdf-href', node.href);
        if (typeof setDiagramSourceLine === 'function') setDiagramSourceLine(rect, node.sourceLine);

        appendWrappedSvgText(svgNS, g, {
            x: node.x,
            y: cy + 1,
            lines: node.lines || [node.text],
            fill: style.text,
            fontSize: node.level === 0 ? 20 : (node.level === 1 ? 17 : 16),
            fontWeight: node.level === 0 ? '700' : (node.level === 1 ? '650' : '600'),
            lineHeight: node.level === 0 ? 25 : 21,
            underline: !!node.href,
            dataLabel: node.text,
            dataNodeId: nodeId,
            dataSourceLine: node.sourceLine || null,
            href: node.href || null
        });

        if (style.done) {
            const r = node.level === 0 ? 10 : 8;
            appendDoneCheckmark(svgNS, g, left + node.width - 2, top + 2, r);
        }
        if (typeof appendDiagramNodeMeta === 'function') {
            appendDiagramNodeMeta(svgNS, g, {
                x: left, y: top, width: node.width, height: node.height
            }, node, {
                avatarR: node.level === 0 ? 20 : 17,
                deadlineFontSize: 12,
                deadlineH: 20
            });
        }
        if (typeof appendDiagramNodeNote === 'function' && node.note) {
            const noteTop = typeof diagramNodeNoteTopY === 'function'
                ? diagramNodeNoteTopY(top + node.height, node)
                : (top + node.height + 8);
            appendDiagramNodeNote(svgNS, g, node.x, noteTop, node);
        }

        for (const child of node.children) drawNodes(child);
    }
    drawNodes(root);

    return { svg, width, height, svgString: new XMLSerializer().serializeToString(svg) };
}

;

// ===== 56-svg-renderer-sequence.js =====
/**
 * Генерация SVG для диаграммы последовательностей (адаптивные цвета групп, плашки, привязка комментариев).
 */
function generateSequenceSVG(layoutData, themeColors) {
    const { participants, items, width, height, activationHeight, title } = layoutData;
    const svgNS = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(svgNS, "svg");
    svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
    svg.setAttribute("width", width);
    svg.setAttribute("height", height);
    svg.style.fontFamily = (typeof getUiFontFamily === "function" ? getUiFontFamily() : "system-ui, -apple-system, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif");
    svg.style.fontSize = "14px";

    const isDark = document.body.classList.contains('dark');
    const primaryTextColor = isDark ? '#e0e0e0' : '#1f2937';
    const secondaryTextColor = isDark ? '#aaa' : '#6b7280';
    const dividerColor = isDark ? '#4b5563' : '#cbd5e1';
    const lifelineColor = isDark ? '#4b5563' : '#cbd5e1';
    const participantTextColor = isDark ? '#f3f4f6' : '#111827';
    const noteLinkColor = isDark ? '#a8a29e' : '#a8a29e';
    const noteFill = isDark ? '#422006' : '#fef9c3';
    const noteStroke = isDark ? '#a8a29e' : '#eab308';
    const noteText = isDark ? '#fef3c7' : '#1f2937';
    const panelFill = typeof readCssColor === 'function'
        ? readCssColor('--panel-bg', isDark ? '#1c1c1e' : '#ffffff')
        : (isDark ? '#1c1c1e' : '#ffffff');
    const diagramBg = typeof readCssColor === 'function'
        ? readCssColor('--diagram-bg', isDark ? '#161618' : '#f8fafc')
        : (isDark ? '#161618' : '#f8fafc');

    const groupStyleKeys = {
        'начало ветки': 'ветка',
        'начало цикла': 'цикл',
        'начало параллельных действий': 'параллельные действия',
        'начало опционально': 'опционально'
    };

    // Рамки групп: спокойнее палитра + мягкий пунктир (длиннее пробел, тоньше штрих)
    const groupColors = {
        ветка: {
            stroke: isDark ? '#94a3b8' : '#94a3b8',
            dasharray: '5,7',
            strokeWidth: '1.5',
            badgeFill: isDark ? '#334155' : '#f1f5f9',
            badgeText: isDark ? '#e2e8f0' : '#334155'
        },
        цикл: {
            stroke: isDark ? '#7dd3fc' : '#38bdf8',
            dasharray: 'none',
            strokeWidth: '1.75',
            badgeFill: isDark ? '#0c4a6e' : '#e0f2fe',
            badgeText: isDark ? '#bae6fd' : '#075985'
        },
        'параллельные действия': {
            stroke: isDark ? '#fbbf24' : '#d97706',
            dasharray: '6,6',
            strokeWidth: '1.5',
            badgeFill: isDark ? '#78350f' : '#fffbeb',
            badgeText: isDark ? '#fde68a' : '#92400e'
        },
        опционально: {
            stroke: isDark ? '#6ee7b7' : '#34d399',
            dasharray: '4,6',
            strokeWidth: '1.5',
            badgeFill: isDark ? '#064e3b' : '#ecfdf5',
            badgeText: isDark ? '#a7f3d0' : '#065f46'
        }
    };

    const defs = document.createElementNS(svgNS, "defs");
    participants.forEach(p => {
        const marker = document.createElementNS(svgNS, "marker");
        marker.setAttribute("id", `arrow-${p.name.replace(/\s/g, '')}`);
        marker.setAttribute("markerWidth", "10");
        marker.setAttribute("markerHeight", "10");
        marker.setAttribute("refX", "9");
        marker.setAttribute("refY", "3");
        marker.setAttribute("orient", "auto");
        const arrowPath = document.createElementNS(svgNS, "path");
        arrowPath.setAttribute("d", "M0,0 L0,6 L9,3 z");
        arrowPath.setAttribute("fill", p.color);
        marker.appendChild(arrowPath);
        defs.appendChild(marker);
    });
    svg.appendChild(defs);

    const linesGroup = document.createElementNS(svgNS, "g");
    const bgGroup = document.createElementNS(svgNS, "g");
    const activationsGroup = document.createElementNS(svgNS, "g");
    const messagesGroup = document.createElementNS(svgNS, "g");
    const notesGroup = document.createElementNS(svgNS, "g");
    const labelsGroup = document.createElementNS(svgNS, "g");
    svg.appendChild(linesGroup);
    svg.appendChild(bgGroup);
    svg.appendChild(activationsGroup);
    svg.appendChild(messagesGroup);
    svg.appendChild(notesGroup);
    svg.appendChild(labelsGroup);

    if (title) {
        const titleEl = document.createElementNS(svgNS, "text");
        titleEl.setAttribute("x", width / 2);
        titleEl.setAttribute("y", 28);
        titleEl.setAttribute("fill", primaryTextColor);
        titleEl.setAttribute("text-anchor", "middle");
        titleEl.setAttribute("font-weight", "700");
        titleEl.setAttribute("font-size", "16px");
        titleEl.textContent = title;
        labelsGroup.appendChild(titleEl);
    }

    participants.forEach(p => {
        const label = p.alias || p.name;
        const boxH = 30;
        const boxW = Math.max(72, Math.min(168, String(label).length * 7.4 + 28));
        const boxX = p.x - boxW / 2;
        const boxY = p.y - boxH;
        const srcLine = p.sourceLine || p.line;

        const g = document.createElementNS(svgNS, "g");
        if (typeof setDiagramSourceLine === 'function') setDiagramSourceLine(g, srcLine);

        const head = document.createElementNS(svgNS, "rect");
        head.setAttribute("x", boxX);
        head.setAttribute("y", boxY);
        head.setAttribute("width", boxW);
        head.setAttribute("height", boxH);
        head.setAttribute("rx", "7");
        head.setAttribute("fill", panelFill);
        head.setAttribute("stroke", p.color || lifelineColor);
        head.setAttribute("stroke-width", "1.75");
        g.appendChild(head);

        const line = document.createElementNS(svgNS, "line");
        line.setAttribute("x1", p.x);
        line.setAttribute("y1", p.y);
        line.setAttribute("x2", p.x);
        line.setAttribute("y2", height - 40);
        // Lifeline нейтральный — цвет участника только на стрелках/активациях
        line.setAttribute("stroke", lifelineColor);
        line.setAttribute("stroke-width", "1.25");
        line.setAttribute("stroke-dasharray", "4,5");
        line.setAttribute("pointer-events", "none");
        linesGroup.appendChild(line);

        const text = document.createElementNS(svgNS, "text");
        text.setAttribute("x", p.x);
        text.setAttribute("y", boxY + boxH / 2 + 1);
        text.setAttribute("fill", participantTextColor);
        text.setAttribute("text-anchor", "middle");
        text.setAttribute("dominant-baseline", "central");
        text.setAttribute("font-weight", "600");
        text.setAttribute("font-size", "13px");
        text.textContent = label;
        text.setAttribute('data-label', label);
        g.appendChild(text);
        labelsGroup.appendChild(g);
    });

    function tagMessageHit(el, item, x1, y1, x2, y2) {
        const src = item.line || item.sourceLine;
        if (typeof setDiagramSourceLine === 'function') setDiagramSourceLine(el, src);
        messagesGroup.appendChild(el);
        // Невидимый хит-бокс вокруг стрелки/подписи — ПКМ по тексту, не только по штриху
        const pad = 14;
        const minX = Math.min(x1, x2) - pad;
        const maxX = Math.max(x1, x2) + pad;
        const minY = Math.min(y1, y2) - pad;
        const maxY = Math.max(y1, y2) + pad;
        const hit = document.createElementNS(svgNS, "rect");
        hit.setAttribute("x", minX);
        hit.setAttribute("y", minY);
        hit.setAttribute("width", Math.max(24, maxX - minX));
        hit.setAttribute("height", Math.max(24, maxY - minY));
        hit.setAttribute("fill", "transparent");
        hit.setAttribute("stroke", "none");
        if (typeof setDiagramSourceLine === 'function') setDiagramSourceLine(hit, src);
        messagesGroup.appendChild(hit);
    }

    function renderItems(itemList) {
        for (const [index, item] of itemList.entries()) {
            if (item.type === 'message') {
                const fromP = participants.find(p => p.name === item.from);
                const toP = participants.find(p => p.name === item.to);
                if (!fromP || !toP) continue;
                // Координаты lifeline — у участника (не у устаревшего item.x1 после сдвига полей)
                const x1 = fromP.x;
                const x2 = toP.x;

                if (item.isSelf) {
                    const cx = x1;
                    const yStart = item.y - 4;
                    const yEnd = item.y + 12;
                    const dx = 90;

                    const activation = document.createElementNS(svgNS, "rect");
                    activation.setAttribute("x", cx - 4);
                    activation.setAttribute("y", yStart);
                    activation.setAttribute("width", 8);
                    activation.setAttribute("height", yEnd - yStart);
                    activation.setAttribute("fill", fromP.color);
                    activation.setAttribute("opacity", "0.35");
                    activationsGroup.appendChild(activation);

                    const path = document.createElementNS(svgNS, "path");
                    path.setAttribute("d", `M${cx},${yStart} C${cx+dx},${yStart-10} ${cx+dx},${yEnd+10} ${cx},${yEnd}`);
                    path.setAttribute("stroke", fromP.color);
                    path.setAttribute("stroke-width", "1.75");
                    path.setAttribute("fill", "none");
                    if (item.arrowType === '-->') path.setAttribute("stroke-dasharray", "5,6");
                    path.setAttribute("marker-end", `url(#arrow-${fromP.name.replace(/\s/g, '')})`);
                    tagMessageHit(path, item, cx, yStart, cx + dx, yEnd);

                    let displayText = item.text;
                    if (item.number) displayText = `${item.number}: ${displayText}`;
                    const text = document.createElementNS(svgNS, "text");
                    text.setAttribute("x", cx + dx/2);
                    text.setAttribute("y", yStart + (yEnd - yStart)/2 + 4);
                    text.setAttribute("fill", primaryTextColor);
                    text.setAttribute("text-anchor", "middle");
                    text.setAttribute("font-size", "12px");
                    text.setAttribute("paint-order", "stroke");
                    text.setAttribute("stroke", diagramBg);
                    text.setAttribute("stroke-width", "3.5");
                    text.textContent = displayText;
                    if (typeof setDiagramSourceLine === 'function') {
                        setDiagramSourceLine(text, item.line || item.sourceLine);
                    }
                    messagesGroup.appendChild(text);
                } else {
                    const activation = document.createElementNS(svgNS, "rect");
                    activation.setAttribute("x", x1 - 4);
                    activation.setAttribute("y", item.activationY);
                    activation.setAttribute("width", 8);
                    activation.setAttribute("height", item.height);
                    activation.setAttribute("fill", fromP.color);
                    activation.setAttribute("opacity", "0.35");
                    activationsGroup.appendChild(activation);

                    const line = document.createElementNS(svgNS, "line");
                    line.setAttribute("x1", x1);
                    line.setAttribute("y1", item.y);
                    line.setAttribute("x2", x2 + (x2 > x1 ? -10 : 10));
                    line.setAttribute("y2", item.y);
                    line.setAttribute("stroke", fromP.color);
                    line.setAttribute("stroke-width", "1.75");
                    line.setAttribute("stroke-linecap", "round");
                    if (item.arrowType === '-->') line.setAttribute("stroke-dasharray", "5,6");
                    line.setAttribute("marker-end", `url(#arrow-${fromP.name.replace(/\s/g, '')})`);
                    tagMessageHit(line, item, x1, item.y, x2, item.y);

                    let displayText = item.text;
                    if (item.number) displayText = `${item.number}: ${displayText}`;
                    const text = document.createElementNS(svgNS, "text");
                    const midX = (x1 + x2) / 2;
                    text.setAttribute("x", midX);
                    text.setAttribute("y", item.y - 6);
                    text.setAttribute("fill", primaryTextColor);
                    text.setAttribute("text-anchor", "middle");
                    text.setAttribute("font-size", "12px");
                    text.setAttribute("paint-order", "stroke");
                    text.setAttribute("stroke", diagramBg);
                    text.setAttribute("stroke-width", "3.5");
                    text.textContent = displayText;
                    if (typeof setDiagramSourceLine === 'function') {
                        setDiagramSourceLine(text, item.line || item.sourceLine);
                    }
                    messagesGroup.appendChild(text);
                }
            } else if (item.type === 'group_start') {
                if (item.x !== undefined && item.width !== undefined && item.boxH !== undefined) {
                    const rect = document.createElementNS(svgNS, "rect");
                    rect.setAttribute("x", item.x);
                    rect.setAttribute("y", item.boxY);
                    rect.setAttribute("width", item.width);
                    rect.setAttribute("height", item.boxH);
                    rect.setAttribute("fill", "transparent");
                    rect.setAttribute("rx", "10");
                    rect.setAttribute("pointer-events", "all");
                    if (typeof setDiagramSourceLine === 'function') {
                        setDiagramSourceLine(rect, item.line || item.sourceLine);
                    }

                    const mappedKey = groupStyleKeys[item.group] || item.group;
                    const style = groupColors[mappedKey];
                    if (style) {
                        rect.setAttribute("stroke", style.stroke);
                        rect.setAttribute("stroke-width", style.strokeWidth || "1.5");
                        if (style.dasharray && style.dasharray !== 'none') {
                            rect.setAttribute("stroke-dasharray", style.dasharray);
                        }

                        if (mappedKey === 'цикл') {
                            const innerRect = document.createElementNS(svgNS, "rect");
                            innerRect.setAttribute("x", item.x + 4);
                            innerRect.setAttribute("y", item.boxY + 4);
                            innerRect.setAttribute("width", item.width - 8);
                            innerRect.setAttribute("height", item.boxH - 8);
                            innerRect.setAttribute("fill", "none");
                            innerRect.setAttribute("stroke", style.stroke);
                            innerRect.setAttribute("stroke-width", "1");
                            innerRect.setAttribute("stroke-opacity", "0.45");
                            innerRect.setAttribute("rx", "8");
                            bgGroup.appendChild(innerRect);
                        }

                        const badgeX = item.x + 10;
                        const badgeY = item.boxY + 6;
                        const badgeHeight = 20;
                        let icon = '';
                        if (mappedKey === 'цикл') icon = '🔁 ';
                        else if (mappedKey === 'параллельные действия') icon = '⚡ ';
                        const groupShortNames = {
                            'начало ветки': 'выбор',
                            'начало цикла': 'цикл',
                            'начало параллельных действий': 'параллельно',
                            'начало опционально': 'если'
                        };
                        const shortName = groupShortNames[item.group] || mappedKey;
                        // С подписью из текста — только она; без подписи — короткое имя блока (не «Начало цикла»)
                        const labelText = icon + (item.label || shortName);
                        const textWidth = Math.max(labelText.length * 8 + 16, 48);

                        const badge = document.createElementNS(svgNS, "rect");
                        badge.setAttribute("x", badgeX);
                        badge.setAttribute("y", badgeY);
                        badge.setAttribute("width", textWidth);
                        badge.setAttribute("height", badgeHeight);
                        badge.setAttribute("rx", "4");
                        badge.setAttribute("fill", style.badgeFill);
                        badge.setAttribute("stroke", style.stroke);
                        badge.setAttribute("stroke-width", "1.5");
                        bgGroup.appendChild(badge);

                        const badgeLabel = document.createElementNS(svgNS, "text");
                        badgeLabel.setAttribute("x", badgeX + 8);
                        badgeLabel.setAttribute("y", badgeY + 14);
                        badgeLabel.setAttribute("fill", style.badgeText);
                        badgeLabel.setAttribute("font-size", "11px");
                        badgeLabel.setAttribute("font-weight", "bold");
                        badgeLabel.textContent = labelText;
                        bgGroup.appendChild(badgeLabel);
                    }

                    bgGroup.appendChild(rect);
                }
                if (item.items) renderItems(item.items);
            } else if (item.type === 'comment_start') {
                const boxRect = document.createElementNS(svgNS, "rect");
                boxRect.setAttribute("x", item.x);
                boxRect.setAttribute("y", item.boxY);
                boxRect.setAttribute("width", item.width);
                boxRect.setAttribute("height", item.boxH);
                boxRect.setAttribute("fill", noteFill);
                boxRect.setAttribute("stroke", noteStroke);
                boxRect.setAttribute("stroke-width", "1.5");
                boxRect.setAttribute("rx", "6");
                if (typeof setDiagramSourceLine === 'function') {
                    setDiagramSourceLine(boxRect, item.line || item.sourceLine);
                }
                notesGroup.appendChild(boxRect);

                const commentText = document.createElementNS(svgNS, "text");
                commentText.setAttribute("x", item.x + 8);
                commentText.setAttribute("y", item.boxY + 20);
                commentText.setAttribute("fill", noteText);
                commentText.setAttribute("font-size", "12px");
                if (typeof setDiagramSourceLine === 'function') {
                    setDiagramSourceLine(commentText, item.line || item.sourceLine);
                }
                const words = item.label.split(' ');
                let line = '';
                let tspans = [];
                words.forEach(word => {
                    if ((line + word).length > 20) {
                        tspans.push(line.trim());
                        line = word + ' ';
                    } else {
                        line += word + ' ';
                    }
                });
                if (line) tspans.push(line.trim());
                tspans.forEach((txt, idx) => {
                    const tspan = document.createElementNS(svgNS, "tspan");
                    tspan.setAttribute("x", item.x + 8);
                    if (idx > 0) tspan.setAttribute("dy", "1.2em");
                    tspan.textContent = txt;
                    commentText.appendChild(tspan);
                });
                notesGroup.appendChild(commentText);

                const targetPos = participants.find(p => p.name === item.target);
                if (targetPos) {
                    const connectX = targetPos.x;
                    const connectY = item.boxY + item.boxH / 2;
                    const lineToDiagram = document.createElementNS(svgNS, "line");
                    lineToDiagram.setAttribute("x1", item.side === 'left' ? item.x + item.width : item.x);
                    lineToDiagram.setAttribute("y1", connectY);
                    lineToDiagram.setAttribute("x2", connectX);
                    lineToDiagram.setAttribute("y2", connectY);
                    lineToDiagram.setAttribute("stroke", noteLinkColor);
                    lineToDiagram.setAttribute("stroke-width", "1.25");
                    lineToDiagram.setAttribute("stroke-dasharray", "4,6");
                    notesGroup.appendChild(lineToDiagram);
                }

                if (item.items) renderItems(item.items);
            } else if (item.type === 'divider') {
                const leftX = Math.min(...participants.map(p => p.x)) - 30;
                const rightX = Math.max(...participants.map(p => p.x)) + 30;
                const line = document.createElementNS(svgNS, "line");
                line.setAttribute("x1", leftX);
                line.setAttribute("y1", item.y);
                line.setAttribute("x2", rightX);
                line.setAttribute("y2", item.y);
                line.setAttribute("stroke", dividerColor);
                line.setAttribute("stroke-width", "1");
                line.setAttribute("stroke-dasharray", "3,7");
                bgGroup.appendChild(line);

                const label = document.createElementNS(svgNS, "text");
                label.setAttribute("x", leftX + 10);
                label.setAttribute("y", item.y - 5);
                label.setAttribute("fill", secondaryTextColor);
                label.setAttribute("font-size", "12px");
                label.textContent = item.label;
                if (typeof setDiagramSourceLine === 'function') {
                    setDiagramSourceLine(line, item.line || item.sourceLine);
                    setDiagramSourceLine(label, item.line || item.sourceLine);
                }
                bgGroup.appendChild(label);
            } else if (item.type === 'deactivate' || item.type === 'activate' || item.type === 'create') {
                const targetName = item.target;
                const p = participants.find(pp =>
                    pp.name === targetName ||
                    pp.alias === targetName ||
                    (pp.alias && pp.alias.toLowerCase() === String(targetName).toLowerCase()) ||
                    pp.name.toLowerCase() === String(targetName).toLowerCase()
                );
                if (p) {
                    const src = item.line || item.sourceLine;
                    if (item.type === 'deactivate') {
                        const s = 7;
                        const cross1 = document.createElementNS(svgNS, "line");
                        cross1.setAttribute("x1", p.x - s);
                        cross1.setAttribute("y1", item.y - s);
                        cross1.setAttribute("x2", p.x + s);
                        cross1.setAttribute("y2", item.y + s);
                        cross1.setAttribute("stroke", p.color);
                        cross1.setAttribute("stroke-width", "2.5");
                        if (typeof setDiagramSourceLine === 'function') setDiagramSourceLine(cross1, src);
                        messagesGroup.appendChild(cross1);
                        const cross2 = document.createElementNS(svgNS, "line");
                        cross2.setAttribute("x1", p.x + s);
                        cross2.setAttribute("y1", item.y - s);
                        cross2.setAttribute("x2", p.x - s);
                        cross2.setAttribute("y2", item.y + s);
                        cross2.setAttribute("stroke", p.color);
                        cross2.setAttribute("stroke-width", "2.5");
                        if (typeof setDiagramSourceLine === 'function') setDiagramSourceLine(cross2, src);
                        messagesGroup.appendChild(cross2);
                        const hit = document.createElementNS(svgNS, "rect");
                        hit.setAttribute("x", p.x - 16);
                        hit.setAttribute("y", item.y - 16);
                        hit.setAttribute("width", 32);
                        hit.setAttribute("height", 32);
                        hit.setAttribute("fill", "transparent");
                        if (typeof setDiagramSourceLine === 'function') setDiagramSourceLine(hit, src);
                        messagesGroup.appendChild(hit);
                    } else if (item.type === 'activate') {
                        // Simmetrika: the bar runs down through the participant's next messages in this
                        // block (it was a stub at the command, above the message it belongs to).
                        let startY = item.y - 8;
                        let endY = item.y + 10;
                        let first = true;
                        for (const next of itemList.slice(index + 1)) {
                            if (next.type === 'deactivate' && (next.target === p.name || next.target === p.alias)) break;
                            if (next.type === 'message' && (next.from === p.name || next.to === p.name)) {
                                if (first) startY = next.y - 10;
                                first = false;
                                endY = next.y + 10;
                            }
                        }
                        const bar = document.createElementNS(svgNS, "rect");
                        bar.setAttribute("x", p.x - 5);
                        bar.setAttribute("y", startY);
                        bar.setAttribute("width", 10);
                        bar.setAttribute("height", endY - startY);
                        bar.setAttribute("fill", p.color);
                        bar.setAttribute("opacity", "0.75");
                        if (typeof setDiagramSourceLine === 'function') setDiagramSourceLine(bar, src);
                        activationsGroup.appendChild(bar);
                    } else if (item.type === 'create') {
                        // As wide as its text (a fixed 56 px let «создать» out of the frame).
                        const label = '«создать»';
                        const boxW = Math.max(56, Math.ceil((typeof wrapTextLines === 'function' && wrapTextLines._canvas
                            ? (() => { const c = wrapTextLines._canvas.getContext('2d'); c.font = '11px ' + (typeof getUiFontFamily === 'function' ? getUiFontFamily() : 'system-ui'); return c.measureText(label).width; })()
                            : label.length * 6.2) + 18));
                        const box = document.createElementNS(svgNS, "rect");
                        box.setAttribute("x", p.x - boxW / 2);
                        box.setAttribute("y", item.y - 12);
                        box.setAttribute("width", boxW);
                        box.setAttribute("height", 22);
                        box.setAttribute("rx", "4");
                        box.setAttribute("fill", isDark ? '#1c1c1e' : '#fff');
                        box.setAttribute("stroke", p.color);
                        box.setAttribute("stroke-width", "2");
                        if (typeof setDiagramSourceLine === 'function') setDiagramSourceLine(box, src);
                        messagesGroup.appendChild(box);
                        const t = document.createElementNS(svgNS, "text");
                        t.setAttribute("x", p.x);
                        t.setAttribute("y", item.y + 3);
                        t.setAttribute("text-anchor", "middle");
                        t.setAttribute("font-size", "11px");
                        t.setAttribute("fill", primaryTextColor);
                        t.textContent = label;
                        if (typeof setDiagramSourceLine === 'function') setDiagramSourceLine(t, src);
                        messagesGroup.appendChild(t);
                    }
                }
            }
        }
    }

    renderItems(items);
    return { svg, width, height, svgString: new XMLSerializer().serializeToString(svg) };
}
;

// ===== 57-svg-renderer-bpmn.js =====
function generateBPMNSVG(layoutData, themeColors) {
    const { lanes, pools, elements, flows, width, height, taskWidth, taskHeight, eventRadius, gatewaySize, processName } = layoutData;
    const svgNS = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(svgNS, "svg");
    svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
    svg.setAttribute("width", width);
    svg.setAttribute("height", height);
    svg.style.fontFamily = (typeof getUiFontFamily === "function" ? getUiFontFamily() : "system-ui, -apple-system, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif");
    svg.style.fontSize = "14px";

    const isDark = document.body.classList.contains('dark');
    const theme = themeColors || [];
    const primaryColor = theme.length > 0 ? theme[0] : (isDark ? '#60a5fa' : '#3b82f6');
    const textColor = isDark ? '#e0e0e0' : '#1f2937';
    const laneBaseFill = typeof readCssColor === 'function'
        ? readCssColor('--diagram-bg', isDark ? '#161618' : '#f8fafc')
        : (isDark ? '#161618' : '#f8fafc');
    const elementFill = typeof readCssColor === 'function'
        ? readCssColor('--panel-bg', isDark ? '#1c1c1e' : '#ffffff')
        : (isDark ? '#334155' : '#ffffff');
    // Обводка фигур и стрелки = цвет дорожки-источника
    let elementStroke = primaryColor;

    const laneColorByName = new Map();
    lanes.forEach(({ lane }, idx) => {
        const c = theme.length > 0 ? theme[idx % theme.length] : primaryColor;
        laneColorByName.set(lane.name, c);
    });
    function softLaneFill(hex) {
        if (typeof mixHex !== 'function') return laneBaseFill;
        return mixHex(hex, laneBaseFill, isDark ? 0.86 : 0.90);
    }
    function softLaneHeader(hex) {
        if (typeof mixHex !== 'function') return laneBaseFill;
        return mixHex(hex, laneBaseFill, isDark ? 0.72 : 0.78);
    }
    function colorForLane(name) {
        return (name && laneColorByName.get(name)) || primaryColor;
    }

    const bgGroup = document.createElementNS(svgNS, "g");
    const poolGroup = document.createElementNS(svgNS, "g");
    const laneGroup = document.createElementNS(svgNS, "g");
    const flowGroup = document.createElementNS(svgNS, "g");
    const elementGroup = document.createElementNS(svgNS, "g");
    const labelGroup = document.createElementNS(svgNS, "g");
    svg.appendChild(bgGroup);
    svg.appendChild(poolGroup);
    svg.appendChild(laneGroup);
    svg.appendChild(flowGroup);
    svg.appendChild(elementGroup);
    svg.appendChild(labelGroup);

    if (processName) {
        const titleEl = document.createElementNS(svgNS, "text");
        titleEl.setAttribute("x", width / 2);
        titleEl.setAttribute("y", 36);
        titleEl.setAttribute("fill", textColor);
        titleEl.setAttribute("text-anchor", "middle");
        titleEl.setAttribute("font-weight", "700");
        titleEl.setAttribute("font-size", "16px");
        titleEl.textContent = processName;
        labelGroup.appendChild(titleEl);
    }

    const defs = document.createElementNS(svgNS, "defs");
    const arrowMarkers = new Map();
    function arrowMarkerId(color) {
        const key = String(color || primaryColor);
        if (arrowMarkers.has(key)) return arrowMarkers.get(key);
        const id = 'bpmn-arrow-' + key.replace(/[^a-fA-F0-9]/g, '');
        const marker = document.createElementNS(svgNS, "marker");
        marker.setAttribute("id", id);
        marker.setAttribute("markerWidth", "10");
        marker.setAttribute("markerHeight", "10");
        marker.setAttribute("refX", "9");
        marker.setAttribute("refY", "3");
        marker.setAttribute("orient", "auto");
        const arrowPath = document.createElementNS(svgNS, "path");
        arrowPath.setAttribute("d", "M0,0 L0,6 L9,3 z");
        arrowPath.setAttribute("fill", key);
        marker.appendChild(arrowPath);
        defs.appendChild(marker);
        arrowMarkers.set(key, id);
        return id;
    }
    // заранее — по одной стрелке на дорожку
    laneColorByName.forEach((c) => arrowMarkerId(c));
    arrowMarkerId(primaryColor);
    svg.appendChild(defs);

    // Пулы
    (pools || []).forEach((pool) => {
        if (!pool || !pool.name) return;
        const rect = document.createElementNS(svgNS, "rect");
        rect.setAttribute("x", pool.x != null ? pool.x : 8);
        rect.setAttribute("y", pool.y);
        rect.setAttribute("width", width - 16);
        rect.setAttribute("height", pool.height);
        rect.setAttribute("fill", "none");
        rect.setAttribute("stroke", primaryColor);
        rect.setAttribute("stroke-width", "2");
        rect.setAttribute("stroke-opacity", "0.55");
        rect.setAttribute("rx", "10");
        poolGroup.appendChild(rect);

        const labelBg = document.createElementNS(svgNS, "rect");
        labelBg.setAttribute("x", (pool.x != null ? pool.x : 8) + 10);
        labelBg.setAttribute("y", pool.y + 4);
        labelBg.setAttribute("width", Math.min(220, pool.name.length * 8 + 24));
        labelBg.setAttribute("height", 22);
        labelBg.setAttribute("rx", "4");
        labelBg.setAttribute("fill", softLaneHeader(primaryColor));
        poolGroup.appendChild(labelBg);

        const text = document.createElementNS(svgNS, "text");
        text.setAttribute("x", (pool.x != null ? pool.x : 8) + 18);
        text.setAttribute("y", pool.y + 19);
        text.setAttribute("fill", textColor);
        text.setAttribute("font-weight", "700");
        text.setAttribute("font-size", "12px");
        text.textContent = pool.name;
        poolGroup.appendChild(text);
    });

    lanes.forEach(({ lane, y, height }) => {
        const laneColor = laneColorByName.get(lane.name) || primaryColor;
        const rect = document.createElementNS(svgNS, "rect");
        rect.setAttribute("x", 20);
        rect.setAttribute("y", y);
        rect.setAttribute("width", width - 40);
        rect.setAttribute("height", height);
        rect.setAttribute("fill", softLaneFill(laneColor));
        rect.setAttribute("stroke", laneColor);
        rect.setAttribute("stroke-width", "1.5");
        rect.setAttribute("stroke-opacity", "0.45");
        rect.setAttribute("rx", "8");
        laneGroup.appendChild(rect);

        // Шапка дорожки — чуть насыщеннее фона (согласовано с titleBand в layout)
        const headerH = Math.min(32, height);
        const header = document.createElementNS(svgNS, "rect");
        header.setAttribute("x", 20);
        header.setAttribute("y", y);
        header.setAttribute("width", width - 40);
        header.setAttribute("height", headerH);
        header.setAttribute("fill", softLaneHeader(laneColor));
        header.setAttribute("rx", "8");
        laneGroup.appendChild(header);
        // Срезать скругление снизу шапки
        const headerClip = document.createElementNS(svgNS, "rect");
        headerClip.setAttribute("x", 20);
        headerClip.setAttribute("y", y + headerH - 8);
        headerClip.setAttribute("width", width - 40);
        headerClip.setAttribute("height", 8);
        headerClip.setAttribute("fill", softLaneHeader(laneColor));
        laneGroup.appendChild(headerClip);

        const strip = document.createElementNS(svgNS, "rect");
        strip.setAttribute("x", 20);
        strip.setAttribute("y", y);
        strip.setAttribute("width", 8);
        strip.setAttribute("height", height);
        strip.setAttribute("fill", laneColor);
        strip.setAttribute("opacity", "0.85");
        strip.setAttribute("rx", "3");
        laneGroup.appendChild(strip);

        const text = document.createElementNS(svgNS, "text");
        text.setAttribute("x", 38);
        text.setAttribute("y", y + 19);
        text.setAttribute("fill", textColor);
        text.setAttribute("font-weight", "700");
        text.setAttribute("font-size", "13px");
        text.textContent = lane.name;
        laneGroup.appendChild(text);
    });

    flows.forEach(flow => {
        const flowColor = colorForLane(flow.fromLane);
        const path = document.createElementNS(svgNS, "polyline");
        let points;
        if (flow.route === 'above' && flow.arcY != null) {
            points = `${flow.fromX},${flow.fromY} ${flow.fromX},${flow.arcY} ${flow.toX},${flow.arcY} ${flow.toX},${flow.toY}`;
        } else if (flow.route === 'around' && flow.busX != null) {
            const yL = flow.yLeave != null ? flow.yLeave : (flow.fromY + flow.toY) / 2;
            const yE = flow.yEnter != null ? flow.yEnter : yL;
            points = `${flow.fromX},${flow.fromY} ${flow.fromX},${yL} ${flow.busX},${yL} ${flow.busX},${yE} ${flow.toX},${yE} ${flow.toX},${flow.toY}`;
        } else if (flow.route === 'ortho' && flow.midX != null) {
            points = `${flow.fromX},${flow.fromY} ${flow.midX},${flow.fromY} ${flow.midX},${flow.toY} ${flow.toX},${flow.toY}`;
        } else if (flow.route === 'cross' || flow.route === 'message') {
            const midY = flow.midY != null ? flow.midY : (flow.fromY + flow.toY) / 2;
            points = `${flow.fromX},${flow.fromY} ${flow.fromX},${midY} ${flow.toX},${midY} ${flow.toX},${flow.toY}`;
        } else {
            // forward и прочие — прямая (не ломать из‑за type===message)
            points = `${flow.fromX},${flow.fromY} ${flow.toX},${flow.toY}`;
        }
        path.setAttribute("points", points);
        path.setAttribute("fill", "none");
        path.setAttribute("stroke", flowColor);
        path.setAttribute("stroke-width", "2");
        path.setAttribute("stroke-linecap", "round");
        path.setAttribute("stroke-linejoin", "round");
        path.setAttribute("opacity", "0.92");
        if (flow.type === 'conditional') {
            path.setAttribute("stroke-dasharray", "6,4");
        } else if (flow.type === 'message') {
            path.setAttribute("stroke-dasharray", "2,2");
        } else if (flow.type === 'association') {
            path.setAttribute("stroke-dasharray", "1,3");
        }
        path.setAttribute("marker-end", `url(#${arrowMarkerId(flowColor)})`);
        if (typeof setDiagramSourceLine === 'function') {
            setDiagramSourceLine(path, flow.line || flow.sourceLine);
        }
        flowGroup.appendChild(path);

        // Маркер default (=>) — диагональ на ПЕРВОМ сегменте реальной ломаной
        // (раньше считали по прямой from→to и черта «висела» рядом со шлюзом)
        if (flow.type === 'default') {
            let segX1 = flow.fromX, segY1 = flow.fromY, segX2 = flow.toX, segY2 = flow.toY;
            if (flow.route === 'above' && flow.arcY != null) {
                segX2 = flow.fromX;
                segY2 = flow.arcY;
            } else if (flow.route === 'around' && flow.yLeave != null) {
                segX2 = flow.fromX;
                segY2 = flow.yLeave;
            } else if (flow.fromLane !== flow.toLane) {
                segX2 = flow.fromX;
                segY2 = flow.midY != null ? flow.midY : (flow.fromY + flow.toY) / 2;
            }
            const dx = segX2 - segX1;
            const dy = segY2 - segY1;
            const len = Math.hypot(dx, dy) || 1;
            const ux = dx / len;
            const uy = dy / len;
            const px = -uy;
            const py = ux;
            const along = Math.min(16, len * 0.35);
            const mx = segX1 + ux * along;
            const my = segY1 + uy * along;
            const slash = document.createElementNS(svgNS, "line");
            slash.setAttribute("x1", mx - px * 6);
            slash.setAttribute("y1", my - py * 6);
            slash.setAttribute("x2", mx + px * 6);
            slash.setAttribute("y2", my + py * 6);
            slash.setAttribute("stroke", flowColor);
            slash.setAttribute("stroke-width", "2.5");
            slash.setAttribute("stroke-linecap", "round");
            flowGroup.appendChild(slash);
        }
        if (flow.label) {
            const text = document.createElementNS(svgNS, "text");
            const lx = flow.labelX != null ? flow.labelX : (flow.fromX + flow.toX) / 2;
            const ly = flow.labelY != null ? flow.labelY : (flow.fromY + flow.toY) / 2 - 8;
            text.setAttribute("x", lx);
            text.setAttribute("y", ly);
            text.setAttribute("text-anchor", "middle");
            text.setAttribute("fill", textColor);
            text.setAttribute("font-size", "11px");
            text.setAttribute("font-weight", "600");
            // Без прямоугольной заливки — только лёгкий контур, чтобы читалось поверх линии
            text.setAttribute("paint-order", "stroke fill");
            text.setAttribute("stroke", typeof readCssColor === 'function'
                ? readCssColor('--diagram-bg', isDark ? '#161618' : '#ffffff')
                : (isDark ? '#161618' : '#ffffff'));
            text.setAttribute("stroke-width", "3.5");
            text.setAttribute("stroke-linejoin", "round");
            text.textContent = flow.label;
            if (typeof setDiagramSourceLine === 'function') {
                setDiagramSourceLine(text, flow.line || flow.sourceLine);
            }
            flowGroup.appendChild(text);
        }
    });

    function drawTaskIcon(x, y, taskType) {
        let iconChar = '';
        switch (taskType) {
            case 'сервисная': iconChar = '⚙️'; break;
            case 'ручная': iconChar = '✋'; break;
            case 'сценарий': iconChar = '📜'; break;
            case 'отправка сообщения': iconChar = '✉️'; break;
            case 'получение сообщения': iconChar = '📥'; break;
            case 'бизнес-правило': iconChar = '📊'; break;
            case 'таймер': iconChar = '⏱️'; break;
            case 'подпроцесс': iconChar = '📦'; break;
            default: return;
        }
        const icon = document.createElementNS(svgNS, "text");
        icon.setAttribute("x", x + 8);
        icon.setAttribute("y", y + 16);
        icon.setAttribute("fill", elementStroke);
        icon.setAttribute("font-size", "14px");
        icon.textContent = iconChar;
        elementGroup.appendChild(icon);
    }

    function drawAttachedNote(el) {
        if (!el.note) return;
        const padX = 12;
        const fontSize = 10;
        const lineH = 13;
        const maxW = Math.max(110, Math.min(168, (el.width || 130) + 24));
        const lines = (typeof wrapTextLines === 'function')
            ? wrapTextLines(el.note, maxW - padX, fontSize)
            : [el.note];
        const noteW = maxW;
        const noteH = 8 + lines.length * lineH;
        // Под фигурой — не смещаем задачу и не ломаем горизонтальные стрелки
        const nx = el.x + (el.width || 0) / 2 - noteW / 2;
        const ny = el.y + (el.height || 0) + 10;

        const link = document.createElementNS(svgNS, "line");
        link.setAttribute("x1", el.x + (el.width || 0) / 2);
        link.setAttribute("y1", el.y + (el.height || 0));
        link.setAttribute("x2", nx + noteW / 2);
        link.setAttribute("y2", ny);
        link.setAttribute("stroke", isDark ? '#a8a29e' : '#ca8a04');
        link.setAttribute("stroke-width", "1.1");
        link.setAttribute("stroke-dasharray", "3,4");
        elementGroup.appendChild(link);

        const rect = document.createElementNS(svgNS, "rect");
        rect.setAttribute("x", nx);
        rect.setAttribute("y", ny);
        rect.setAttribute("width", noteW);
        rect.setAttribute("height", noteH);
        rect.setAttribute("fill", isDark ? '#422006' : '#fef9c3');
        rect.setAttribute("stroke", isDark ? '#a8a29e' : '#ca8a04');
        rect.setAttribute("stroke-width", "1");
        rect.setAttribute("rx", "4");
        elementGroup.appendChild(rect);

        const text = document.createElementNS(svgNS, "text");
        text.setAttribute("x", nx + 6);
        text.setAttribute("y", ny + fontSize + 2);
        text.setAttribute("fill", isDark ? '#fef3c7' : '#1f2937');
        text.setAttribute("font-size", fontSize + "px");
        lines.forEach((line, idx) => {
            const tspan = document.createElementNS(svgNS, "tspan");
            tspan.setAttribute("x", nx + 6);
            tspan.setAttribute("dy", idx === 0 ? "0" : String(lineH));
            tspan.textContent = line;
            text.appendChild(tspan);
        });
        elementGroup.appendChild(text);
    }

    function drawEventSymbol(x, y, eventType, eventSubType) {
        const cx = x + eventRadius;
        const cy = y + eventRadius;
        if (eventSubType === 'таймер') {
            const clock = document.createElementNS(svgNS, "circle");
            clock.setAttribute("cx", cx);
            clock.setAttribute("cy", cy);
            clock.setAttribute("r", 8);
            clock.setAttribute("fill", "none");
            clock.setAttribute("stroke", elementStroke);
            clock.setAttribute("stroke-width", "1.5");
            elementGroup.appendChild(clock);
            const hand = document.createElementNS(svgNS, "line");
            hand.setAttribute("x1", cx);
            hand.setAttribute("y1", cy);
            hand.setAttribute("x2", cx);
            hand.setAttribute("y2", cy - 6);
            hand.setAttribute("stroke", elementStroke);
            hand.setAttribute("stroke-width", "1.5");
            elementGroup.appendChild(hand);
        } else if (eventSubType === 'сообщение') {
            const envelope = document.createElementNS(svgNS, "path");
            envelope.setAttribute("d", `M${cx-6},${cy-3} L${cx},${cy+1} L${cx+6},${cy-3} M${cx-6},${cy-3} L${cx-6},${cy+4} L${cx+6},${cy+4} L${cx+6},${cy-3}`);
            envelope.setAttribute("fill", "none");
            envelope.setAttribute("stroke", elementStroke);
            envelope.setAttribute("stroke-width", "1.5");
            elementGroup.appendChild(envelope);
        } else if (eventSubType === 'ошибка') {
            const lightning = document.createElementNS(svgNS, "text");
            lightning.setAttribute("x", cx - 5);
            lightning.setAttribute("y", cy + 6);
            lightning.setAttribute("fill", elementStroke);
            lightning.setAttribute("font-size", "16px");
            lightning.setAttribute("font-weight", "bold");
            lightning.textContent = '⚡';
            elementGroup.appendChild(lightning);
        } else if (eventSubType === 'эскалация') {
            const arrow = document.createElementNS(svgNS, "text");
            arrow.setAttribute("x", cx - 4);
            arrow.setAttribute("y", cy + 6);
            arrow.setAttribute("fill", elementStroke);
            arrow.setAttribute("font-size", "14px");
            arrow.textContent = '↑';
            elementGroup.appendChild(arrow);
        } else if (eventSubType === 'отмена') {
            const cross = document.createElementNS(svgNS, "text");
            cross.setAttribute("x", cx - 4);
            cross.setAttribute("y", cy + 6);
            cross.setAttribute("fill", elementStroke);
            cross.setAttribute("font-weight", "bold");
            cross.setAttribute("font-size", "14px");
            cross.textContent = '×';
            elementGroup.appendChild(cross);
        } else if (eventSubType === 'компенсация') {
            const rewind = document.createElementNS(svgNS, "text");
            rewind.setAttribute("x", cx - 6);
            rewind.setAttribute("y", cy + 6);
            rewind.setAttribute("fill", elementStroke);
            rewind.setAttribute("font-size", "14px");
            rewind.textContent = '⟲';
            elementGroup.appendChild(rewind);
        } else if (eventSubType === 'сигнал') {
            const triangle = document.createElementNS(svgNS, "polygon");
            triangle.setAttribute("points", `${cx},${cy-6} ${cx-5},${cy+4} ${cx+5},${cy+4}`);
            triangle.setAttribute("fill", "none");
            triangle.setAttribute("stroke", elementStroke);
            triangle.setAttribute("stroke-width", "1.5");
            elementGroup.appendChild(triangle);
        } else if (eventSubType === 'множественный') {
            const pentagon = document.createElementNS(svgNS, "polygon");
            const points = [];
            for (let i = 0; i < 5; i++) {
                const angle = (i * 72 - 90) * Math.PI / 180;
                points.push(`${cx + 6 * Math.cos(angle)},${cy + 6 * Math.sin(angle)}`);
            }
            pentagon.setAttribute("points", points.join(' '));
            pentagon.setAttribute("fill", "none");
            pentagon.setAttribute("stroke", elementStroke);
            pentagon.setAttribute("stroke-width", "1.5");
            elementGroup.appendChild(pentagon);
        }
    }

    elements.forEach(el => {
        const x = el.x;
        const y = el.y;
        const w = el.width;
        const h = el.height;
        elementStroke = (el.lane && laneColorByName.get(el.lane)) || primaryColor;

        if (el.type === 'task') {
            const rect = document.createElementNS(svgNS, "rect");
            rect.setAttribute("x", x);
            rect.setAttribute("y", y);
            rect.setAttribute("width", w);
            rect.setAttribute("height", h);
            rect.setAttribute("fill", elementFill);
            rect.setAttribute("stroke", elementStroke);
            rect.setAttribute("stroke-width", (el.isSubprocess || el.taskType === 'подпроцесс') ? "2.5" : "2");
            rect.setAttribute("rx", "6");
            if (typeof setDiagramSourceLine === 'function') {
                setDiagramSourceLine(rect, el.sourceLine || el.line);
            }
            elementGroup.appendChild(rect);

            if (el.isSubprocess || el.taskType === 'подпроцесс') {
                // толстая рамка + маркер [+]
                const inner = document.createElementNS(svgNS, "rect");
                inner.setAttribute("x", x + 4);
                inner.setAttribute("y", y + 4);
                inner.setAttribute("width", w - 8);
                inner.setAttribute("height", h - 8);
                inner.setAttribute("fill", "none");
                inner.setAttribute("stroke", elementStroke);
                inner.setAttribute("stroke-width", "1");
                inner.setAttribute("stroke-opacity", "0.45");
                inner.setAttribute("rx", "4");
                elementGroup.appendChild(inner);
                const plus = document.createElementNS(svgNS, "text");
                plus.setAttribute("x", x + w / 2);
                plus.setAttribute("y", y + h - 8);
                plus.setAttribute("fill", elementStroke);
                plus.setAttribute("text-anchor", "middle");
                plus.setAttribute("font-size", "14px");
                plus.setAttribute("font-weight", "700");
                plus.textContent = '+';
                elementGroup.appendChild(plus);
            }

            // Иконка только если тип != пользовательская и не подпроцесс (у него +)
            if (el.taskType && el.taskType !== 'пользовательская' && el.taskType !== 'подпроцесс' && !el.isSubprocess) {
                drawTaskIcon(x, y, el.taskType);
            }

            const hasMarker = el.marker === 'цикл' || el.marker === 'параллель' || el.isSubprocess || el.taskType === 'подпроцесс';
            const fontSize = el._nested ? 10 : 12;
            const lineH = el._nested ? 12 : 14;
            const maxTextW = Math.max(40, w - 16);
            let taskLines = (typeof wrapTextLines === 'function')
                ? wrapTextLines(el.name, maxTextW, fontSize)
                : [el.name];
            const maxLines = (el.isSubprocess || el.taskType === 'подпроцесс') ? 1 : (hasMarker ? 3 : 4);
            if (taskLines.length > maxLines) taskLines = taskLines.slice(0, maxLines);
            const blockH = taskLines.length * lineH;
            const textY = (el.isSubprocess || el.taskType === 'подпроцесс')
                ? y + 16
                : y + (h - (hasMarker ? 12 : 0) - blockH) / 2 + fontSize * 0.85;

            const text = document.createElementNS(svgNS, "text");
            text.setAttribute("x", x + w / 2);
            text.setAttribute("y", textY);
            text.setAttribute("fill", textColor);
            text.setAttribute("text-anchor", "middle");
            text.setAttribute("font-size", fontSize + "px");
            text.setAttribute("data-label", el.name || '');
            taskLines.forEach((line, idx) => {
                const tspan = document.createElementNS(svgNS, "tspan");
                tspan.setAttribute("x", x + w / 2);
                tspan.setAttribute("dy", idx === 0 ? "0" : String(lineH));
                tspan.textContent = line;
                text.appendChild(tspan);
            });
            elementGroup.appendChild(text);

            // Маркер цикла / параллельного экземпляра
            if (el.marker === 'цикл' || el.marker === 'параллель') {
                const mx = x + w / 2;
                const my = y + h - 10;
                if (el.marker === 'цикл') {
                    const loop = document.createElementNS(svgNS, "text");
                    loop.setAttribute("x", mx);
                    loop.setAttribute("y", my + 4);
                    loop.setAttribute("fill", elementStroke);
                    loop.setAttribute("text-anchor", "middle");
                    loop.setAttribute("font-size", "12px");
                    loop.textContent = '↺';
                    elementGroup.appendChild(loop);
                } else {
                    // три вертикальные черты — multi-instance
                    for (let i = -1; i <= 1; i++) {
                        const tick = document.createElementNS(svgNS, "line");
                        tick.setAttribute("x1", mx + i * 4);
                        tick.setAttribute("y1", my - 4);
                        tick.setAttribute("x2", mx + i * 4);
                        tick.setAttribute("y2", my + 4);
                        tick.setAttribute("stroke", elementStroke);
                        tick.setAttribute("stroke-width", "1.5");
                        elementGroup.appendChild(tick);
                    }
                }
            }

            if (el.note) drawAttachedNote(el);
        } else if (el.type === 'event') {
            const circle = document.createElementNS(svgNS, "circle");
            circle.setAttribute("cx", x + eventRadius);
            circle.setAttribute("cy", y + eventRadius);
            circle.setAttribute("r", eventRadius);
            circle.setAttribute("fill", elementFill);
            circle.setAttribute("stroke", elementStroke);
            circle.setAttribute("stroke-width", "2");
            if (typeof setDiagramSourceLine === 'function') {
                setDiagramSourceLine(circle, el.sourceLine || el.line);
            }
            elementGroup.appendChild(circle);

            if (el.boundary) {
                const outer = document.createElementNS(svgNS, "circle");
                outer.setAttribute("cx", x + eventRadius);
                outer.setAttribute("cy", y + eventRadius);
                outer.setAttribute("r", eventRadius + 3);
                outer.setAttribute("fill", "none");
                outer.setAttribute("stroke", elementStroke);
                outer.setAttribute("stroke-width", "1.5");
                outer.setAttribute("stroke-dasharray", "3,2");
                elementGroup.appendChild(outer);
            }

            if (el.eventType === 'начало') {
                drawEventSymbol(x, y, el.eventType, el.eventSubType);
            } else if (el.eventType === 'промежуточное' || el.boundary) {
                const inner = document.createElementNS(svgNS, "circle");
                inner.setAttribute("cx", x + eventRadius);
                inner.setAttribute("cy", y + eventRadius);
                inner.setAttribute("r", eventRadius / 2);
                inner.setAttribute("fill", "none");
                inner.setAttribute("stroke", elementStroke);
                inner.setAttribute("stroke-width", "1.5");
                elementGroup.appendChild(inner);
                drawEventSymbol(x, y, el.eventType, el.eventSubType);
            } else if (el.eventType === 'завершение') {
                const inner = document.createElementNS(svgNS, "circle");
                inner.setAttribute("cx", x + eventRadius);
                inner.setAttribute("cy", y + eventRadius);
                inner.setAttribute("r", eventRadius / 3);
                inner.setAttribute("fill", elementStroke);
                elementGroup.appendChild(inner);
                drawEventSymbol(x, y, el.eventType, el.eventSubType);
            }

            if (!el.boundary) {
                const text = document.createElementNS(svgNS, "text");
                text.setAttribute("x", x + eventRadius);
                text.setAttribute("y", y + h + 16);
                text.setAttribute("fill", textColor);
                text.setAttribute("text-anchor", "middle");
                text.setAttribute("font-size", "11px");
                text.textContent = el.name;
                text.setAttribute("data-label", el.name || '');
                elementGroup.appendChild(text);
            }
            if (el.note) drawAttachedNote(el);
        } else if (el.type === 'data' || el.type === 'datastore') {
            if (el.type === 'data') {
                // документ со «загнутым» углом
                const fold = 12;
                const d = `M${x},${y} L${x + w - fold},${y} L${x + w},${y + fold} L${x + w},${y + h} L${x},${y + h} Z`;
                const path = document.createElementNS(svgNS, "path");
                path.setAttribute("d", d);
                path.setAttribute("fill", elementFill);
                path.setAttribute("stroke", elementStroke);
                path.setAttribute("stroke-width", "2");
                if (typeof setDiagramSourceLine === 'function') {
                    setDiagramSourceLine(path, el.sourceLine || el.line);
                }
                elementGroup.appendChild(path);
                const foldLine = document.createElementNS(svgNS, "polyline");
                foldLine.setAttribute("points", `${x + w - fold},${y} ${x + w - fold},${y + fold} ${x + w},${y + fold}`);
                foldLine.setAttribute("fill", "none");
                foldLine.setAttribute("stroke", elementStroke);
                foldLine.setAttribute("stroke-width", "1.5");
                elementGroup.appendChild(foldLine);
            } else {
                // цилиндр — хранилище
                const ry = 10;
                const body = document.createElementNS(svgNS, "rect");
                body.setAttribute("x", x);
                body.setAttribute("y", y + ry);
                body.setAttribute("width", w);
                body.setAttribute("height", h - ry * 2);
                body.setAttribute("fill", elementFill);
                body.setAttribute("stroke", elementStroke);
                body.setAttribute("stroke-width", "2");
                if (typeof setDiagramSourceLine === 'function') {
                    setDiagramSourceLine(body, el.sourceLine || el.line);
                }
                elementGroup.appendChild(body);
                const top = document.createElementNS(svgNS, "ellipse");
                top.setAttribute("cx", x + w / 2);
                top.setAttribute("cy", y + ry);
                top.setAttribute("rx", w / 2);
                top.setAttribute("ry", ry);
                top.setAttribute("fill", elementFill);
                top.setAttribute("stroke", elementStroke);
                top.setAttribute("stroke-width", "2");
                elementGroup.appendChild(top);
                const bot = document.createElementNS(svgNS, "ellipse");
                bot.setAttribute("cx", x + w / 2);
                bot.setAttribute("cy", y + h - ry);
                bot.setAttribute("rx", w / 2);
                bot.setAttribute("ry", ry);
                bot.setAttribute("fill", elementFill);
                bot.setAttribute("stroke", elementStroke);
                bot.setAttribute("stroke-width", "2");
                elementGroup.appendChild(bot);
            }
            const text = document.createElementNS(svgNS, "text");
            text.setAttribute("x", x + w / 2);
            text.setAttribute("y", y + h + 14);
            text.setAttribute("fill", textColor);
            text.setAttribute("text-anchor", "middle");
            text.setAttribute("font-size", "11px");
            text.textContent = el.name;
            text.setAttribute("data-label", el.name || '');
            elementGroup.appendChild(text);
            if (el.note) drawAttachedNote(el);
        } else if (el.type === 'gateway') {
            const diamond = document.createElementNS(svgNS, "polygon");
            const cx = x + w / 2;
            const cy = y + h / 2;
            const points = `${cx},${y} ${x + w},${cy} ${cx},${y + h} ${x},${cy}`;
            diamond.setAttribute("points", points);
            diamond.setAttribute("fill", elementFill);
            diamond.setAttribute("stroke", elementStroke);
            diamond.setAttribute("stroke-width", "2");
            if (typeof setDiagramSourceLine === 'function') {
                setDiagramSourceLine(diamond, el.sourceLine || el.line);
            }
            elementGroup.appendChild(diamond);

            if (el.gatewayType === 'исключающий') {
                const xMark = document.createElementNS(svgNS, "text");
                xMark.setAttribute("x", cx);
                xMark.setAttribute("y", cy + 5);
                xMark.setAttribute("fill", elementStroke);
                xMark.setAttribute("text-anchor", "middle");
                xMark.setAttribute("font-weight", "bold");
                xMark.setAttribute("font-size", "16px");
                xMark.textContent = '×';
                elementGroup.appendChild(xMark);
            } else if (el.gatewayType === 'параллельный') {
                const plus = document.createElementNS(svgNS, "text");
                plus.setAttribute("x", cx);
                plus.setAttribute("y", cy + 5);
                plus.setAttribute("fill", elementStroke);
                plus.setAttribute("text-anchor", "middle");
                plus.setAttribute("font-weight", "bold");
                plus.setAttribute("font-size", "16px");
                plus.textContent = '+';
                elementGroup.appendChild(plus);
            } else if (el.gatewayType === 'включающий') {
                const circle = document.createElementNS(svgNS, "circle");
                circle.setAttribute("cx", cx);
                circle.setAttribute("cy", cy);
                circle.setAttribute("r", 7);
                circle.setAttribute("fill", "none");
                circle.setAttribute("stroke", elementStroke);
                circle.setAttribute("stroke-width", "1.5");
                elementGroup.appendChild(circle);
            } else if (el.gatewayType === 'комплексный') {
                const star = document.createElementNS(svgNS, "text");
                star.setAttribute("x", cx - 6);
                star.setAttribute("y", cy + 6);
                star.setAttribute("fill", elementStroke);
                star.setAttribute("font-weight", "bold");
                star.setAttribute("font-size", "14px");
                star.textContent = '⍟';
                elementGroup.appendChild(star);
            }

            const text = document.createElementNS(svgNS, "text");
            // Подпись НАД ромбом — не перекрывает выход вниз и вправо
            text.setAttribute("x", cx);
            text.setAttribute("fill", textColor);
            text.setAttribute("text-anchor", "middle");
            text.setAttribute("font-size", "11px");
            const gwLines = (typeof wrapTextLines === 'function')
                ? wrapTextLines(el.name, Math.max(90, w + 48), 11)
                : [el.name];
            const lines = gwLines.slice(0, 2);
            text.setAttribute("y", y - 6 - Math.max(0, lines.length - 1) * 12);
            text.setAttribute("data-label", el.name || '');
            lines.forEach((line, idx) => {
                const tspan = document.createElementNS(svgNS, "tspan");
                tspan.setAttribute("x", cx);
                tspan.setAttribute("dy", idx === 0 ? "0" : "12");
                tspan.textContent = line;
                text.appendChild(tspan);
            });
            elementGroup.appendChild(text);
            if (el.note) drawAttachedNote(el);
        } else if (el.type === 'annotation') {
            const rect = document.createElementNS(svgNS, "rect");
            rect.setAttribute("x", x);
            rect.setAttribute("y", y);
            rect.setAttribute("width", w);
            rect.setAttribute("height", h);
            rect.setAttribute("fill", isDark ? '#422006' : '#fef9c3');
            rect.setAttribute("stroke", isDark ? '#a8a29e' : '#eab308');
            rect.setAttribute("stroke-width", "1");
            rect.setAttribute("rx", "4");
            if (typeof setDiagramSourceLine === 'function') {
                setDiagramSourceLine(rect, el.sourceLine || el.line);
            }
            elementGroup.appendChild(rect);

            const fontSize = 11;
            const lineHeightPx = fontSize * 1.3;
            const lines = el._wrapLines || wrapTextLines(el.name, w - 16, fontSize);
            const blockH = lines.length * lineHeightPx;
            const textX = x + 8;
            const textY = y + (h - blockH) / 2 + fontSize;

            const text = document.createElementNS(svgNS, "text");
            text.setAttribute("x", textX);
            text.setAttribute("y", textY);
            text.setAttribute("fill", isDark ? '#fef3c7' : '#1f2937');
            text.setAttribute("font-size", fontSize + "px");
            lines.forEach((line, idx) => {
                const tspan = document.createElementNS(svgNS, "tspan");
                tspan.setAttribute("x", textX);
                tspan.setAttribute("dy", idx === 0 ? "0" : String(lineHeightPx));
                tspan.textContent = line;
                text.appendChild(tspan);
            });
            elementGroup.appendChild(text);
        }
    });

    return { svg, width, height, svgString: new XMLSerializer().serializeToString(svg) };
}
;

// ===== 58-svg-renderer-secret.js =====
/**
 * Рендерер Kanban-доски (assignee внизу справа, dueDate внизу слева,
 * контрастные даты и участники). Добавлено отображение описания с переносом длинных строк.
 */
function generateSecretSVG(layoutData, themeColors) {
    const {
        columns, tasks, width, height, title,
        tagHeight, tagHorizontalGap, footerHeight
    } = layoutData;

    const svgNS = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(svgNS, "svg");
    svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
    svg.setAttribute("width", width);
    svg.setAttribute("height", height);
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", "Kanban-доска");
    svg.style.fontFamily = (typeof getUiFontFamily === "function" ? getUiFontFamily() : "system-ui, -apple-system, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif");
    svg.style.fontSize = "14px";

    const isDark = document.body.classList.contains('dark');
    const theme = themeColors || [];
    const primaryColor = theme.length > 0 ? theme[0] : (isDark ? '#60a5fa' : '#3b82f6');
    const textColor = isDark ? '#e0e0e0' : '#1f2937';
    const secondaryColor = isDark ? '#cbd5e1' : '#374151';
    const descriptionColor = isDark ? '#94a3b8' : '#6b7280';
    const columnFill = typeof readCssColor === 'function'
        ? readCssColor('--diagram-bg', isDark ? '#161618' : '#f8fafc')
        : (isDark ? '#161618' : '#f8fafc');
    const columnStroke = typeof readCssColor === 'function'
        ? readCssColor('--border', isDark ? '#3a3a3c' : '#cbd5e1')
        : (isDark ? '#475569' : '#cbd5e1');
    const taskFill = typeof readCssColor === 'function'
        ? readCssColor('--panel-bg', isDark ? '#1c1c1e' : '#ffffff')
        : (isDark ? '#334155' : '#ffffff');
    const taskStroke = columnStroke;

    const bgGroup = document.createElementNS(svgNS, "g");
    const columnGroup = document.createElementNS(svgNS, "g");
    const taskGroup = document.createElementNS(svgNS, "g");
    svg.appendChild(bgGroup);
    svg.appendChild(columnGroup);
    svg.appendChild(taskGroup);

    const columnColors = {};
    columns.forEach((col, i) => {
        columnColors[col.name] = theme.length > 0 ? theme[i % theme.length] : primaryColor;
    });

    if (title) {
        const titleEl = document.createElementNS(svgNS, "text");
        titleEl.setAttribute("x", width / 2);
        titleEl.setAttribute("y", 36);
        titleEl.setAttribute("fill", textColor);
        titleEl.setAttribute("text-anchor", "middle");
        titleEl.setAttribute("font-weight", "700");
        titleEl.setAttribute("font-size", "16px");
        titleEl.textContent = title;
        svg.appendChild(titleEl);
    }

    // Колонки
    columns.forEach(col => {
        const colColor = columnColors[col.name];
        const rect = document.createElementNS(svgNS, "rect");
        rect.setAttribute("x", col.x);
        rect.setAttribute("y", col.y);
        rect.setAttribute("width", col.width);
        rect.setAttribute("height", col.height);
        rect.setAttribute("fill", columnFill);
        rect.setAttribute("stroke", columnStroke);
        rect.setAttribute("stroke-width", "2");
        rect.setAttribute("rx", "10");
        columnGroup.appendChild(rect);

        const header = document.createElementNS(svgNS, "rect");
        header.setAttribute("x", col.x);
        header.setAttribute("y", col.y);
        header.setAttribute("width", col.width);
        header.setAttribute("height", 36);
        header.setAttribute("fill", colColor);
        header.setAttribute("rx", "10");
        columnGroup.appendChild(header);

        const title = document.createElementNS(svgNS, "text");
        title.setAttribute("x", col.x + 12);
        title.setAttribute("y", col.y + 24);
        title.setAttribute("fill", getContrastColor(colColor));
        title.setAttribute("text-anchor", "start");
        title.setAttribute("font-weight", "bold");
        title.setAttribute("font-size", "14px");
        title.textContent = col.name;
        columnGroup.appendChild(title);

        if (col.wipLimit != null) {
            const wip = document.createElementNS(svgNS, "text");
            wip.setAttribute("x", col.x + col.width - 12);
            wip.setAttribute("y", col.y + 24);
            wip.setAttribute("fill", col.wipExceeded ? '#fecaca' : getContrastColor(colColor));
            wip.setAttribute("text-anchor", "end");
            wip.setAttribute("font-weight", "700");
            wip.setAttribute("font-size", "12px");
            wip.textContent = `${col.wipCount || 0}/${col.wipLimit}`;
            columnGroup.appendChild(wip);
            if (col.wipExceeded) {
                rect.setAttribute("stroke", "#ef4444");
                rect.setAttribute("stroke-width", "2.5");
                rect.setAttribute("fill", isDark ? '#3f1d1d' : '#fef2f2');
                // Полоска сверху колонки — лимит виден без чтения цифр
                const warn = document.createElementNS(svgNS, "rect");
                warn.setAttribute("x", col.x);
                warn.setAttribute("y", col.y + 36);
                warn.setAttribute("width", col.width);
                warn.setAttribute("height", 4);
                warn.setAttribute("fill", "#ef4444");
                columnGroup.appendChild(warn);
            }
        }
    });

    // Задачи
    tasks.forEach(task => {
        const rect = document.createElementNS(svgNS, "rect");
        rect.setAttribute("x", task.x);
        rect.setAttribute("y", task.y);
        rect.setAttribute("width", task.width);
        rect.setAttribute("height", task.height);
        rect.setAttribute("fill", taskFill);
        rect.setAttribute("stroke", taskStroke);
        rect.setAttribute("stroke-width", "1.5");
        rect.setAttribute("rx", "6");
        if (task.href) {
            rect.setAttribute("data-pdf-href", task.href);
        }
        if (typeof setDiagramSourceLine === 'function') {
            setDiagramSourceLine(rect, task.sourceLine || task._line || task.line);
        }
        taskGroup.appendChild(rect);

        // Название задачи — с переносом по ширине карточки
        const padding = task.taskPadding || 12;
        const titleFontSize = task.titleFontSize || 13;
        const titleLineHeight = task.titleLineHeight || 18;
        const titleLines = task.titleLines && task.titleLines.length
            ? task.titleLines
            : [task.name || ''];
        titleLines.forEach((line, i) => {
            const titleText = document.createElementNS(svgNS, "text");
            titleText.setAttribute("x", task.x + padding);
            titleText.setAttribute("y", task.y + 22 + i * titleLineHeight);
            titleText.setAttribute("fill", textColor);
            titleText.setAttribute("font-weight", "600");
            titleText.setAttribute("font-size", `${titleFontSize}px`);
            titleText.setAttribute("data-label", task.name || line);
            if (task.cardId) titleText.setAttribute("data-node-id", String(task.cardId));
            if (task.href) {
                titleText.setAttribute("data-pdf-href", task.href);
                titleText.setAttribute("text-decoration", "underline");
                titleText.style.textDecoration = "underline";
            }
            titleText.textContent = line;
            taskGroup.appendChild(titleText);
        });

        let infoY = task.y + 22 + titleLines.length * titleLineHeight + 10;

        // Приоритет (ширина согласована с layout → titleMaxWidth)
        if (task.priority !== 'обычная') {
            const priorityColors = {
                срочно: '#ef4444',
                важно: '#f59e0b',
                средне: '#14b8a6',
                'не срочно': '#94a3b8'
            };
            const prioLabel = task.priority;
            const badgeW = task.prioBadgeW
                || Math.max(50, String(prioLabel).length * 6.5 + 14);
            const badgeRightPad = 10;
            const badge = document.createElementNS(svgNS, "rect");
            badge.setAttribute("x", task.x + task.width - badgeW - badgeRightPad);
            badge.setAttribute("y", task.y + 10);
            badge.setAttribute("width", badgeW);
            badge.setAttribute("height", 18);
            badge.setAttribute("fill", priorityColors[task.priority] || '#6b7280');
            badge.setAttribute("rx", "4");
            taskGroup.appendChild(badge);

            const priorityText = document.createElementNS(svgNS, "text");
            priorityText.setAttribute("x", task.x + task.width - badgeW / 2 - badgeRightPad);
            priorityText.setAttribute("y", task.y + 23);
            priorityText.setAttribute("fill", "#ffffff");
            priorityText.setAttribute("text-anchor", "middle");
            priorityText.setAttribute("font-size", "10px");
            priorityText.setAttribute("font-weight", "bold");
            priorityText.textContent = task.priority;
            taskGroup.appendChild(priorityText);
        }

        // Теги
        const maxTagWidth = task.contentWidth || (task.width - 2 * padding);
        if (task.tags && task.tags.length > 0) {
            const tagStartX = task.x + padding;
            let tagX = tagStartX;
            let tagY = infoY;

            task.tags.forEach(tag => {
                const tagColor = tag.color || primaryColor;
                const tagWidth = tag.text.length * 7 + 16;

                if (tagX + tagWidth > tagStartX + maxTagWidth && tagX > tagStartX) {
                    tagX = tagStartX;
                    tagY += tagHeight;
                }

                const tagBadge = document.createElementNS(svgNS, "rect");
                tagBadge.setAttribute("x", tagX);
                tagBadge.setAttribute("y", tagY);
                tagBadge.setAttribute("width", tagWidth);
                tagBadge.setAttribute("height", 16);
                tagBadge.setAttribute("fill", tagColor);
                tagBadge.setAttribute("rx", "4");
                taskGroup.appendChild(tagBadge);

                const tagText = document.createElementNS(svgNS, "text");
                tagText.setAttribute("x", tagX + tagWidth / 2);
                tagText.setAttribute("y", tagY + 12);
                tagText.setAttribute("fill", getContrastColor(tagColor));
                tagText.setAttribute("text-anchor", "middle");
                tagText.setAttribute("font-size", "10px");
                tagText.textContent = tag.text;
                taskGroup.appendChild(tagText);

                tagX += tagWidth + tagHorizontalGap;
            });

            infoY = tagY + tagHeight + 4;
        }

        // Описание с переносом длинных строк и отступами
        if (task.descriptionLines && task.descriptionLines.length > 0) {
            // вычисляем максимальное число символов в строке исходя из доступной ширины и размера шрифта
            const fontSize = task.descriptionFontSize || 12;
            const availableWidth = task.contentWidth || (task.width - 2 * padding);
            // примерно 0.6 * fontSize на символ (для шрифта sans-serif)
            const maxChars = Math.floor(availableWidth / (fontSize * 0.6));
            const descY = infoY + 4;
            let lineIndex = 0;
            task.descriptionLines.forEach(line => {
                let remaining = line;
                while (remaining.length > 0) {
                    let chunk = remaining.substring(0, maxChars);
                    if (remaining.length > maxChars) {
                        const lastSpace = chunk.lastIndexOf(' ');
                        if (lastSpace > 0) {
                            chunk = chunk.substring(0, lastSpace);
                        }
                    }
                    const descText = document.createElementNS(svgNS, "text");
                    descText.setAttribute("x", task.x + padding);
                    descText.setAttribute("y", descY + lineIndex * task.descriptionLineHeight + 12);
                    descText.setAttribute("fill", descriptionColor);
                    descText.setAttribute("font-size", `${fontSize}px`);
                    descText.setAttribute("font-weight", "normal");
                    descText.textContent = chunk;
                    taskGroup.appendChild(descText);
                    lineIndex++;
                    remaining = remaining.substring(chunk.length).trim();
                }
            });
            infoY += lineIndex * task.descriptionLineHeight + 8;
        }

        // Нижняя полоса: dueDate слева, assignee справа (при просрочке — две строки, имя остаётся справа)
        const twoLine = !!(task._footerTwoLine || (task.assignee && task.dueDate && task.overdue));
        const footerY = task.y + task.height - (twoLine ? 10 : 14);
        if (task.dueDate) {
            const dateText = document.createElementNS(svgNS, "text");
            dateText.setAttribute("x", task.x + padding);
            dateText.setAttribute("y", twoLine ? (task.y + task.height - 24) : footerY);
            dateText.setAttribute("text-anchor", "start");
            dateText.setAttribute("fill", task.overdue ? '#ef4444' : secondaryColor);
            dateText.setAttribute("font-size", "11px");
            dateText.setAttribute("font-weight", task.overdue ? "700" : "500");
            const dueLabel = task.overdue ? ('⚠ ' + task.dueDate) : task.dueDate;
            dateText.textContent = dueLabel;
            taskGroup.appendChild(dateText);
        }
        if (task.assignee) {
            if (typeof appendAssigneeAvatar === 'function') {
                const initials = task.initials
                    || (typeof diagramAssigneeInitials === 'function'
                        ? diagramAssigneeInitials(task.assignee)
                        : String(task.assignee).slice(0, 2).toUpperCase());
                appendAssigneeAvatar(svgNS, taskGroup, task.x + task.width - padding - 2, footerY - 2, {
                    initials,
                    assignee: task.assignee,
                    r: 16,
                    title: '@' + task.assignee
                });
            } else {
                const assigneeText = document.createElementNS(svgNS, "text");
                assigneeText.setAttribute("x", task.x + task.width - padding);
                assigneeText.setAttribute("y", footerY);
                assigneeText.setAttribute("text-anchor", "end");
                assigneeText.setAttribute("fill", secondaryColor);
                assigneeText.setAttribute("font-size", "11px");
                assigneeText.setAttribute("font-weight", "500");
                const name = String(task.assignee || '');
                const maxName = twoLine ? 22 : 14;
                assigneeText.textContent = '👤 ' + (name.length > maxName ? name.slice(0, maxName - 1) + '…' : name);
                taskGroup.appendChild(assigneeText);
            }
        }
    });

    return { svg, width, height, svgString: new XMLSerializer().serializeToString(svg) };
}
;

// ===== 59-svg-renderer-wave.js =====
/**
 * Рендерер волнообразной (Sankey) диаграммы.
 * Ленты — залитые Bezier-полосы (не толстый stroke), узлы с подписью сбоку.
 */
function generateWaveSVG(layoutData, themeColors) {
    const { nodes, links, width, height, title } = layoutData;
    const svgNS = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(svgNS, "svg");
    svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
    svg.setAttribute("width", width);
    svg.setAttribute("height", height);
    svg.style.fontFamily = (typeof getUiFontFamily === "function" ? getUiFontFamily() : "system-ui, -apple-system, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif");
    svg.style.fontSize = "13px";

    const isDark = document.body.classList.contains('dark');
    const theme = themeColors || [];
    const defaultColor = isDark ? '#60a5fa' : '#3b82f6';
    const labelColor = isDark ? '#e5e7eb' : '#1f2937';
    const valueColor = isDark ? '#f8fafc' : '#111827';

    const defs = document.createElementNS(svgNS, "defs");
    svg.appendChild(defs);

    if (title) {
        const titleEl = document.createElementNS(svgNS, "text");
        titleEl.setAttribute("x", width / 2);
        titleEl.setAttribute("y", 32);
        titleEl.setAttribute("fill", labelColor);
        titleEl.setAttribute("text-anchor", "middle");
        titleEl.setAttribute("font-weight", "700");
        titleEl.setAttribute("font-size", "16px");
        titleEl.textContent = title;
        svg.appendChild(titleEl);
    }

    const linkGroup = document.createElementNS(svgNS, "g");
    const nodeGroup = document.createElementNS(svgNS, "g");
    const labelGroup = document.createElementNS(svgNS, "g");
    const bandLabels = [];
    const middleLabels = [];
    const haloColor = typeof readCssColor === 'function'
        ? readCssColor('--diagram-bg', isDark ? '#161618' : '#f8fafc')
        : (isDark ? '#161618' : '#f8fafc');
    svg.appendChild(linkGroup);
    svg.appendChild(nodeGroup);
    svg.appendChild(labelGroup);

    const nodeColorMap = new Map();
    nodes.forEach((node, i) => {
        nodeColorMap.set(node.name, theme.length > 0 ? theme[i % theme.length] : defaultColor);
    });

    function softHex(hex, mixWith, t) {
        const parse = (h) => {
            const s = String(h || '').replace('#', '');
            if (s.length !== 6) return [59, 130, 246];
            return [parseInt(s.slice(0, 2), 16), parseInt(s.slice(2, 4), 16), parseInt(s.slice(4, 6), 16)];
        };
        const a = parse(hex);
        const b = parse(mixWith);
        const m = (i) => Math.round(a[i] * (1 - t) + b[i] * t);
        return `#${[m(0), m(1), m(2)].map((n) => n.toString(16).padStart(2, '0')).join('')}`;
    }

    // Ленты: залитый путь из двух кубических кривых (верх + низ)
    links.forEach((link, idx) => {
        const sourceColor = nodeColorMap.get(link.source) || defaultColor;
        const targetColor = nodeColorMap.get(link.target) || defaultColor;
        const x0 = link.x1;
        const x1 = link.x2;
        const y0 = link.y1;
        const y1 = link.y2;
        const t0 = Math.max(2, link.thickness || 10) / 2;
        const t1 = Math.max(2, link.targetThickness != null ? link.targetThickness : link.thickness || 10) / 2;
        const dx = x1 - x0;
        const c1 = x0 + dx * 0.42;
        const c2 = x1 - dx * 0.42;

        const d = [
            `M ${x0} ${y0 - t0}`,
            `C ${c1} ${y0 - t0}, ${c2} ${y1 - t1}, ${x1} ${y1 - t1}`,
            `L ${x1} ${y1 + t1}`,
            `C ${c2} ${y1 + t1}, ${c1} ${y0 + t0}, ${x0} ${y0 + t0}`,
            'Z'
        ].join(' ');

        const gradId = `wave-grad-${idx}`;
        const grad = document.createElementNS(svgNS, "linearGradient");
        grad.setAttribute("id", gradId);
        grad.setAttribute("x1", String(x0));
        grad.setAttribute("y1", "0");
        grad.setAttribute("x2", String(x1));
        grad.setAttribute("y2", "0");
        grad.setAttribute("gradientUnits", "userSpaceOnUse");
        const s1 = document.createElementNS(svgNS, "stop");
        s1.setAttribute("offset", "0%");
        s1.setAttribute("stop-color", softHex(sourceColor, isDark ? '#0f172a' : '#ffffff', 0.08));
        s1.setAttribute("stop-opacity", "0.72");
        const s2 = document.createElementNS(svgNS, "stop");
        s2.setAttribute("offset", "100%");
        s2.setAttribute("stop-color", softHex(targetColor, isDark ? '#0f172a' : '#ffffff', 0.08));
        s2.setAttribute("stop-opacity", "0.72");
        grad.appendChild(s1);
        grad.appendChild(s2);
        defs.appendChild(grad);

        const path = document.createElementNS(svgNS, "path");
        path.setAttribute("d", d);
        path.setAttribute("fill", `url(#${gradId})`);
        path.setAttribute("stroke", "none");
        if (typeof setDiagramSourceLine === 'function') {
            setDiagramSourceLine(path, link.line || link.sourceLine);
        }
        linkGroup.appendChild(path);

        // Значение по центру ленты
        const midX = (x0 + x1) / 2;
        const midY = (y0 + y1) / 2;
        const text = document.createElementNS(svgNS, "text");
        text.setAttribute("x", midX);
        text.setAttribute("y", midY + 4);
        text.setAttribute("fill", valueColor);
        text.setAttribute("text-anchor", "middle");
        text.setAttribute("font-size", "12px");
        text.setAttribute("font-weight", "600");
        text.setAttribute("opacity", "0.85");
        text.textContent = link.value;
        labelGroup.appendChild(text);
        bandLabels.push({ el: text, x: midX, y: midY + 4, w: String(link.value).length * 7.5 + 4 });
    });

    // Узлы + подписи сбоку (не внутри узкой полоски)
    const layerXs = [...new Set(nodes.map((n) => n.x))].sort((a, b) => a - b);
    const firstX = layerXs[0];
    const lastX = layerXs[layerXs.length - 1];

    nodes.forEach(node => {
        const color = nodeColorMap.get(node.name) || defaultColor;
        const rect = document.createElementNS(svgNS, "rect");
        rect.setAttribute("x", node.x);
        rect.setAttribute("y", node.y);
        rect.setAttribute("width", node.width);
        rect.setAttribute("height", node.height);
        rect.setAttribute("fill", color);
        rect.setAttribute("rx", "3");
        if (typeof setDiagramSourceLine === 'function') {
            setDiagramSourceLine(rect, node.sourceLine || node.line);
        }
        nodeGroup.appendChild(rect);

        const onLeft = node.x <= firstX + 1;
        const onRight = node.x >= lastX - 1;
        const text = document.createElementNS(svgNS, "text");
        text.setAttribute("y", node.y + node.height / 2 + 4);
        text.setAttribute("fill", labelColor);
        text.setAttribute("font-size", "13px");
        text.setAttribute("font-weight", "600");
        if (onLeft) {
            text.setAttribute("x", node.x - 10);
            text.setAttribute("text-anchor", "end");
        } else if (onRight) {
            text.setAttribute("x", node.x + node.width + 10);
            text.setAttribute("text-anchor", "start");
        } else {
            // Simmetrika: beside the node over a halo of the background (above it, centred, it sat on
            // the bands and on the node above), kept a line apart from its column's neighbours.
            text.setAttribute("x", node.x + node.width + 6);
            text.setAttribute("text-anchor", "start");
            text.setAttribute("stroke", haloColor);
            text.setAttribute("stroke-width", "3");
            text.setAttribute("stroke-linejoin", "round");
            text.setAttribute("paint-order", "stroke");
            middleLabels.push({ el: text, col: node.x, y: node.y + node.height / 2 + 4, name: node.name });
        }
        text.textContent = node.name;
        text.setAttribute('data-label', node.name);
        labelGroup.appendChild(text);
    });

    const columns = new Map();
    middleLabels.forEach((l) => {
        if (!columns.has(l.col)) columns.set(l.col, []);
        columns.get(l.col).push(l);
    });
    columns.forEach((list) => {
        list.sort((a, b) => a.y - b.y);
        for (let i = 1; i < list.length; i++) list[i].y = Math.max(list[i].y, list[i - 1].y + 16);
        list.forEach((l) => l.el.setAttribute("y", l.y));
    });
    // A band's value under a label goes (the node's name is what is read there).
    const ctx = typeof document !== 'undefined' ? document.createElement('canvas').getContext('2d') : null;
    if (ctx) ctx.font = '600 13px ' + (typeof getUiFontFamily === 'function' ? getUiFontFamily() : 'system-ui');
    middleLabels.forEach((l) => {
        const x0 = Number(l.el.getAttribute("x"));
        const x1 = x0 + (ctx ? ctx.measureText(l.name).width : l.name.length * 8) + 4;
        bandLabels.forEach((v) => {
            if (v.x + v.w / 2 > x0 && v.x - v.w / 2 < x1 && Math.abs(v.y - l.y) < 14) v.el.remove();
        });
    });

    return { svg, width, height, svgString: new XMLSerializer().serializeToString(svg) };
}

;

// ===== 60-svg-renderer-sankey.js =====
/**
 * Рендерер классического Sankey («Потоки»).
 * Ленты — цвет источника, полупрозрачные; узлы — вертикальные бруски с итогами.
 */
function generateSankeySVG(layoutData, themeColors) {
    const { nodes, links, width, height, title, columnLabels } = layoutData;
    const svgNS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(svgNS, 'svg');
    svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
    svg.setAttribute('width', width);
    svg.setAttribute('height', height);
    svg.style.fontFamily = (typeof getUiFontFamily === 'function' ? getUiFontFamily() : 'system-ui, -apple-system, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif');
    svg.style.fontSize = '13px';

    const isDark = document.body.classList.contains('dark');
    const theme = themeColors || [];
    const defaultColor = isDark ? '#60a5fa' : '#3b82f6';
    const labelColor = isDark ? '#e5e7eb' : '#1f2937';
    const mutedColor = isDark ? '#94a3b8' : '#64748b';
    const valueOnLink = isDark ? '#f8fafc' : '#0f172a';

    function softHex(hex, mixWith, t) {
        const parse = (h) => {
            const s = String(h || '').replace('#', '');
            if (s.length !== 6) return [59, 130, 246];
            return [parseInt(s.slice(0, 2), 16), parseInt(s.slice(2, 4), 16), parseInt(s.slice(4, 6), 16)];
        };
        const a = parse(hex);
        const b = parse(mixWith);
        const m = (i) => Math.round(a[i] * (1 - t) + b[i] * t);
        return `#${[m(0), m(1), m(2)].map((n) => n.toString(16).padStart(2, '0')).join('')}`;
    }

    function fmt(n) {
        return (Math.round(n * 100) / 100).toLocaleString('ru-RU');
    }

    const defs = document.createElementNS(svgNS, 'defs');
    svg.appendChild(defs);

    if (title) {
        const titleEl = document.createElementNS(svgNS, 'text');
        titleEl.setAttribute('x', width / 2);
        titleEl.setAttribute('y', 30);
        titleEl.setAttribute('fill', labelColor);
        titleEl.setAttribute('text-anchor', 'middle');
        titleEl.setAttribute('font-weight', '700');
        titleEl.setAttribute('font-size', '16px');
        titleEl.textContent = title;
        svg.appendChild(titleEl);
    }

    (columnLabels || []).forEach((col) => {
        const t = document.createElementNS(svgNS, 'text');
        t.setAttribute('x', col.x);
        t.setAttribute('y', col.y);
        t.setAttribute('text-anchor', 'middle');
        t.setAttribute('fill', labelColor);
        t.setAttribute('font-size', '15px');
        t.setAttribute('font-weight', '700');
        t.setAttribute('letter-spacing', '0.02em');
        t.textContent = col.text;
        svg.appendChild(t);
    });

    const linkGroup = document.createElementNS(svgNS, 'g');
    const nodeGroup = document.createElementNS(svgNS, 'g');
    const labelGroup = document.createElementNS(svgNS, 'g');
    const linkLabels = [];
    svg.appendChild(linkGroup);
    svg.appendChild(nodeGroup);
    svg.appendChild(labelGroup);

    // Цвет узла: по порядку появления слева направо / сверху вниз
    const nodeColorMap = new Map();
    const sortedForColor = [...nodes].sort((a, b) => (a.x - b.x) || (a.y - b.y));
    sortedForColor.forEach((node, i) => {
        nodeColorMap.set(node.name, theme.length ? theme[i % theme.length] : defaultColor);
    });

    // Ленты: цвет источника, полупрозрачность (классический Sankey)
    links.forEach((link, idx) => {
        const sourceColor = nodeColorMap.get(link.source) || defaultColor;
        const x0 = link.x1;
        const x1 = link.x2;
        const y0 = link.y1;
        const y1 = link.y2;
        const t0 = Math.max(2, link.thickness || 10) / 2;
        const t1 = Math.max(2, link.targetThickness != null ? link.targetThickness : link.thickness || 10) / 2;
        const dx = x1 - x0;
        const c1 = x0 + dx * 0.45;
        const c2 = x1 - dx * 0.45;

        const d = [
            `M ${x0} ${y0 - t0}`,
            `C ${c1} ${y0 - t0}, ${c2} ${y1 - t1}, ${x1} ${y1 - t1}`,
            `L ${x1} ${y1 + t1}`,
            `C ${c2} ${y1 + t1}, ${c1} ${y0 + t0}, ${x0} ${y0 + t0}`,
            'Z'
        ].join(' ');

        const path = document.createElementNS(svgNS, 'path');
        path.setAttribute('d', d);
        path.setAttribute('fill', softHex(sourceColor, isDark ? '#0f172a' : '#ffffff', 0.12));
        path.setAttribute('fill-opacity', isDark ? '0.55' : '0.48');
        path.setAttribute('stroke', 'none');
        if (typeof setDiagramSourceLine === 'function') {
            setDiagramSourceLine(path, link.line || link.sourceLine);
        }
        linkGroup.appendChild(path);

        // Подпись потока — только на достаточно толстых лентах
        const band = Math.min(t0, t1) * 2;
        if (band >= 18) {
            const midX = (x0 + x1) / 2;
            const midY = (y0 + y1) / 2;
            const text = document.createElementNS(svgNS, 'text');
            text.setAttribute('x', midX);
            text.setAttribute('y', midY + 4);
            text.setAttribute('fill', valueOnLink);
            text.setAttribute('text-anchor', 'middle');
            text.setAttribute('font-size', '11px');
            text.setAttribute('font-weight', '700');
            text.setAttribute('opacity', '0.9');
            text.textContent = fmt(link.value);
            labelGroup.appendChild(text);
            linkLabels.push({ el: text, x: midX, y: midY + 4, w: String(text.textContent).length * 7 + 4 });
        }
    });

    const layerXs = [...new Set(nodes.map((n) => n.x))].sort((a, b) => a - b);
    const firstX = layerXs[0];
    const lastX = layerXs[layerXs.length - 1];

    const haloColor = typeof readCssColor === 'function'
        ? readCssColor('--diagram-bg', isDark ? '#161618' : '#f8fafc')
        : (isDark ? '#161618' : '#f8fafc');
    const middleLabels = [];
    nodes.forEach((node) => {
        const color = nodeColorMap.get(node.name) || defaultColor;
        const rect = document.createElementNS(svgNS, 'rect');
        rect.setAttribute('x', node.x);
        rect.setAttribute('y', node.y);
        rect.setAttribute('width', node.width);
        rect.setAttribute('height', node.height);
        rect.setAttribute('fill', color);
        rect.setAttribute('rx', '2');
        rect.setAttribute('stroke', isDark ? '#0b1220' : '#ffffff');
        rect.setAttribute('stroke-width', '1');
        if (typeof setDiagramSourceLine === 'function') {
            setDiagramSourceLine(rect, node.sourceLine || node.line);
        }
        nodeGroup.appendChild(rect);

        const onLeft = node.x <= firstX + 1;
        const onRight = node.x >= lastX - 1;
        const nameEl = document.createElementNS(svgNS, 'text');
        nameEl.setAttribute('fill', labelColor);
        nameEl.setAttribute('font-size', '13px');
        nameEl.setAttribute('font-weight', '700');
        const flowEl = document.createElementNS(svgNS, 'text');
        flowEl.setAttribute('fill', mutedColor);
        flowEl.setAttribute('font-size', '11px');
        flowEl.setAttribute('font-weight', '600');
        flowEl.textContent = fmt(node.flow);

        if (onLeft) {
            nameEl.setAttribute('x', node.x - 10);
            nameEl.setAttribute('y', node.y + node.height / 2 - 2);
            nameEl.setAttribute('text-anchor', 'end');
            flowEl.setAttribute('x', node.x - 10);
            flowEl.setAttribute('y', node.y + node.height / 2 + 14);
            flowEl.setAttribute('text-anchor', 'end');
        } else if (onRight) {
            nameEl.setAttribute('x', node.x + node.width + 10);
            nameEl.setAttribute('y', node.y + node.height / 2 - 2);
            nameEl.setAttribute('text-anchor', 'start');
            flowEl.setAttribute('x', node.x + node.width + 10);
            flowEl.setAttribute('y', node.y + node.height / 2 + 14);
            flowEl.setAttribute('text-anchor', 'start');
        } else {
            // Simmetrika: a middle node is labelled beside it, name and value on one line, over a halo
            // of the background — above it, centred, labels of a dense column ran into each other.
            nameEl.setAttribute('x', node.x + node.width + 6);
            nameEl.setAttribute('y', node.y + node.height / 2 + 4);
            nameEl.setAttribute('text-anchor', 'start');
            nameEl.setAttribute('font-size', '12px');
            nameEl.setAttribute('stroke', haloColor);
            nameEl.setAttribute('stroke-width', '3');
            nameEl.setAttribute('stroke-linejoin', 'round');
            nameEl.setAttribute('paint-order', 'stroke');
            nameEl.textContent = node.name + ' ';
            const value = document.createElementNS(svgNS, 'tspan');
            value.setAttribute('fill', mutedColor);
            value.setAttribute('font-weight', '600');
            value.setAttribute('font-size', '11px');
            value.textContent = fmt(node.flow);
            nameEl.appendChild(value);
            nameEl.setAttribute('data-label', node.name);
            labelGroup.appendChild(nameEl);
            middleLabels.push({ el: nameEl, x: node.x, y: node.y + node.height / 2 + 4 });
            return;
        }
        nameEl.textContent = node.name;
        nameEl.setAttribute('data-label', node.name);
        labelGroup.appendChild(nameEl);
        labelGroup.appendChild(flowEl);
    });

    // Labels of one middle column kept a line apart, nearest to their nodes.
    const columns = new Map();
    middleLabels.forEach((l) => {
        if (!columns.has(l.x)) columns.set(l.x, []);
        columns.get(l.x).push(l);
    });
    columns.forEach((list) => {
        list.sort((a, b) => a.y - b.y);
        const LINE = 15;
        for (let i = 1; i < list.length; i++) list[i].y = Math.max(list[i].y, list[i - 1].y + LINE);
        list.forEach((l) => l.el.setAttribute('y', l.y));
    });

    // A value on a band under a node's label goes: the label already says it.
    const measure = (() => {
        if (typeof document === 'undefined') return (t) => t.length * 7;
        const ctx = document.createElement('canvas').getContext('2d');
        ctx.font = '700 12px ' + (typeof getUiFontFamily === 'function' ? getUiFontFamily() : 'system-ui');
        return (t) => ctx.measureText(t).width;
    })();
    middleLabels.forEach((l) => {
        const x0 = Number(l.el.getAttribute('x'));
        const x1 = x0 + measure(l.el.textContent) + 4;
        const y = l.y;
        linkLabels.forEach((v) => {
            if (v.x + v.w / 2 > x0 && v.x - v.w / 2 < x1 && Math.abs(v.y - y) < 13) v.el.remove();
        });
    });

    return { svg, width, height, svgString: new XMLSerializer().serializeToString(svg) };
}

;

// ===== 61-svg-renderer-pulsewave.js =====
/**
 * Рендерер «Динамика волны».
 * Лента меняет толщину; дельты на сегментах и итог по ряду.
 */
function generatePulsewaveSVG(layoutData, themeColors) {
    const { nodes, links, width, height, title, sliceLabels } = layoutData;
    const svgNS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(svgNS, 'svg');
    svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
    svg.setAttribute('width', width);
    svg.setAttribute('height', height);
    svg.style.fontFamily = (typeof getUiFontFamily === 'function' ? getUiFontFamily() : 'system-ui, -apple-system, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif');
    svg.style.fontSize = '19px';

    const isDark = document.body.classList.contains('dark');
    const theme = themeColors || [];
    const defaultColor = isDark ? '#60a5fa' : '#3b82f6';
    const labelColor = isDark ? '#e5e7eb' : '#1f2937';
    const valueColor = isDark ? '#f8fafc' : '#111827';
    const helperColor = isDark ? '#94a3b8' : '#64748b';
    const guideColor = isDark ? '#1e293b' : '#e2e8f0';
    const upColor = isDark ? '#4ade80' : '#16a34a';
    const downColor = isDark ? '#f87171' : '#dc2626';

    function softHex(hex, mixWith, t) {
        const parse = (h) => {
            const s = String(h || '').replace('#', '');
            if (s.length !== 6) return [59, 130, 246];
            return [parseInt(s.slice(0, 2), 16), parseInt(s.slice(2, 4), 16), parseInt(s.slice(4, 6), 16)];
        };
        const a = parse(hex);
        const b = parse(mixWith);
        const m = (i) => Math.round(a[i] * (1 - t) + b[i] * t);
        return `#${[m(0), m(1), m(2)].map((n) => n.toString(16).padStart(2, '0')).join('')}`;
    }

    function fmtNum(n) {
        const v = Math.round(n * 100) / 100;
        return String(v).replace('.', ',');
    }

    function fmtDelta(from, to) {
        const d = to - from;
        const pct = from !== 0 ? (d / from) * 100 : 0;
        const sign = d > 0 ? '+' : '';
        return { d, pct, text: sign + fmtNum(d), pctText: sign + fmtNum(Math.round(pct * 10) / 10) + '%' };
    }

    const defs = document.createElementNS(svgNS, 'defs');
    svg.appendChild(defs);

    if (title) {
        const titleEl = document.createElementNS(svgNS, 'text');
        titleEl.setAttribute('x', width / 2);
        titleEl.setAttribute('y', 40);
        titleEl.setAttribute('fill', labelColor);
        titleEl.setAttribute('text-anchor', 'middle');
        titleEl.setAttribute('font-weight', '700');
        titleEl.setAttribute('font-size', '24px');
        titleEl.textContent = title;
        svg.appendChild(titleEl);
    }

    const guides = document.createElementNS(svgNS, 'g');
    const linkGroup = document.createElementNS(svgNS, 'g');
    const nodeGroup = document.createElementNS(svgNS, 'g');
    const labelGroup = document.createElementNS(svgNS, 'g');
    svg.appendChild(guides);
    svg.appendChild(linkGroup);
    svg.appendChild(nodeGroup);
    svg.appendChild(labelGroup);

    const colorBySeries = new Map();
    nodes.forEach((node) => {
        if (!colorBySeries.has(node.seriesName)) {
            const i = colorBySeries.size;
            colorBySeries.set(node.seriesName, theme.length ? theme[i % theme.length] : defaultColor);
        }
    });

    const slicesRendered = new Set();
    (sliceLabels || []).forEach((slice) => {
        if (slicesRendered.has(slice.text)) return;
        slicesRendered.add(slice.text);

        const guide = document.createElementNS(svgNS, 'line');
        guide.setAttribute('x1', slice.x);
        guide.setAttribute('x2', slice.x);
        guide.setAttribute('y1', slice.y + 16);
        guide.setAttribute('y2', height - 28);
        guide.setAttribute('stroke', guideColor);
        guide.setAttribute('stroke-width', '1');
        guide.setAttribute('stroke-dasharray', '4 6');
        guide.setAttribute('opacity', '0.9');
        guides.appendChild(guide);

        const text = document.createElementNS(svgNS, 'text');
        text.setAttribute('x', slice.x);
        text.setAttribute('y', slice.y);
        text.setAttribute('text-anchor', 'middle');
        text.setAttribute('fill', helperColor);
        text.setAttribute('font-size', '18px');
        text.setAttribute('font-weight', '700');
        text.textContent = slice.text;
        labelGroup.appendChild(text);
    });

    links.forEach((link, idx) => {
        const color = colorBySeries.get(link.seriesName) || defaultColor;
        const x0 = link.x1;
        const x1 = link.x2;
        const y0 = link.y1;
        const y1 = link.y2;
        const t0 = Math.max(2, link.thickness || 10) / 2;
        const t1 = Math.max(2, link.targetThickness || 10) / 2;
        const dx = x1 - x0;
        const c1 = x0 + dx * 0.42;
        const c2 = x1 - dx * 0.42;

        const d = [
            `M ${x0} ${y0 - t0}`,
            `C ${c1} ${y0 - t0}, ${c2} ${y1 - t1}, ${x1} ${y1 - t1}`,
            `L ${x1} ${y1 + t1}`,
            `C ${c2} ${y1 + t1}, ${c1} ${y0 + t0}, ${x0} ${y0 + t0}`,
            'Z'
        ].join(' ');

        const gradId = `pulsewave-grad-${idx}`;
        const grad = document.createElementNS(svgNS, 'linearGradient');
        grad.setAttribute('id', gradId);
        grad.setAttribute('x1', String(x0));
        grad.setAttribute('y1', '0');
        grad.setAttribute('x2', String(x1));
        grad.setAttribute('y2', '0');
        grad.setAttribute('gradientUnits', 'userSpaceOnUse');
        const s1 = document.createElementNS(svgNS, 'stop');
        s1.setAttribute('offset', '0%');
        s1.setAttribute('stop-color', softHex(color, isDark ? '#0f172a' : '#ffffff', 0.08));
        s1.setAttribute('stop-opacity', '0.78');
        const s2 = document.createElementNS(svgNS, 'stop');
        s2.setAttribute('offset', '100%');
        s2.setAttribute('stop-color', softHex(color, isDark ? '#0f172a' : '#ffffff', 0.18));
        s2.setAttribute('stop-opacity', '0.9');
        grad.appendChild(s1);
        grad.appendChild(s2);
        defs.appendChild(grad);

        const path = document.createElementNS(svgNS, 'path');
        path.setAttribute('d', d);
        path.setAttribute('fill', `url(#${gradId})`);
        path.setAttribute('stroke', 'none');
        if (typeof setDiagramSourceLine === 'function') {
            setDiagramSourceLine(path, link.line || link.sourceLine);
        }
        linkGroup.appendChild(path);
    });

    const bySeries = new Map();
    nodes.forEach((node) => {
        if (!bySeries.has(node.seriesName)) bySeries.set(node.seriesName, []);
        bySeries.get(node.seriesName).push(node);
    });
    bySeries.forEach((rowNodes) => {
        rowNodes.sort((a, b) => a.x - b.x);
        const first = rowNodes[0];
        const last = rowNodes[rowNodes.length - 1];
        const total = fmtDelta(first.value, last.value);
        const totalColor = total.d >= 0 ? upColor : downColor;
        const arrow = total.d >= 0 ? '▲' : '▼';

        const summary = document.createElementNS(svgNS, 'text');
        summary.setAttribute('x', last.x + last.width + 14);
        summary.setAttribute('y', last.centerY + 2);
        summary.setAttribute('fill', totalColor);
        summary.setAttribute('font-size', '22px');
        summary.setAttribute('font-weight', '700');
        summary.textContent = `${arrow} ${total.pctText}`;
        labelGroup.appendChild(summary);

        const abs = document.createElementNS(svgNS, 'text');
        abs.setAttribute('x', last.x + last.width + 14);
        abs.setAttribute('y', last.centerY + 26);
        abs.setAttribute('fill', helperColor);
        abs.setAttribute('font-size', '18px');
        abs.setAttribute('font-weight', '600');
        abs.textContent = `(${total.text})`;
        labelGroup.appendChild(abs);
    });

    links.forEach((link) => {
        const delta = fmtDelta(link.fromValue, link.toValue);
        const deltaColor = delta.d >= 0 ? upColor : (delta.d < 0 ? downColor : helperColor);
        const midX = (link.x1 + link.x2) / 2;
        const band = Math.max(link.thickness || 0, link.targetThickness || 0);
        const midY = (link.y1 + link.y2) / 2 - band / 2 - 14;

        const pillW = 68;
        const pillH = 26;
        const pill = document.createElementNS(svgNS, 'rect');
        pill.setAttribute('x', midX - pillW / 2);
        pill.setAttribute('y', midY - pillH / 2);
        pill.setAttribute('width', pillW);
        pill.setAttribute('height', pillH);
        pill.setAttribute('rx', '13');
        pill.setAttribute('fill', isDark ? '#0b1220' : '#ffffff');
        pill.setAttribute('stroke', deltaColor);
        pill.setAttribute('stroke-width', '1');
        pill.setAttribute('opacity', '0.94');
        labelGroup.appendChild(pill);

        const dt = document.createElementNS(svgNS, 'text');
        dt.setAttribute('x', midX);
        dt.setAttribute('y', midY + 6);
        dt.setAttribute('text-anchor', 'middle');
        dt.setAttribute('fill', deltaColor);
        dt.setAttribute('font-size', '17px');
        dt.setAttribute('font-weight', '700');
        dt.textContent = delta.pctText;
        labelGroup.appendChild(dt);
    });

    nodes.forEach((node, index) => {
        const color = colorBySeries.get(node.seriesName) || defaultColor;
        const rowNodes = bySeries.get(node.seriesName) || [];
        const isMax = rowNodes.length && node.value === Math.max.apply(null, rowNodes.map((n) => n.value));
        const isMin = rowNodes.length > 1 && node.value === Math.min.apply(null, rowNodes.map((n) => n.value));

        const rect = document.createElementNS(svgNS, 'rect');
        rect.setAttribute('x', node.x);
        rect.setAttribute('y', node.y);
        rect.setAttribute('width', node.width);
        rect.setAttribute('height', node.height);
        rect.setAttribute('fill', color);
        rect.setAttribute('rx', '3');
        if (typeof setDiagramSourceLine === 'function') {
            setDiagramSourceLine(rect, node.sourceLine || node.line);
        }
        if (isMax) {
            rect.setAttribute('stroke', upColor);
            rect.setAttribute('stroke-width', '2');
        } else if (isMin) {
            rect.setAttribute('stroke', downColor);
            rect.setAttribute('stroke-width', '2');
            rect.setAttribute('stroke-dasharray', '3 2');
        }
        nodeGroup.appendChild(rect);

        const val = document.createElementNS(svgNS, 'text');
        val.setAttribute('x', node.x + node.width / 2);
        val.setAttribute('y', node.y - 12);
        val.setAttribute('text-anchor', 'middle');
        val.setAttribute('fill', valueColor);
        val.setAttribute('font-size', '18px');
        val.setAttribute('font-weight', '700');
        val.textContent = fmtNum(node.value);
        labelGroup.appendChild(val);

        if (index === 0 || nodes[index - 1].seriesName !== node.seriesName) {
            const label = document.createElementNS(svgNS, 'text');
            label.setAttribute('x', node.x - 14);
            label.setAttribute('y', node.centerY + 6);
            label.setAttribute('text-anchor', 'end');
            label.setAttribute('fill', labelColor);
            label.setAttribute('font-size', '19px');
            label.setAttribute('font-weight', '600');
            label.textContent = node.seriesName;
            label.setAttribute('data-label', node.seriesName);
            labelGroup.appendChild(label);
        }
    });

    return { svg, width, height, svgString: new XMLSerializer().serializeToString(svg) };
}

;

// ===== 62-svg-renderer-gantt.js =====
function generateGanttSVG(layoutData, themeColors) {
    const {
        title,
        startDate,
        chartOriginDate,
        totalDays,
        dayWidth,
        leftMargin,
        topMargin,
        bottomMargin,
        rightMargin,
        rowHeight,
        headerHeight,
        barHeight,
        barRadius,
        chartWidth,
        chartHeight,
        tasks,
        sections,
        commentLineHeight,
        commentPadding,
        scaleStep,
        scaleLabelFormat
    } = layoutData;

    // Защита от некорректных значений
    const safeTotalDays = (isFinite(totalDays) && totalDays > 0) ? totalDays : 1;
    const safeDayWidth = (isFinite(dayWidth) && dayWidth > 0) ? dayWidth : 25;
    const safeHeaderHeight = (isFinite(headerHeight) && headerHeight > 0) ? headerHeight : 40;
    const safeChartHeight = (isFinite(chartHeight) && chartHeight > 0) ? chartHeight : 200;
    const safeChartWidth = (isFinite(chartWidth) && chartWidth > 20) ? chartWidth : 200;
    const safeTopMargin = (isFinite(topMargin) && topMargin > 0) ? topMargin : 90;
    const safeBottomMargin = (isFinite(bottomMargin) && bottomMargin > 0) ? bottomMargin : 40;
    const safeLeftMargin = (isFinite(leftMargin) && leftMargin > 0) ? leftMargin : 180;
    const safeRightMargin = (isFinite(rightMargin) && rightMargin > 0) ? rightMargin : 40;
    const safeRowHeight = (isFinite(rowHeight) && rowHeight > 0) ? rowHeight : 30;
    const safeBarHeight = (isFinite(barHeight) && barHeight > 0) ? barHeight : 20;
    const safeBarRadius = (isFinite(barRadius) && barRadius > 0) ? barRadius : 4;
    const safeCommentLineHeight = (isFinite(commentLineHeight) && commentLineHeight > 0) ? commentLineHeight : 14;
    const safeScaleStep = (isFinite(scaleStep) && scaleStep > 0) ? scaleStep : 1;

    const adjustedTopMargin = Math.max(safeTopMargin, 90);
    const totalWidth = safeChartWidth + safeLeftMargin + safeRightMargin;
    const totalHeight = safeChartHeight + adjustedTopMargin + safeBottomMargin;

    const svgNS = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(svgNS, "svg");
    svg.setAttribute("viewBox", `0 0 ${totalWidth} ${totalHeight}`);
    svg.setAttribute("width", totalWidth);
    svg.setAttribute("height", totalHeight);
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", title || "Диаграмма Ганта");
    svg.style.fontFamily = (typeof getUiFontFamily === "function" ? getUiFontFamily() : "system-ui, -apple-system, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif");
    svg.style.fontSize = "12px";

    const isDark = document.body.classList.contains('dark');
    const theme = themeColors || [];
    const primaryColor = theme.length > 0 ? theme[0] : (isDark ? '#60a5fa' : '#3b82f6');
    const textColor = typeof readCssColor === 'function'
        ? readCssColor('--text', isDark ? '#f5f5f7' : '#0f172a')
        : (isDark ? '#f8fafc' : '#1f2937');
    const gridColor = typeof readCssColor === 'function'
        ? readCssColor('--secondary-text', isDark ? '#a1a1a6' : '#64748b')
        : (isDark ? '#94a3b8' : '#64748b');
    // Фон SVG = фон области диаграммы на сайте (не белый/slate)
    const bgColor = typeof readCssColor === 'function'
        ? readCssColor('--diagram-bg', isDark ? '#161618' : '#f8fafc')
        : (isDark ? '#161618' : '#f8fafc');
    const panelColor = typeof readCssColor === 'function'
        ? readCssColor('--panel-bg', isDark ? '#1c1c1e' : '#ffffff')
        : (isDark ? '#1c1c1e' : '#ffffff');
    const sectionHeaderFill = isDark ? 'rgba(0,0,0,0.28)' : 'rgba(15,23,42,0.06)';
    const rowFill = isDark ? 'rgba(255,255,255,0.04)' : 'rgba(15,23,42,0.028)';
    const drawBarRadius = Math.min(safeBarRadius, 4);

    const sectionColors = {};
    sections.forEach((section, index) => {
        sectionColors[section.name] = theme.length > 0 ? theme[index % theme.length] : primaryColor;
    });

    function softSectionFill(hex) {
        if (typeof mixHex !== 'function') return sectionHeaderFill;
        return mixHex(hex, bgColor, isDark ? 0.90 : 0.93);
    }
    function softRowTint(hex) {
        if (typeof mixHex !== 'function') return rowFill;
        return mixHex(hex, bgColor, isDark ? 0.95 : 0.96);
    }
    // ---- ФОН ----
    const bgRect = document.createElementNS(svgNS, "rect");
    bgRect.setAttribute("width", "100%");
    bgRect.setAttribute("height", "100%");
    bgRect.setAttribute("fill", bgColor);
    svg.appendChild(bgRect);

    // ---- ЗАГОЛОВОК ----
    const titleText = document.createElementNS(svgNS, "text");
    titleText.setAttribute("x", safeLeftMargin);
    titleText.setAttribute("y", adjustedTopMargin - 20);
    titleText.setAttribute("fill", textColor);
    titleText.setAttribute("font-size", "18px");
    titleText.setAttribute("font-weight", "bold");
    titleText.textContent = title || 'Диаграмма Ганта';
    svg.appendChild(titleText);

    // ---- ФОН СТРОК / ЗАГОЛОВКИ РАЗДЕЛОВ ----
    const rowsGroup = document.createElementNS(svgNS, "g");
    svg.appendChild(rowsGroup);

    tasks.forEach(task => {
        if (typeof task.rowY !== 'number' || !isFinite(task.rowY)) return;

        if (task.isSectionHeader) {
            const secColor = sectionColors[task.name] || primaryColor;
            const hdrH = task.rowHeight || 26;

            // Спокойная полоса на всю ширину — без яркой цветной линии через чарт
            const hdr = document.createElementNS(svgNS, "rect");
            hdr.setAttribute("x", 0);
            hdr.setAttribute("y", task.rowY);
            hdr.setAttribute("width", totalWidth);
            hdr.setAttribute("height", hdrH);
            hdr.setAttribute("fill", softSectionFill(secColor));
            rowsGroup.appendChild(hdr);

            // Цветной акцент между названием и чартом (не поверх текста)
            const accent = document.createElementNS(svgNS, "rect");
            accent.setAttribute("x", safeLeftMargin - 6);
            accent.setAttribute("y", task.rowY + 5);
            accent.setAttribute("width", 3);
            accent.setAttribute("height", Math.max(8, hdrH - 10));
            accent.setAttribute("rx", "1.5");
            accent.setAttribute("fill", secColor);
            accent.setAttribute("opacity", "0.85");
            rowsGroup.appendChild(accent);

            // Summary / rollup фазы
            if (task.isRollup && task.rollupWidth > 0) {
                const roll = document.createElementNS(svgNS, "rect");
                roll.setAttribute("x", task.rollupX);
                roll.setAttribute("y", task.rowY + 7);
                roll.setAttribute("width", task.rollupWidth);
                roll.setAttribute("height", Math.max(6, hdrH - 14));
                roll.setAttribute("rx", "2");
                roll.setAttribute("fill", secColor);
                roll.setAttribute("opacity", "0.35");
                rowsGroup.appendChild(roll);
            }

            const rule = document.createElementNS(svgNS, "line");
            rule.setAttribute("x1", 0);
            rule.setAttribute("y1", task.rowY + hdrH - 0.5);
            rule.setAttribute("x2", totalWidth);
            rule.setAttribute("y2", task.rowY + hdrH - 0.5);
            rule.setAttribute("stroke", gridColor);
            rule.setAttribute("stroke-width", "1");
            rule.setAttribute("opacity", "0.28");
            rowsGroup.appendChild(rule);

            const hdrText = document.createElementNS(svgNS, "text");
            hdrText.setAttribute("x", safeLeftMargin - 12);
            hdrText.setAttribute("y", task.rowY + hdrH / 2 + 4);
            hdrText.setAttribute("fill", textColor);
            hdrText.setAttribute("text-anchor", "end");
            hdrText.setAttribute("font-size", "12px");
            hdrText.setAttribute("font-weight", "700");
            hdrText.textContent = task.name;
            rowsGroup.appendChild(hdrText);
            return;
        }
        // Дорожки задач без заливки — хватает цвета названия и полосы.
    });

    // ---- ЗАДАЧИ ----
    const taskGroup = document.createElementNS(svgNS, "g");
    svg.appendChild(taskGroup);

    tasks.forEach(task => {
        if (task.isSectionHeader) return;
        if (typeof task.x !== 'number' || !isFinite(task.x) ||
            typeof task.rowY !== 'number' || !isFinite(task.rowY)) {
            return;
        }

        const color = sectionColors[task.sectionName] || primaryColor;
        const taskRowHeight = task.rowHeight || safeRowHeight;
        const barY = task.rowY + (taskRowHeight - safeBarHeight) / 2;

        // Название задачи — цвет раздела (как полоса)
        const nameText = document.createElementNS(svgNS, "text");
        nameText.setAttribute("x", safeLeftMargin - 10);
        nameText.setAttribute("y", task.rowY + taskRowHeight / 2 + (task.assignee ? -2 : 4));
        // The section's colour, darkened until it reads on the panel (pastel names were faint).
        nameText.setAttribute("fill", readableTextColor(color, bgColor));
        nameText.setAttribute("text-anchor", "end");
        nameText.setAttribute("font-size", "12px");
        nameText.setAttribute("font-weight", "600");
        nameText.textContent = task.name;
        nameText.setAttribute('data-label', task.name);
        if (typeof setDiagramSourceLine === 'function') {
            setDiagramSourceLine(nameText, task.sourceLine || task.line);
        }
        taskGroup.appendChild(nameText);

        if (task.assignee) {
            const who = document.createElementNS(svgNS, "text");
            who.setAttribute("x", safeLeftMargin - 10);
            who.setAttribute("y", task.rowY + taskRowHeight / 2 + 12);
            who.setAttribute("fill", readableTextColor(color, bgColor));
            who.setAttribute("text-anchor", "end");
            who.setAttribute("font-size", "10px");
            who.setAttribute("opacity", "0.75");
            who.textContent = '@' + task.assignee;
            taskGroup.appendChild(who);
        }

        if (task.isMilestone) {
            // Веха — короткая вертикальная риска (не ромб)
            const cx = task.x;
            const cy = task.rowY + taskRowHeight / 2;
            const tick = document.createElementNS(svgNS, "rect");
            tick.setAttribute("x", cx - 2);
            tick.setAttribute("y", cy - 9);
            tick.setAttribute("width", 4);
            tick.setAttribute("height", 18);
            tick.setAttribute("rx", "2");
            tick.setAttribute("fill", color);
            if (typeof setDiagramSourceLine === 'function') {
                setDiagramSourceLine(tick, task.sourceLine || task.line);
            }
            taskGroup.appendChild(tick);
        } else {
            const barW = Math.max(task.width || 0, 4);
            const progress = (typeof task.progress === 'number') ? task.progress : null;

            if (progress != null) {
                const bar = document.createElementNS(svgNS, "rect");
                bar.setAttribute("x", task.x);
                bar.setAttribute("y", barY);
                bar.setAttribute("width", barW);
                bar.setAttribute("height", safeBarHeight);
                bar.setAttribute("fill", color);
                bar.setAttribute("opacity", "0.22");
                bar.setAttribute("rx", drawBarRadius);
                bar.setAttribute("ry", drawBarRadius);
                bar.setAttribute("stroke", panelColor);
                bar.setAttribute("stroke-width", "1");
                if (typeof setDiagramSourceLine === 'function') {
                    setDiagramSourceLine(bar, task.sourceLine || task.line);
                }
                taskGroup.appendChild(bar);

                if (progress > 0) {
                    const fillW = Math.max(2, barW * (progress / 100));
                    const barFill = document.createElementNS(svgNS, "rect");
                    barFill.setAttribute("x", task.x);
                    barFill.setAttribute("y", barY);
                    barFill.setAttribute("width", fillW);
                    barFill.setAttribute("height", safeBarHeight);
                    barFill.setAttribute("fill", color);
                    barFill.setAttribute("rx", drawBarRadius);
                    barFill.setAttribute("ry", drawBarRadius);
                    taskGroup.appendChild(barFill);
                }
            } else {
                const bar = document.createElementNS(svgNS, "rect");
                bar.setAttribute("x", task.x);
                bar.setAttribute("y", barY);
                bar.setAttribute("width", barW);
                bar.setAttribute("height", safeBarHeight);
                bar.setAttribute("fill", color);
                bar.setAttribute("rx", drawBarRadius);
                bar.setAttribute("ry", drawBarRadius);
                bar.setAttribute("stroke", typeof mixHex === 'function' ? mixHex(color, '#000000', 0.22) : panelColor);
                bar.setAttribute("stroke-width", "1");
                if (typeof setDiagramSourceLine === 'function') {
                    setDiagramSourceLine(bar, task.sourceLine || task.line);
                }
                taskGroup.appendChild(bar);
            }

            const displayDuration = task.originalDuration || task.duration;
            if (displayDuration !== undefined && displayDuration !== null) {
                const label = progress != null
                    ? `${displayDuration}д · ${progress}%`
                    : `${displayDuration}д`;
                const durText = document.createElementNS(svgNS, "text");
                if (barW >= 36) {
                    durText.setAttribute("x", task.x + barW / 2);
                    durText.setAttribute("y", task.rowY + taskRowHeight / 2);
                    durText.setAttribute("dominant-baseline", "central");
                    durText.setAttribute("text-anchor", "middle");
                    durText.setAttribute("fill", getContrastColor(color));
                    durText.setAttribute("font-weight", "bold");
                } else {
                    durText.setAttribute("x", task.x + barW + 4);
                    durText.setAttribute("y", task.rowY + taskRowHeight / 2);
                    durText.setAttribute("dominant-baseline", "central");
                    durText.setAttribute("fill", readableTextColor(color, bgColor));
                }
                durText.setAttribute("font-size", "10px");
                durText.textContent = label;
                taskGroup.appendChild(durText);
            }
        }

        // Комментарий
        if (task.comment) {
            const barBottom = barY + safeBarHeight;
            const commentY = barBottom + 2;
            const maxCommentWidth = Math.min(280, safeChartWidth - 20);
            const words = task.comment.split(' ');
            let lines = [];
            let currentLine = '';
            const approxCharWidth = 6;

            words.forEach(word => {
                const testLine = currentLine ? currentLine + ' ' + word : word;
                if (testLine.length * approxCharWidth > maxCommentWidth) {
                    if (currentLine) lines.push(currentLine);
                    currentLine = word;
                } else {
                    currentLine = testLine;
                }
            });
            if (currentLine) lines.push(currentLine);

            const maxLines = 3;
            if (lines.length > maxLines) {
                lines = lines.slice(0, maxLines);
                lines[lines.length - 1] = lines[lines.length - 1] + '…';
            }

            lines.forEach((line, idx) => {
                const text = document.createElementNS(svgNS, "text");
                text.setAttribute("x", task.x);
                text.setAttribute("y", commentY + idx * safeCommentLineHeight + 10);
                text.setAttribute("fill", gridColor);
                text.setAttribute("font-size", "10px");
                text.setAttribute("font-style", "italic");
                if (idx === 0) {
                    text.textContent = '📌 ' + line;
                } else {
                    text.setAttribute("x", task.x + 14);
                    text.textContent = line;
                }
                taskGroup.appendChild(text);
            });
        }
    });

    // ---- ВЕРТИКАЛЬНЫЙ РАЗДЕЛИТЕЛЬ ----
    const divider = document.createElementNS(svgNS, "line");
    divider.setAttribute("x1", safeLeftMargin);
    divider.setAttribute("y1", adjustedTopMargin);
    divider.setAttribute("x2", safeLeftMargin);
    divider.setAttribute("y2", adjustedTopMargin + safeHeaderHeight + safeChartHeight - safeHeaderHeight);
    divider.setAttribute("stroke", gridColor);
    divider.setAttribute("stroke-width", "2");
    divider.setAttribute("opacity", "0.6");
    taskGroup.appendChild(divider);

    // ---- ВРЕМЕННАЯ ШКАЛА ----
    const scaleGroup = document.createElementNS(svgNS, "g");
    svg.appendChild(scaleGroup);

    const scaleY = adjustedTopMargin + safeHeaderHeight - 18;
    const scaleBg = document.createElementNS(svgNS, "rect");
    scaleBg.setAttribute("x", safeLeftMargin);
    scaleBg.setAttribute("y", scaleY - 20);
    scaleBg.setAttribute("width", safeChartWidth);
    scaleBg.setAttribute("height", 30);
    scaleBg.setAttribute("fill", bgColor);
    scaleBg.setAttribute("opacity", "0.92");
    scaleGroup.appendChild(scaleBg);

    const scaleLine = document.createElementNS(svgNS, "line");
    scaleLine.setAttribute("x1", safeLeftMargin);
    scaleLine.setAttribute("y1", scaleY);
    scaleLine.setAttribute("x2", safeLeftMargin + safeChartWidth);
    scaleLine.setAttribute("y2", scaleY);
    scaleLine.setAttribute("stroke", gridColor);
    scaleLine.setAttribute("stroke-width", "1.5");
    scaleLine.setAttribute("opacity", "0.6");
    scaleGroup.appendChild(scaleLine);

    const monthNames = ['Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт','Ноя','Дек'];
    const step = Math.max(1, Math.min(safeScaleStep, safeTotalDays));
    const chartOrigin = typeof startOfDay === 'function'
        ? startOfDay(chartOriginDate || startDate)
        : new Date(chartOriginDate || startDate);

    function xForChartDayOffset(dayOffset) {
        return safeLeftMargin + dayOffset * safeDayWidth;
    }

    for (let i = 0; i < safeTotalDays; i += step) {
        const date = typeof addCalendarDays === 'function'
            ? addCalendarDays(chartOrigin, i)
            : (() => { const d = new Date(chartOrigin); d.setDate(d.getDate() + i); return d; })();
        if (!date) continue;
        const x = xForChartDayOffset(i);
        if (x > safeLeftMargin + safeChartWidth) break;

        const line = document.createElementNS(svgNS, "line");
        line.setAttribute("x1", x);
        line.setAttribute("y1", scaleY);
        line.setAttribute("x2", x);
        line.setAttribute("y2", adjustedTopMargin + safeHeaderHeight + safeChartHeight - safeHeaderHeight);
        line.setAttribute("stroke", gridColor);
        line.setAttribute("stroke-width", "1.5");
        line.setAttribute("opacity", "0.4");
        scaleGroup.appendChild(line);

        let label = '';
        if (scaleLabelFormat === 'day') {
            label = date.getDate().toString();
        } else if (scaleLabelFormat === 'week') {
            const weekStart = new Date(date);
            weekStart.setDate(weekStart.getDate() - weekStart.getDay() + 1);
            label = weekStart.getDate() + '/' + (weekStart.getMonth() + 1);
        } else {
            label = monthNames[date.getMonth()] + ' ' + date.getFullYear();
        }

        const text = document.createElementNS(svgNS, "text");
        text.setAttribute("x", x);
        text.setAttribute("y", scaleY + 14);
        text.setAttribute("fill", textColor);
        text.setAttribute("text-anchor", "middle");
        text.setAttribute("font-size", "11px");
        text.setAttribute("font-weight", "500");
        text.textContent = label;
        scaleGroup.appendChild(text);
    }

    // ---- МАРКЕР «СЕГОДНЯ» (поверх сетки и полос) ----
    try {
        const today = typeof startOfToday === 'function' ? startOfToday() : startOfDay(new Date());
        if (chartOrigin && today && !isNaN(chartOrigin.getTime()) && !isNaN(today.getTime()) && safeTotalDays > 0) {
            const dayOffset = typeof diffCalendarDays === 'function'
                ? diffCalendarDays(chartOrigin, today)
                : 0;
            if (dayOffset >= 0 && dayOffset < safeTotalDays) {
                const tx = xForChartDayOffset(dayOffset);
                const y1 = adjustedTopMargin - 8;
                const y2 = adjustedTopMargin + safeChartHeight;
                const todayGroup = document.createElementNS(svgNS, 'g');
                todayGroup.setAttribute('pointer-events', 'none');

                const halo = document.createElementNS(svgNS, 'line');
                halo.setAttribute('x1', tx);
                halo.setAttribute('x2', tx);
                halo.setAttribute('y1', y1);
                halo.setAttribute('y2', y2);
                halo.setAttribute('stroke', bgColor);
                halo.setAttribute('stroke-width', '5');
                halo.setAttribute('opacity', '0.9');
                todayGroup.appendChild(halo);

                const todayLine = document.createElementNS(svgNS, 'line');
                todayLine.setAttribute('x1', tx);
                todayLine.setAttribute('x2', tx);
                todayLine.setAttribute('y1', y1);
                todayLine.setAttribute('y2', y2);
                todayLine.setAttribute('stroke', '#ef4444');
                todayLine.setAttribute('stroke-width', '2');
                todayLine.setAttribute('stroke-dasharray', '4 3');
                todayLine.setAttribute('opacity', '0.95');
                todayGroup.appendChild(todayLine);

                const todayLabel = document.createElementNS(svgNS, 'text');
                todayLabel.setAttribute('x', tx + 5);
                todayLabel.setAttribute('y', adjustedTopMargin - 10);
                todayLabel.setAttribute('fill', '#ef4444');
                todayLabel.setAttribute('font-size', '10px');
                todayLabel.setAttribute('font-weight', '700');
                todayLabel.setAttribute(
                    'font-family',
                    (typeof getUiFontFamily === 'function')
                        ? getUiFontFamily()
                        : 'system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif'
                );
                todayLabel.setAttribute('paint-order', 'stroke');
                todayLabel.setAttribute('stroke', bgColor);
                todayLabel.setAttribute('stroke-width', '3');
                todayLabel.textContent = 'Сегодня';
                todayGroup.appendChild(todayLabel);

                svg.appendChild(todayGroup);
            }
        }
    } catch (_) { /* ignore */ }

    return { svg, width: totalWidth, height: totalHeight };
}

;

// ===== 63-svg-renderer-treemap.js =====
/**
 * Рендерер Treemap («Плитка») — спокойные вложенные прямоугольники.
 */
function generateTreemapSVG(layoutData, themeColors) {
    const { nodes, width, height, rootName, rootValue } = layoutData;
    const svgNS = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(svgNS, "svg");
    svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
    svg.setAttribute("width", width);
    svg.setAttribute("height", height);
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", rootName || "Диаграмма «Плитка»");
    svg.style.fontFamily = (typeof getUiFontFamily === "function"
        ? getUiFontFamily()
        : "system-ui, -apple-system, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif");
    svg.style.fontSize = "13px";

    const isDark = document.body.classList.contains('dark');
    const theme = themeColors || [];
    const defaultColor = isDark ? '#64748b' : '#64748b';
    const bg = typeof readCssColor === 'function'
        ? readCssColor('--diagram-bg', isDark ? '#161618' : '#f8fafc')
        : (isDark ? '#161618' : '#f8fafc');
    const panel = typeof readCssColor === 'function'
        ? readCssColor('--panel-bg', isDark ? '#1c1c1e' : '#ffffff')
        : (isDark ? '#1c1c1e' : '#ffffff');
    const border = typeof readCssColor === 'function'
        ? readCssColor('--border', isDark ? '#3a3a3c' : '#e2e8f0')
        : (isDark ? '#3a3a3c' : '#e2e8f0');
    const textColor = typeof readCssColor === 'function'
        ? readCssColor('--text', isDark ? '#f5f5f7' : '#0f172a')
        : (isDark ? '#f5f5f7' : '#0f172a');
    const muted = typeof readCssColor === 'function'
        ? readCssColor('--secondary-text', isDark ? '#a1a1a6' : '#64748b')
        : (isDark ? '#a1a1a6' : '#64748b');
    /** Агрегирующие полосы — единый серый, без палитры (иначе рябит). */
    const headerFill = isDark ? '#3f3f46' : '#e4e4e7';

    function soft(hex, other, t) {
        return (typeof mixHex === 'function') ? mixHex(hex, other, t) : hex;
    }
    /** Приглушённый цвет клетки: тема сильно смешана с панелью */
    function tileColor(hex) {
        return soft(hex || defaultColor, panel, isDark ? 0.62 : 0.72);
    }

    const bgRect = document.createElementNS(svgNS, "rect");
    bgRect.setAttribute("x", "0");
    bgRect.setAttribute("y", "0");
    bgRect.setAttribute("width", String(width));
    bgRect.setAttribute("height", String(height));
    bgRect.setAttribute("fill", bg);
    svg.appendChild(bgRect);

    if (rootName) {
        const title = document.createElementNS(svgNS, "text");
        title.setAttribute("x", "16");
        title.setAttribute("y", "22");
        title.setAttribute("fill", textColor);
        title.setAttribute("font-size", "14px");
        title.setAttribute("font-weight", "600");
        title.textContent = rootName;
        svg.appendChild(title);

        if (rootValue != null && isFinite(rootValue)) {
            const valEl = document.createElementNS(svgNS, "text");
            valEl.setAttribute("x", "16");
            valEl.setAttribute("y", "22");
            valEl.setAttribute("dx", String(Math.min(280, 12 + String(rootName).length * 7.6)));
            valEl.setAttribute("fill", muted);
            valEl.setAttribute("font-size", "13px");
            valEl.setAttribute("font-weight", "500");
            valEl.textContent = '· ' + formatTreemapValue(rootValue);
            svg.appendChild(valEl);
        }
    }

    let leafIndex = 0;
    const tilesGroup = document.createElementNS(svgNS, "g");
    const labelsGroup = document.createElementNS(svgNS, "g");
    svg.appendChild(tilesGroup);
    svg.appendChild(labelsGroup);

    nodes.forEach((node) => {
        if (!(node.width > 1) || !(node.height > 1)) return;

        const themeHex = theme.length
            ? theme[leafIndex % theme.length]
            : defaultColor;
        if (!node.isHeader) leafIndex++;

        const fill = node.isHeader ? headerFill : tileColor(themeHex);

        const rect = document.createElementNS(svgNS, "rect");
        rect.setAttribute("x", node.x);
        rect.setAttribute("y", node.y);
        rect.setAttribute("width", node.width);
        rect.setAttribute("height", node.height);
        rect.setAttribute("rx", node.isHeader ? "3" : "4");
        rect.setAttribute("fill", fill);
        rect.setAttribute("stroke", border);
        rect.setAttribute("stroke-width", node.isHeader ? "1" : "1.25");
        if (typeof setDiagramSourceLine === 'function') {
            setDiagramSourceLine(rect, node.sourceLine || node.line);
        }
        tilesGroup.appendChild(rect);

        const minForLabel = node.isHeader ? 28 : 36;
        if (node.width < minForLabel || node.height < (node.isHeader ? 12 : 28)) return;

        const labelColor = node.isHeader
            ? muted
            : ((typeof getContrastColor === 'function') ? getContrastColor(fill) : textColor);

        if (node.isHeader) {
            let hdr = String(node.name || '');
            if (node.value != null && Number(node.value) > 0 && node.width >= 72) {
                hdr += ' · ' + formatTreemapValue(node.value);
                if (rootValue > 0 && node.width >= 110) {
                    const pct = Math.round((Number(node.value) / Number(rootValue)) * 1000) / 10;
                    hdr += ' · ' + pct + '%';
                }
            }
            const label = document.createElementNS(svgNS, "text");
            label.setAttribute("x", node.x + 10);
            label.setAttribute("y", node.y + Math.min(node.height - 4, 15));
            label.setAttribute("text-anchor", "start");
            label.setAttribute("fill", labelColor);
            label.setAttribute("font-weight", "600");
            label.setAttribute("font-size", "11px");
            label.setAttribute("data-label", node.name || '');
            label.textContent = truncateTreemapLabel(hdr, node.width - 14, 11);
            labelsGroup.appendChild(label);
            return;
        }

        const fontSize = node.width > 110 ? 12 : 11;
        const lineH = fontSize + 3;
        const valueLineH = 14;
        const padY = 6;
        const showValue = node.height >= 42 && node.width >= 52;
        const availH = node.height - padY * 2 - (showValue ? valueLineH + 4 : 0);
        const maxNameLines = Math.max(1, Math.floor(availH / lineH));
        const nameLines = fitTreemapWrappedLabel(
            node.name,
            node.width - 12,
            maxNameLines,
            fontSize
        );

        const blockH = nameLines.length * lineH + (showValue ? valueLineH + 4 : 0);
        let ty = node.y + (node.height - blockH) / 2 + fontSize;

        nameLines.forEach((line) => {
            const label = document.createElementNS(svgNS, "text");
            label.setAttribute("x", node.x + node.width / 2);
            label.setAttribute("y", ty);
            label.setAttribute("text-anchor", "middle");
            label.setAttribute("fill", labelColor);
            label.setAttribute("font-weight", "600");
            label.setAttribute("font-size", fontSize + "px");
            label.setAttribute("data-label", node.name || '');
            label.textContent = line;
            labelsGroup.appendChild(label);
            ty += lineH;
        });

        if (showValue) {
            ty += 4;
            const val = document.createElementNS(svgNS, "text");
            val.setAttribute("x", node.x + node.width / 2);
            val.setAttribute("y", ty);
            val.setAttribute("text-anchor", "middle");
            val.setAttribute("fill", labelColor);
            val.setAttribute("font-size", "11px");
            val.setAttribute("font-weight", "500");
            val.setAttribute("opacity", "0.78");
            let txt = formatTreemapValue(node.value);
            if (rootValue > 0 && node.height >= 56) {
                const pct = Math.round((Number(node.value) / Number(rootValue)) * 1000) / 10;
                txt += ' · ' + pct + '%';
            }
            val.textContent = txt;
            labelsGroup.appendChild(val);
        }
    });

    return {
        svg,
        width,
        height,
        svgString: new XMLSerializer().serializeToString(svg)
    };
}

function formatTreemapValue(v) {
    const n = Number(v);
    if (!isFinite(n)) return '';
    if (Math.abs(n - Math.round(n)) < 1e-9) return String(Math.round(n));
    return (Math.round(n * 100) / 100).toLocaleString('ru-RU');
}

function truncateTreemapLabel(text, maxPx, fontSize) {
    const s = String(text || '');
    const approx = fontSize * 0.62;
    const maxChars = Math.max(3, Math.floor(maxPx / approx));
    if (s.length <= maxChars) return s;
    return s.slice(0, Math.max(1, maxChars - 1)) + '…';
}

/** Перенос по словам, если высота позволяет; иначе обрезка последней строки. */
function fitTreemapWrappedLabel(text, maxPx, maxLines, fontSize) {
    const s = String(text || '').trim();
    if (!s) return [''];
    const linesCap = Math.max(1, maxLines | 0);
    if (typeof wrapTextLines === 'function') {
        const wrapped = wrapTextLines(s, Math.max(24, maxPx), fontSize);
        if (wrapped.length <= linesCap) return wrapped;
        const kept = wrapped.slice(0, linesCap);
        kept[linesCap - 1] = truncateTreemapLabel(kept[linesCap - 1], maxPx, fontSize);
        return kept;
    }
    return [truncateTreemapLabel(s, maxPx, fontSize)];
}

