            if (n.kind === 'external') {
                const tag = el('text', {
                    x: n.x + 10, y: n.y + 14, fill: muted, 'font-size': 9, 'font-weight': 700
                });
                tag.textContent = 'ВНЕШН.';
                g.appendChild(tag);
            } else if (n._role === 'service') {
                const tag = el('text', {
                    x: n.x + 10, y: n.y + 14, fill: muted, 'font-size': 9, 'font-weight': 700
                });
                tag.textContent = 'СЕРВИС';
                g.appendChild(tag);
            }
